  const seller = await MyGlobal.prisma.shopping_mall_ai_sellers.findFirst({
    where: {
      id: payload.id,
      is_active: true,
      verified: true
    },
  });

  if (!seller) {
    throw new ForbiddenException("You're not an active/verified seller or not enrolled.");
  }

  return payload;
}

