/**
 * Authenticates and verifies an admin user using JWT and database validation.
 * - Verifies the JWT token using jwtAuthorize function.
 * - Ensures payload type is "admin".
 * - Validates admin existence and is_active state in the database.
 * @throws ForbiddenException When payload type is not "admin" or DB validation fails.
 * @param request HTTP request containing headers with Bearer token.
 * @returns Authenticated AdminPayload
 */
export async function adminAuthorize(request: {
  headers: {
    authorization?: string;
  };
}): Promise<AdminPayload> {
  const payload: AdminPayload = jwtAuthorize({ request }) as AdminPayload;

  if (payload.type !== "admin") {
    throw new ForbiddenException(`You're not ${payload.type}`);
  }

  const admin = await MyGlobal.prisma.shopping_mall_ai_admins.findFirst({
    where: {
      id: payload.id,
      is_active: true,
    },
  });

  if (admin === null) {
    throw new ForbiddenException("You're not enrolled");
  }

  return payload;
}

