import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProduct";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Get a fully-detailed product by ID (shopping_mall_ai_products).
 *
 * This endpoint returns the full detail of a single active product for a
 * customer. Only products with 'active' status are visible to customers. All
 * audit and core fields are returned, and date/time fields are normalized as
 * RFC 3339 strings.
 *
 * @param props - Request props
 * @param props.customer - Authenticated customer for authorization context
 * @param props.shoppingMallAiProductId - UUID of the product to retrieve
 * @returns Full product detail as IShoppingMallAiProduct
 * @throws {Error} If the product is not found or is not visible to the customer
 */
export async function get__shopping_mall_ai_customer_shoppingMallAiProducts_$shoppingMallAiProductId(props: {
  customer: CustomerPayload;
  shoppingMallAiProductId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiProduct> {
  const { shoppingMallAiProductId } = props;

  const product = await MyGlobal.prisma.shopping_mall_ai_products.findFirst({
    where: {
      id: shoppingMallAiProductId,
      status: "active",
    },
  });
  if (!product) throw new Error("Product not found");
  return {
    id: product.id,
    shopping_mall_ai_seller_id: product.shopping_mall_ai_seller_id,
    shopping_mall_ai_product_category_id:
      product.shopping_mall_ai_product_category_id,
    title: product.title,
    description: product.description,
    price: product.price,
    status: product.status,
    sku: product.sku,
    created_at: toISOStringSafe(product.created_at),
    updated_at: toISOStringSafe(product.updated_at),
  };
}

