/**
 * Permanently deletes a product bundle by its unique identifier (UUID),
 * directly removing the record from the shopping_mall_ai_product_bundles table
 * without soft delete.
 *
 * This action is restricted to authenticated admins. Once deleted, the bundle
 * is unrecoverable. Access by non-admins is denied by the authentication
 * decorator, but this function also documents the expected error semantics.
 *
 * @param props - Admin: The authenticated admin payload (must be active).
 *   shoppingMallAiProductBundleId: UUID of the product bundle to delete.
 * @returns Void
 * @throws {Error} If the admin context is missing/invalid or product bundle
 *   does not exist, or if deletion is restricted by relational constraints.
 */
export async function delete__shopping_mall_ai_admin_shoppingMallAiProductBundles_$shoppingMallAiProductBundleId(props: {
  admin: AdminPayload;
  shoppingMallAiProductBundleId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { shoppingMallAiProductBundleId } = props;
  // NOTE: Robustness - decorator ensures admin is valid and active.
  await MyGlobal.prisma.shopping_mall_ai_product_bundles.delete({
    where: { id: shoppingMallAiProductBundleId },
  });
  return;
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductSnapshot";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Get a specific product snapshot by ID (shopping_mall_ai_product_snapshots).
 *
 * Retrieve detailed audit information for a single product snapshot using its
 * ID from shopping_mall_ai_product_snapshots. The response includes metadata,
 * full serialized product JSON, and information about the event that triggered
 * the snapshot (created, updated, deleted, etc).
 *
 * This is intended for platform administrators and compliance officers
 * investigating specific product histories or reconstructing prior product
 * states for regulatory review. Related operations may include restoring an old
 * snapshot or comparing states between two snapshots.
 *
 * Errors include not-found, unauthorized access, or invalid ID format.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated administrator requesting the snapshot
 *   details
 * @param props.shoppingMallAiProductSnapshotId - Unique identifier of the
 *   product snapshot record to retrieve
 * @returns The detailed audit snapshot information
 * @throws {Error} If admin authentication is missing, or the snapshot is not
 *   found
 */
export async function get__shopping_mall_ai_admin_shoppingMallAiProductSnapshots_$shoppingMallAiProductSnapshotId(props: {
  admin: AdminPayload;
  shoppingMallAiProductSnapshotId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiProductSnapshot> {
  // Authentication is enforced but revalidate for safety
  if (!props.admin)
    throw new Error("Unauthorized: Admin authentication required");

  const snapshot =
    await MyGlobal.prisma.shopping_mall_ai_product_snapshots.findUniqueOrThrow({
      where: {
        id: props.shoppingMallAiProductSnapshotId,
      },
    });

  return {
    id: snapshot.id,
    shopping_mall_ai_product_id: snapshot.shopping_mall_ai_product_id,
    action: snapshot.action,
    snapshot_json: snapshot.snapshot_json,
    created_at: toISOStringSafe(snapshot.created_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiFileAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFileAccessLog";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Get a single file access log entry by fileAccessLogId from
 * shopping_mall_ai_file_access_logs.
 *
 * Fetch metadata related to one file access log event identified by
 * fileAccessLogId (UUID). The shopping_mall_ai_file_access_logs table logs
 * every access event on files inside the shopping mall platform, including who
 * accessed which file, on what channel, what type of event occurred (e.g.,
 * DOWNLOAD, VIEW), its outcome, and access origin (IP, system).
 *
 * Data returned is restricted to authorized actors (admin, compliance auditor),
 * supporting granular monitoring for abnormal or suspicious usage. Unauthorized
 * access, not found, or restricted-log viewing attempts return error messages.
 * Log detail is essential for incident response, compliance monitoring, and
 * forensics.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin making the request
 *   (authorization handled by decorator)
 * @param props.fileAccessLogId - UUID for the file access log record to
 *   retrieve.
 * @returns Details of the requested file access event.
 * @throws {Error} When the file access log entry is not found or inaccessible
 */
export async function get__shopping_mall_ai_admin_shoppingMallAiFileAccessLogs_$fileAccessLogId(props: {
  admin: AdminPayload;
  fileAccessLogId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiFileAccessLog> {
  const { admin, fileAccessLogId } = props;
  const log =
    await MyGlobal.prisma.shopping_mall_ai_file_access_logs.findUnique({
      where: { id: fileAccessLogId },
    });
  if (!log) throw new Error("File access log not found");
  return {
    id: log.id,
    shopping_mall_ai_file_id: log.shopping_mall_ai_file_id,
    actor_type: log.actor_type ?? null,
    actor_id: log.actor_id ?? null,
    access_type: log.access_type,
    channel: log.channel,
    outcome: log.outcome,
    ip_address: log.ip_address,
    accessed_at: toISOStringSafe(log.accessed_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Get metadata details for a specific uploaded file by ID.
 *
 * Retrieves the metadata of a specific file by its unique identifier (UUID)
 * from the shopping_mall_ai_files table. The returned object contains detailed
 * information such as the file's URI, original name, MIME type, size, hash,
 * actor information, upload time, and deletion state.
 *
 * This operation supports compliance, audit, and asset-management requirements
 * by allowing admins to resolve issues, trace uploads, and verify asset
 * records. Access is restricted to admins due to the sensitive nature of file
 * information.
 *
 * Related endpoints include file asset listing, attachment lookups, and file
 * access audit logs. File content download must be handled through a secure
 * media CDN, not via this endpoint.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the request
 * @param props.shoppingMallAiFileId - Unique identifier of the file (UUID)
 * @returns The complete metadata of the file (IShoppingMallAiFile)
 * @throws {Error} When file is not found or admin is not authorized
 */
export async function get__shopping_mall_ai_admin_shoppingMallAiFiles_$shoppingMallAiFileId(props: {
  admin: AdminPayload;
  shoppingMallAiFileId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiFile> {
  const { admin, shoppingMallAiFileId } = props;
  // Admin presence and type are enforced by decorator, but double-check for contract clarity
  if (!admin || admin.type !== "admin") {
    throw new Error("Unauthorized: admin credentials required");
  }
  const file = await MyGlobal.prisma.shopping_mall_ai_files.findUnique({
    where: { id: shoppingMallAiFileId },
  });
  if (!file) throw new Error("File not found");
  return {
