 * (shopping_mall_ai_legal_consents).
 *
 * Retrieves a paginated list of all legal consent records in the system. Each
 * record ties a unique user (customer, seller, or admin) to a specific policy
 * document and version, per compliance requirements. The API supports typical
 * pagination and may be used in compliance dashboards or as the basis for bulk
 * audits by regulatory staff.
 *
 * Security is enforced: only users with appropriate administrative or
 * compliance roles can access the full consent registry. Sensitive user
 * information is safeguarded and audit logs are maintained for all access to
 * this endpoint.
 *
 * The operation directly reflects the structure of the
 * shopping_mall_ai_legal_consents table; no fields are omitted or denormalized.
 * Results are ordered for traceability and compliance reviews.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin issuing this request
 * @returns Paginated collection of legal consent records and pagination
 *   metadata
 * @throws {Error} When the admin is not authorized or database access fails
 */
export async function get__shopping_mall_ai_admin_legalConsents(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiLegalConsent> {
  // Default pagination (could be parameterized from request context)
  const page = 1;
  const limit = 100;
  // Count total number of consents
  const totalRecords =
    await MyGlobal.prisma.shopping_mall_ai_legal_consents.count();
  // Fetch paginated data
  const rows = await MyGlobal.prisma.shopping_mall_ai_legal_consents.findMany({
    orderBy: { consented_at: "desc" },
    skip: (page - 1) * limit,
    take: limit,
  });
  return {
    pagination: {
      current: page as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      limit: limit as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      records: totalRecords as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: Math.ceil(totalRecords / limit) as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data: rows.map((row) => ({
      id: row.id,
      user_id: row.user_id,
      policy_code: row.policy_code,
      policy_version: row.policy_version,
      consented_at: toISOStringSafe(row.consented_at),
      consent_method: row.consent_method,
      withdrawn_at: row.withdrawn_at ? toISOStringSafe(row.withdrawn_at) : null,
      consent_ip: row.consent_ip ?? null,
      deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
    })),
  };
