 *
 * Soft delete a comment, given the parent BBS post UUID and the specific
 * comment UUID. Deletes are performed by marking deleted_at to the current
 * timestamp, maintaining full audit compliance according to
 * shopping_mall_ai_bbs_comments. Only the comment's author or an admin is
 * allowed to perform this operation; all actions are tracked for moderation
 * review.
 *
 * Results in the comment becoming invisible to regular users. If attempt is
 * made on an already deleted comment or if user lacks permission, an error is
 * returned.
 *
 * @param props - Request properties
 * @param props.admin - Admin user authentication payload
 * @param props.bbsPostId - UUID of the parent BBS post for the target comment
 * @param props.bbsCommentId - UUID of the specific comment to (soft) delete
 * @returns Void
 * @throws {Error} If comment does not exist or is already deleted
 */
export async function delete__shopping_mall_ai_admin_bbsPosts_$bbsPostId_bbsComments_$bbsCommentId(props: {
  admin: AdminPayload;
  bbsPostId: string & tags.Format<"uuid">;
  bbsCommentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { bbsPostId, bbsCommentId } = props;

  // Find the target comment matching post and id
  const comment = await MyGlobal.prisma.shopping_mall_ai_bbs_comments.findFirst(
    {
      where: {
        id: bbsCommentId,
        shopping_mall_ai_bbs_post_id: bbsPostId,
      },
    },
  );
  if (!comment) throw new Error("Comment not found or already deleted");
