  // Soft-delete by setting deleted_at to now
  await MyGlobal.prisma.shopping_mall_ai_bbs_comments.update({
    where: { id: bbsCommentId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
  // No return value needed (void)
}

