import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Register new uploaded file metadata.
 *
 * This endpoint creates a new record in shopping_mall_ai_files after a file
 * upload in the shopping mall platform. It strictly enforces deduplication by
 * file hash, audits all inserts, and supports role-based access for
 * authenticated customers. The returned object provides a complete,
 * audit-traceable record including original name, storage URI, type, size, and
 * uploader reference.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer making the request
 * @param props.body - File metadata to be registered (original_name, uri,
 *   extension, mime_type, size, hash, optional actor_type and actor_id)
 * @returns Registered file metadata record matching IShoppingMallAiFile
 * @throws {Error} If the file hash already exists (duplicates not allowed)
 */
export async function post__shopping_mall_ai_customer_shoppingMallAiFiles(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiFile.ICreate;
}): Promise<IShoppingMallAiFile> {
  const { body } = props;

  // Deduplication: ensure no file with this hash exists that is not deleted
  const existing = await MyGlobal.prisma.shopping_mall_ai_files.findFirst({
    where: {
      hash: body.hash,
      deleted_at: null,
    },
  });
  if (existing) {
    throw new Error(
      "A file with this hash already exists in the system (deduplication enforced).",
    );
  }

  // Fully prepare values
  const newId = v4();
  const now = toISOStringSafe(new Date());

  const created = await MyGlobal.prisma.shopping_mall_ai_files.create({
    data: {
      id: newId,
      original_name: body.original_name,
      uri: body.uri,
      extension: body.extension,
      mime_type: body.mime_type,
      size: body.size,
      hash: body.hash,
      actor_type: body.actor_type ?? null,
      actor_id: body.actor_id ?? null,
      created_at: now,
      deleted_at: null,
    },
  });

  return {
    id: created.id,
    original_name: created.original_name,
    uri: created.uri,
    extension: created.extension,
    mime_type: created.mime_type,
    size: created.size,
    hash: created.hash,
    actor_type: created.actor_type,
    actor_id: created.actor_id,
    created_at: toISOStringSafe(created.created_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

