/**
 * Completely removes a shopping cart from the database by its cartId (hard
 * delete).
 *
 * This operation deletes the cart and all related records via schema cascade
 * (items, sessions, etc). Admins may delete any cart.
 *
 * @param props - The function parameters.
 * @param props.admin - The authenticated admin performing the deletion. Must be
 *   active and authorized.
 * @param props.cartId - The unique cart identifier to delete (UUID).
 * @returns Void
 * @throws {Error} If the cart does not exist (404 Not Found).
 */
export async function delete__shopping_mall_ai_admin_carts_$cartId(props: {
  admin: AdminPayload;
  cartId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { cartId } = props;
  try {
    await MyGlobal.prisma.shopping_mall_ai_carts.delete({
      where: { id: cartId },
    });
  } catch (error) {
    // Prisma error code P2025 means record not found
