import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Soft delete a product review by reviewId (audit/retain for compliance).
 *
 * Marks a product review as deleted by populating deleted_at. Only allowed for
 * authenticated admins (role enforced by AdminAuth decorator). Sellers and
 * general users cannot remove reviews via this endpoint. Deleted reviews are
 * hidden from standard queries.
 *
 * This operation is fully auditable and retains records as per compliance.
 * Success is indicated by empty return (void) or HTTP 204 No Content.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the delete operation
 * @param props.reviewId - ReviewId to soft-delete (UUID)
 * @returns Void (success)
 * @throws {Error} If the review is not found (404 Error)
 */
export async function delete__shopping_mall_ai_admin_reviews_$reviewId(props: {
  admin: AdminPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { reviewId } = props;

  // Find the review: throw 404 if not found
  const review = await MyGlobal.prisma.shopping_mall_ai_reviews.findUnique({
    where: { id: reviewId },
    select: { id: true, deleted_at: true },
  });
  if (!review) throw new Error("Review not found");

  // Idempotent: if already deleted, don't update
  if (review.deleted_at) return;

  // Update with current timestamp for soft delete (never use Date type directly)
  const deletedAt: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(),
  );
  await MyGlobal.prisma.shopping_mall_ai_reviews.update({
    where: { id: reviewId },
    data: { deleted_at: deletedAt },
  });
}

