import { IShoppingMallAiCartSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartSession";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Retrieves a paginated, filterable list of cart session records for admin
 * users.
 *
 * This endpoint provides an internal admin-only view for analyzing,
 * troubleshooting, and listing active cart sessions from the
 * shopping_mall_ai_cart_sessions table. Sessions are paginated and can be
 * filtered/scoped for operational workflows (future upgrade).
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin performing the operation
 * @returns Paginated list of cart sessions and page meta
 * @throws {Error} When access is attempted by a non-admin user
 */
export async function get__shopping_mall_ai_admin_cartSessions(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiCartSession> {
  const { admin } = props;
  const page = 1;
  const limit = 100;
  const skip = (page - 1) * limit;

  // Count total cart session records
  const total = await MyGlobal.prisma.shopping_mall_ai_cart_sessions.count();

  // Fetch cart session page
  const sessions =
    await MyGlobal.prisma.shopping_mall_ai_cart_sessions.findMany({
      skip,
      take: limit,
