/**
 * Retrieve metadata for a single file attachment as identified by
 * fileAttachmentId (UUID).
 *
 * This endpoint looks up a file attachment record by its unique ID, verifies
 * the requesting customer is authorized to view it (by checking that they are
 * the owner of the underlying uploaded file), and returns the full attachment
 * linkage metadata.
 *
 * Customers may only view attachments that are linked to their own files.
 * Attempts to access unrelated or non-existent attachments will result in
 * appropriate error responses.
 *
 * @param props - Request parameter object
 * @param props.customer - Authenticated customer payload
 * @param props.fileAttachmentId - UUID for the file attachment record to
 *   retrieve
 * @returns IShoppingMallAiFileAttachment details
 * @throws {Error} If the file attachment does not exist
 * @throws {Error} If the authenticated customer does not own the underlying
 *   file
 */
export async function get__shopping_mall_ai_customer_shoppingMallAiFileAttachments_$fileAttachmentId(props: {
  customer: CustomerPayload;
  fileAttachmentId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiFileAttachment> {
  const { customer, fileAttachmentId } = props;
  // First, fetch the attachment record by ID
  const attachment =
    await MyGlobal.prisma.shopping_mall_ai_file_attachments.findUnique({
      where: { id: fileAttachmentId },
    });
  if (!attachment) throw new Error("File attachment not found");

  // If associated with a file, check file ownership (customer must own the file)
  if (attachment.shopping_mall_ai_file_id) {
    const file = await MyGlobal.prisma.shopping_mall_ai_files.findUnique({
      where: { id: attachment.shopping_mall_ai_file_id },
    });
    if (!file) throw new Error("Underlying file not found");
    if (file.actor_type !== "customer" || file.actor_id !== customer.id) {
      throw new Error("Permission denied: customer does not own this file");
    }
  } else {
    // For non-file attachments, deny access (authorization for generic target_type not supported in this endpoint)
    throw new Error(
      "Permission denied: unable to validate file ownership for this attachment type",
    );
  }

  return {
    id: attachment.id,
    shopping_mall_ai_file_id: attachment.shopping_mall_ai_file_id ?? null,
    shopping_mall_ai_media_asset_id:
      attachment.shopping_mall_ai_media_asset_id ?? null,
    target_type: attachment.target_type,
    target_id: attachment.target_id,
    attached_at: toISOStringSafe(attachment.attached_at),
  };
}

