/**
 * Lists all items in a shopping cart (admin).
 *
 * Fetches all items (products, options, quantities) for the specified cartId.
 * Each item includes all primary fields from shopping_mall_ai_cart_items with
 * audit details. Throws 404 if the cart does not exist. Admin authorization
 * required (broad access).
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin payload (authorization enforced)
 * @param props.cartId - UUID of the parent shopping cart to inspect
 * @returns Paginated list of items in the cart, including all audit/history
 *   details
 * @throws {Error} When the cart with the specified id does not exist
 */
export async function get__shopping_mall_ai_admin_carts_$cartId_cartItems(props: {
  admin: AdminPayload;
  cartId: string & tags.Format<"uuid">;
}): Promise<IPageIShoppingMallAiCartItem> {
  const { admin, cartId } = props;

  // Step 1: Ensure the cart exists (404 if not)
  const cart = await MyGlobal.prisma.shopping_mall_ai_carts.findUnique({
    where: { id: cartId },
    select: { id: true },
  });
  if (!cart) throw new Error("Cart not found");

  // Step 2: Fetch all items for this cart
  const items = await MyGlobal.prisma.shopping_mall_ai_cart_items.findMany({
    where: { shopping_mall_ai_cart_id: cartId },
    orderBy: { added_at: "asc" },
  });

  // Step 3: Map to IShoppingMallAiCartItem DTO (convert dates)
  const data = items.map((item) => ({
    id: item.id as string & tags.Format<"uuid">,
    shopping_mall_ai_cart_id: item.shopping_mall_ai_cart_id as string &
      tags.Format<"uuid">,
