        item.shopping_mall_ai_product_option_id as string & tags.Format<"uuid">,
    }),
    quantity: item.quantity,
    added_at: toISOStringSafe(item.added_at),
    updated_at: toISOStringSafe(item.updated_at),
  }));

  // Step 4: Construct pagination object
  const total = data.length;
  return {
    pagination: {
      current: 1 as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      limit: total as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      records: total as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: 1 as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data,
  };
}

