import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Erase (hard delete) an order item from a specific order (admin only).
 *
 * This operation permanently removes a specified order item from a parent
 * order. Only admins (as authorized by AdminAuth) may perform this action. The
 * deletion is enforced as a hard delete because the schema does not support
 * soft delete or retention. Referential integrity is strictly checked: the
 * specified item must exist and must belong to the given parent order. The
 * parent order must not be in an immutable status (e.g., 'completed'); such
 * orders are protected from item deletion.
 *
 * Throws an error if the order item or order does not exist, or if deletion is
 * not permissible due to business state constraints.
 *
 * @param props - Properties for the deletion operation
 * @param props.admin - The authenticated admin performing the deletion
 * @param props.orderId - The parent order's UUID
 * @param props.orderItemId - The order item UUID to be deleted
 * @returns Void (no return on success)
 * @throws {Error} When the order item does not exist
 * @throws {Error} When the order item does not belong to the indicated parent
 *   order
 * @throws {Error} When the parent order does not exist
 * @throws {Error} When deletion is forbidden due to immutable order status
 *   (e.g., completed)
 */
export async function delete__shopping_mall_ai_admin_orders_$orderId_orderItems_$orderItemId(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  orderItemId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, orderId, orderItemId } = props;

  // 1. Fetch order item and check existance and referential integrity
  const orderItem =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findUnique({
      where: { id: orderItemId },
    });
  if (!orderItem) throw new Error("Order item not found");
  if (orderItem.shopping_mall_ai_order_id !== orderId) {
    throw new Error("Order item does not belong to the provided order");
  }

  // 2. Fetch parent order and validate mutable state
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
  });
  if (!order) throw new Error("Order not found");
  if (order.status === "completed") {
    throw new Error("Cannot delete items from a completed order");
  }

  // 3. Perform hard delete of the order item
  await MyGlobal.prisma.shopping_mall_ai_order_items.delete({
    where: { id: orderItemId },
  });

  // 4. Return void
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
