import { IShoppingMallAiInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInventory";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Updates a product inventory record by UUID.
 *
 * Only the seller who owns the underlying product may update the inventory.
 * Performs all business validations: quantity and reserved_quantity must be
 * non-negative and reserved_quantity must not exceed available quantity. Audits
 * update time.
 *
 * @param props.seller Authenticated seller payload
 * @param props.shoppingMallAiInventoryId UUID of inventory row to update
 * @param props.body Update object (fields are patchable)
 * @returns Updated inventory object
 * @throws {Error} If seller does not own inventory row or if validation fails
 */
export async function put__shopping_mall_ai_seller_shoppingMallAiInventories_$shoppingMallAiInventoryId(props: {
  seller: SellerPayload;
  shoppingMallAiInventoryId: string & tags.Format<"uuid">;
  body: IShoppingMallAiInventory.IUpdate;
}): Promise<IShoppingMallAiInventory> {
  const { seller, shoppingMallAiInventoryId, body } = props;

  // Fetch inventory with associated product for seller check
  const inventory =
    await MyGlobal.prisma.shopping_mall_ai_inventories.findUnique({
      where: { id: shoppingMallAiInventoryId },
      include: { product: true },
    });
  if (!inventory) throw new Error("Inventory not found");
  if (
    !inventory.product ||
    inventory.product.shopping_mall_ai_seller_id !== seller.id
  ) {
    throw new Error("Unauthorized: seller does not own this inventory");
  }

  // Enforce business rules
  if (body.quantity !== undefined && body.quantity < 0) {
    throw new Error("Quantity cannot be negative");
  }
  if (body.reserved_quantity !== undefined && body.reserved_quantity < 0) {
    throw new Error("Reserved quantity cannot be negative");
  }

  // Compare against new/old values for reserved <= quantity
  const newQuantity =
    body.quantity !== undefined ? body.quantity : inventory.quantity;
  const newReserved =
    body.reserved_quantity !== undefined
      ? body.reserved_quantity
      : inventory.reserved_quantity;
  if (newReserved > newQuantity) {
    throw new Error("Reserved quantity cannot exceed available quantity");
  }

  // Update operation
  const updated = await MyGlobal.prisma.shopping_mall_ai_inventories.update({
    where: { id: shoppingMallAiInventoryId },
    data: {
      shopping_mall_ai_product_id:
        body.shopping_mall_ai_product_id ?? undefined,
      shopping_mall_ai_product_option_id:
        body.shopping_mall_ai_product_option_id ?? undefined,
      quantity: body.quantity ?? undefined,
      reserved_quantity: body.reserved_quantity ?? undefined,
      restock_at: body.restock_at ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });
  // Normalize output types as required (toISOStringSafe for all dates)
  return {
    id: updated.id,
    shopping_mall_ai_product_id: updated.shopping_mall_ai_product_id,
    shopping_mall_ai_product_option_id:
      updated.shopping_mall_ai_product_option_id ?? null,
    quantity: updated.quantity,
    reserved_quantity: updated.reserved_quantity,
    restock_at: updated.restock_at ? toISOStringSafe(updated.restock_at) : null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

