  shoppingMallAiProductOptionId: string & tags.Format<"uuid">;
  body: IShoppingMallAiProductOption.IUpdate;
}): Promise<IShoppingMallAiProductOption> {
  const { admin, shoppingMallAiProductOptionId, body } = props;

  // 1. Fetch the product option to ensure it exists
  const option =
    await MyGlobal.prisma.shopping_mall_ai_product_options.findUnique({
      where: { id: shoppingMallAiProductOptionId },
    });
  if (!option) throw new Error("Product option not found");

  // 2. Only update mutable fields; treat null as undefined (schema expects string)
  const now = toISOStringSafe(new Date());
  try {
    const updated =
      await MyGlobal.prisma.shopping_mall_ai_product_options.update({
        where: { id: shoppingMallAiProductOptionId },
        data: {
          name: body.name ?? undefined,
          value: body.value ?? undefined,
