      option_sku: updated.option_sku,
      created_at: toISOStringSafe(updated.created_at),
      updated_at: now,
    };
  } catch (err: unknown) {
    // Catch unique constraint errors (P2002: Unique constraint failed)
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
