 *
 * Admin-only endpoint to update product snapshot metadata in
 * shopping_mall_ai_product_snapshots. Only the action field (label/metadata)
 * may be changed; the historical serialized product state in snapshot_json is
 * strictly immutable for compliance and audit. Throws if any attempt is made to
 * alter snapshot_json or immutable fields.
 *
 * @param props - Admin: Authenticated platform admin
 *   shoppingMallAiProductSnapshotId: The UUID of the snapshot to update body:
 *   Metadata update payload. Only action is mutable, snapshot_json must remain
 *   unchanged or error will be thrown
 * @returns The updated product snapshot metadata
 * @throws {Error} If not found, unauthorized, or mutation of immutable fields
 *   attempted
 */
export async function put__shopping_mall_ai_admin_shoppingMallAiProductSnapshots_$shoppingMallAiProductSnapshotId(props: {
  admin: AdminPayload;
  shoppingMallAiProductSnapshotId: string & tags.Format<"uuid">;
  body: IShoppingMallAiProductSnapshot.IUpdate;
}): Promise<IShoppingMallAiProductSnapshot> {
  const { admin, shoppingMallAiProductSnapshotId, body } = props;

  // Authorization: Platform admin required, field presence and current decorator guarantee enforced externally
  // (If additional checks required - e.g., admin privilege escalation, add them here)

  // Fetch the snapshot (throws if not found)
  const snapshot =
    await MyGlobal.prisma.shopping_mall_ai_product_snapshots.findUnique({
      where: { id: shoppingMallAiProductSnapshotId },
    });
  if (!snapshot) throw new Error("Product snapshot not found");

  // Forbid any modification of snapshot_json (immutability: must match exactly)
  if (body.snapshot_json !== snapshot.snapshot_json) {
    throw new Error(
      "Modification of snapshot_json is forbidden for compliance reasons",
    );
