  if (body.action !== snapshot.action) {
    updated = await MyGlobal.prisma.shopping_mall_ai_product_snapshots.update({
      where: { id: shoppingMallAiProductSnapshotId },
      data: { action: body.action },
    });
  }

  // Transform to API type and normalize timestamp
  return {
    id: updated.id,
    shopping_mall_ai_product_id: updated.shopping_mall_ai_product_id,
    action: updated.action,
    snapshot_json: updated.snapshot_json,
    created_at: toISOStringSafe(updated.created_at),
