/**
 * Delete a product inventory record (hard delete,
 * shopping_mall_ai_inventories).
 *
 * Deletes an inventory record from the shopping_mall_ai_inventories table using
 * its UUID as primary key. This is a hard delete operation: as the table lacks
 * 'deleted_at' or 'is_deleted', the record is permanently erased. Only the
 * seller who owns the product associated with the inventory can perform this
 * operation.
 *
 * Common scenarios: cleaning up legacy/test inventories, removing orphaned
 * records, resolving audit discrepancies.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the deletion
 * @param props.shoppingMallAiInventoryId - UUID of the inventory record for
 *   hard deletion
 * @returns Void
 * @throws {Error} If the inventory does not exist
 * @throws {Error} If the inventory is not owned by the seller (authorization
 *   failure)
 */
export async function delete__shopping_mall_ai_seller_shoppingMallAiInventories_$shoppingMallAiInventoryId(props: {
  seller: SellerPayload;
  shoppingMallAiInventoryId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, shoppingMallAiInventoryId } = props;

  // 1. Fetch inventory with its associated product
  const inventory =
    await MyGlobal.prisma.shopping_mall_ai_inventories.findUnique({
      where: { id: shoppingMallAiInventoryId },
      include: { product: true },
    });

  if (!inventory) {
    throw new Error("Inventory not found");
  }

  // 2. Check that the seller owns the product associated with this inventory
  if (inventory.product.shopping_mall_ai_seller_id !== seller.id) {
    throw new Error("Unauthorized: You can only delete your own inventories");
  }

  // 3. Hard delete the inventory
  await MyGlobal.prisma.shopping_mall_ai_inventories.delete({
    where: { id: shoppingMallAiInventoryId },
  });
}

