/**
 * Retrieve metadata for a specific media asset file variant belonging to the
 * customer.
 *
 * Fetches metadata for the given media asset (via its mediaAssetId) only if:
 *
 * - The asset exists (404 if not)
 * - It relates to a file owned by this customer (actor_type == 'customer' and
 *   actor_id == customer.id; else forbidden)
 * - The file is not soft-deleted (404 if deleted)
 *
 * This ensures customers can only access metadata for their own files and
 * protects privacy and data retention compliance.
 *
 * @param props
 * @param props.customer - The authenticated customer for access/ownership
 *   enforcement.
 * @param props.mediaAssetId - UUID of the media asset to retrieve.
 * @returns The IShoppingMallAiMediaAsset metadata for this variant if access is
 *   allowed.
 * @throws {Error} If asset does not exist or is not owned by this customer, or
 *   is deleted. Error is 404 for not found/deleted and 403 for not owned.
 */
export async function get__shopping_mall_ai_customer_shoppingMallAiMediaAssets_$mediaAssetId(props: {
  customer: CustomerPayload;
  mediaAssetId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiMediaAsset> {
  const { customer, mediaAssetId } = props;

  // Step 1: Fetch asset (not found => 404)
  const asset = await MyGlobal.prisma.shopping_mall_ai_media_assets.findUnique({
    where: { id: mediaAssetId },
  });
  if (!asset) throw new Error("Media asset not found");

  // Step 2: Fetch file (not found => 404)
  const file = await MyGlobal.prisma.shopping_mall_ai_files.findUnique({
    where: { id: asset.shopping_mall_ai_file_id },
  });
  if (!file) throw new Error("File not found");
  if (file.deleted_at !== null && file.deleted_at !== undefined) {
    throw new Error("Media asset is deleted");
  }
  if (file.actor_type !== "customer" || file.actor_id !== customer.id) {
    throw new Error("Forbidden: asset not owned by this customer");
  }

  return {
    id: asset.id,
    shopping_mall_ai_file_id: asset.shopping_mall_ai_file_id,
    asset_type: asset.asset_type,
    asset_uri: asset.asset_uri,
    width: asset.width ?? null,
    height: asset.height ?? null,
    duration: asset.duration ?? null,
    created_at: toISOStringSafe(asset.created_at),
  };
}

