/**
 * Soft delete a comment on a BBS forum post (shopping_mall_ai_bbs_comments).
 *
 * Soft delete a comment, given the parent BBS post UUID and the specific
 * comment UUID. Deletes are performed by marking deleted_at to the current
 * timestamp, maintaining full audit compliance according to
 * shopping_mall_ai_bbs_comments. Only the comment's author or an admin is
 * allowed to perform this operation; all actions are tracked for moderation
 * review.
 *
 * Results in the comment becoming invisible to regular users. If attempt is
 * made on an already deleted comment or if user lacks permission, an error is
 * returned.
 *
 * @param props - Operation properties
 * @param props.customer - Authenticated customer payload
 * @param props.bbsPostId - UUID of parent BBS post for the target comment
 * @param props.bbsCommentId - UUID of specific comment to (soft) delete
 * @returns Void
 * @throws {Error} When comment not found, already deleted, not owned by
 *   customer, or doesn't belong to specified post
 */
export async function delete__shopping_mall_ai_customer_bbsPosts_$bbsPostId_bbsComments_$bbsCommentId(props: {
  customer: CustomerPayload;
  bbsPostId: string & tags.Format<"uuid">;
  bbsCommentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, bbsPostId, bbsCommentId } = props;

  // 1. Fetch target comment
  const comment =
    await MyGlobal.prisma.shopping_mall_ai_bbs_comments.findUnique({
      where: { id: bbsCommentId },
