/**
 * Registers a new product in the catalog by inserting a row into the
 * shopping_mall_ai_products table.
 *
 * Only authenticated admins can execute this. This function validates that the
 * referenced seller and product category exist, ensures SKU uniqueness for the
 * chosen seller, then creates and returns the product record with all audit
 * fields set.
 *
 * @param props - The request object with authenticated admin and product
 *   creation body.
 * @param props.admin - Authenticated AdminPayload. Only admins may create
 *   products with this endpoint.
 * @param props.body - Required product fields—category, title, description,
 *   price, status, sku.
 * @returns The new product entity, containing audit timestamps and PK/FK
 *   values.
 * @throws {Error} If the referenced category or seller is missing.
 * @throws {Error} If the SKU is not unique for the seller.
 */
export async function post__shopping_mall_ai_admin_shoppingMallAiProducts(props: {
  admin: AdminPayload;
  body: IShoppingMallAiProduct.ICreate;
}): Promise<IShoppingMallAiProduct> {
  const { admin, body } = props;
  // Validate category exists
  await MyGlobal.prisma.shopping_mall_ai_product_categories.findUniqueOrThrow({
    where: { id: body.shopping_mall_ai_product_category_id },
    select: { id: true },
  });

  // Validate seller exists
  await MyGlobal.prisma.shopping_mall_ai_sellers.findUniqueOrThrow({
    where: { id: body.shopping_mall_ai_seller_id },
    select: { id: true },
  });

  // Enforce SKU uniqueness for seller
  const existingSku = await MyGlobal.prisma.shopping_mall_ai_products.findFirst(
    {
      where: {
        sku: body.sku,
        shopping_mall_ai_seller_id: body.shopping_mall_ai_seller_id,
      },
      select: { id: true },
    },
  );
  if (existingSku) throw new Error("SKU already exists for this seller");

  const now = toISOStringSafe(new Date());
  const result = await MyGlobal.prisma.shopping_mall_ai_products.create({
    data: {
      id: v4(),
      shopping_mall_ai_seller_id: body.shopping_mall_ai_seller_id,
      shopping_mall_ai_product_category_id:
        body.shopping_mall_ai_product_category_id,
      title: body.title,
      description: body.description,
      price: body.price,
      status: body.status,
      sku: body.sku,
      created_at: now,
      updated_at: now,
    },
  });

  return {
    id: result.id,
    shopping_mall_ai_seller_id: result.shopping_mall_ai_seller_id,
    shopping_mall_ai_product_category_id:
      result.shopping_mall_ai_product_category_id,
    title: result.title,
    description: result.description,
    price: result.price,
    status: result.status,
    sku: result.sku,
    created_at: toISOStringSafe(result.created_at),
    updated_at: toISOStringSafe(result.updated_at),
  };
}

