import { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Retrieve all metadata for a single uploaded file by its unique fileId (UUID),
 * restricting access so only the uploading customer can access metadata.
 *
 * Only the customer that uploaded the file (actor_type=="customer", actor_id
 * matches CustomerPayload.id) may access the metadata. Audit and soft-delete
 * (deleted_at) fields are included in the response per business requirements.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer (CustomerPayload)
 * @param props.fileId - File UUID to retrieve
 * @returns File metadata matching IShoppingMallAiFile
 * @throws {Error} When file is not found, deleted, or the customer is not the
 *   file's owner
 */
export async function get__shopping_mall_ai_customer_shoppingMallAiFiles_$fileId(props: {
  customer: CustomerPayload;
  fileId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiFile> {
  const { customer, fileId } = props;
  const file = await MyGlobal.prisma.shopping_mall_ai_files.findFirst({
    where: { id: fileId },
    select: {
      id: true,
      original_name: true,
      uri: true,
      extension: true,
      mime_type: true,
      size: true,
      hash: true,
      actor_type: true,
      actor_id: true,
      created_at: true,
      deleted_at: true,
    },
  });
  if (!file) throw new Error("File not found");
  if (file.actor_type !== "customer" || file.actor_id !== customer.id) {
    throw new Error("Permission denied: You are not the file's owner");
  }
  return {
    id: file.id,
    original_name: file.original_name,
    uri: file.uri,
    extension: file.extension,
    mime_type: file.mime_type,
    size: file.size,
    hash: file.hash,
    actor_type: file.actor_type ?? null,
    actor_id: file.actor_id ?? null,
    created_at: toISOStringSafe(file.created_at),
    deleted_at: file.deleted_at ? toISOStringSafe(file.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
