import { IShoppingMallAiPolicyChange } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiPolicyChange";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Update a policy change/version record (DB: shopping_mall_ai_policy_changes).
 *
 * Allows an admin to update the details of a compliance policy change/version
 * audit record. Fields may be corrected (summary, version, approver, approval
 * date, etc), subject to validation. Throws 404 if the specified record does
 * not exist. Does not use native Date anywhere; all datetime values are handled
 * as ISO 8601 branded strings. Only mutable by authenticated admin users as per
 * compliance policy.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the operation
 * @param props.policyChangeId - UUID of the policy change/version to update
 * @param props.body - Fields to update in the policy/version record
 * @returns The updated policy change/version record, after mutation
 * @throws {Error} When the policy change/version record does not exist
 */
export async function put__shopping_mall_ai_admin_policyChanges_$policyChangeId(props: {
  admin: AdminPayload;
  policyChangeId: string & tags.Format<"uuid">;
  body: IShoppingMallAiPolicyChange.IUpdate;
}): Promise<IShoppingMallAiPolicyChange> {
  const { policyChangeId, body } = props;

  // 1. Fetch the existing record (throws 404 if missing)
  const current =
    await MyGlobal.prisma.shopping_mall_ai_policy_changes.findUnique({
      where: { id: policyChangeId },
    });
  if (!current) throw new Error("Policy change/version record not found");

  // 2. Update only the provided fields (date handling as ISO strings)
  const updated = await MyGlobal.prisma.shopping_mall_ai_policy_changes.update({
    where: { id: policyChangeId },
    data: {
      policy_code: body.policy_code ?? undefined,
      policy_version: body.policy_version ?? undefined,
      change_summary: body.change_summary ?? undefined,
      approved_by: body.approved_by ?? undefined,
      approved_at: body.approved_at
        ? toISOStringSafe(body.approved_at)
        : undefined,
      previous_version:
        body.previous_version !== undefined ? body.previous_version : undefined,
      deleted_at:
        body.deleted_at === null
          ? null
          : body.deleted_at
            ? toISOStringSafe(body.deleted_at)
            : undefined,
    },
  });

  // 3. Map updated record to API DTO, ensuring all date types are correct
  return {
    id: updated.id,
    policy_code: updated.policy_code,
    policy_version: updated.policy_version,
    change_summary: updated.change_summary,
    approved_by: updated.approved_by,
    approved_at: toISOStringSafe(updated.approved_at),
    previous_version: updated.previous_version ?? null,
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

