/**
 * Get a specific payment record for an order (shopping_mall_ai_payments).
 *
 * This endpoint returns all atomic fields of a payment record attached to a
 * specified order, including method (card, deposit, coupon, etc.), status,
 * amount, and all audit timestamps. Only the order's owning customer can access
 * their payment records. Throws error if unauthorized or not found.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer payload (for RBAC)
 * @param props.orderId - Parent order ID for the payment
 * @param props.paymentId - ID of the payment to retrieve
 * @returns Detailed payment record if found and authorized
 * @throws {Error} If the record does not exist or the customer is unauthorized
 */
export async function get__shopping_mall_ai_customer_orders_$orderId_payments_$paymentId(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  paymentId: string & tags.Format<"uuid">;
}): Promise<IShoppingPayment> {
  const { customer, orderId, paymentId } = props;

  // Find payment by both ID (UUID PK) and order linkage. Include order customer for RBAC check.
  const payment = await MyGlobal.prisma.shopping_mall_ai_payments.findFirst({
    where: {
      id: paymentId,
      shopping_mall_ai_order_id: orderId,
    },
    select: {
      id: true,
      shopping_mall_ai_order_id: true,
      shopping_mall_ai_channel_id: true,
      method: true,
      status: true,
      amount: true,
      initiated_at: true,
      resolved_at: true,
      order: {
        select: {
          shopping_mall_ai_customer_id: true,
        },
      },
    },
  });

  if (!payment) throw new Error("Payment record not found");
  if (payment.order.shopping_mall_ai_customer_id !== customer.id) {
    throw new Error("Unauthorized: Payment does not belong to this customer");
  }

  return {
    id: payment.id,
    shopping_mall_ai_order_id: payment.shopping_mall_ai_order_id,
    shopping_mall_ai_channel_id: payment.shopping_mall_ai_channel_id,
    method: payment.method,
    status: payment.status,
    amount: payment.amount,
    initiated_at: toISOStringSafe(payment.initiated_at),
    resolved_at: payment.resolved_at
      ? toISOStringSafe(payment.resolved_at)
      : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IPageIShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiCartItem";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Retrieves all items associated with a particular shopping cart.
 *
 * This endpoint returns all cart item records for a given cartId, enforcing
 * ownership: only the owning customer can view cart contents. Throws an error
 * if the cart does not exist or the current user is not the owner. Each
 * returned item includes all cart item fields and audit timestamps formatted as
 * required.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer making the request
 *   (authorization enforced)
 * @param props.cartId - Unique identifier for the shopping cart
 * @returns Paginated object with all cart items for this cart
 * @throws {Error} If cart not found
 * @throws {Error} If requester is not the cart's owner
 */
export async function get__shopping_mall_ai_customer_carts_$cartId_cartItems(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
}): Promise<IPageIShoppingMallAiCartItem> {
  const { customer, cartId } = props;

  // Step 1: Fetch the cart by id
  const cart = await MyGlobal.prisma.shopping_mall_ai_carts.findUnique({
    where: { id: cartId },
  });
  if (!cart) throw new Error("Cart not found");

  // Step 2: Enforce ownership: only the owning customer may access
  if (
    !cart.shopping_mall_ai_customer_id ||
    cart.shopping_mall_ai_customer_id !== customer.id
  ) {
    throw new Error("Forbidden: You do not own this cart");
  }

  // Step 3: Fetch all items in the cart
  const items = await MyGlobal.prisma.shopping_mall_ai_cart_items.findMany({
    where: { shopping_mall_ai_cart_id: cartId },
    orderBy: { added_at: "asc" },
  });

  // Step 4: Map items to IShoppingMallAiCartItem (date conversion, optional option_id)
  const rows = items.map((item) => {
    const result: IShoppingMallAiCartItem = {
      id: item.id,
      shopping_mall_ai_cart_id: item.shopping_mall_ai_cart_id,
      shopping_mall_ai_product_id: item.shopping_mall_ai_product_id,
      quantity: item.quantity,
      added_at: toISOStringSafe(item.added_at),
      updated_at: toISOStringSafe(item.updated_at),
    };
    if (
      item.shopping_mall_ai_product_option_id !== null &&
      item.shopping_mall_ai_product_option_id !== undefined
    ) {
      result.shopping_mall_ai_product_option_id =
        item.shopping_mall_ai_product_option_id;
    }
    return result;
  });

  // Build pagination: single page, all items
  const pagination = {
    current: 1,
    limit: rows.length,
    records: rows.length,
    pages: 1,
  };

  return { pagination, data: rows };
}

