        actor_id: true,
        actor_role: true,
        operation: true,
        detail: true,
        occurred_at: true,
        context: true,
        deleted_at: true,
      },
    });
  // Return mapped DTO object
  return {
    id: log.id,
    entity_type: log.entity_type,
    entity_id: log.entity_id,
    actor_id: log.actor_id ?? null,
    actor_role: log.actor_role,
    operation: log.operation,
    detail: log.detail,
    occurred_at: toISOStringSafe(log.occurred_at),
    context: log.context ?? null,
    deleted_at: log.deleted_at ? toISOStringSafe(log.deleted_at) : null,
