import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Create a new content moderation event log record as an admin.
 *
 * This function inserts a new record into shopping_mall_ai_content_moderations,
 * logging actions such as delete, hide, restore, or warn for user-generated
 * content. It ensures the operation is performed by the authenticated admin
 * only and returns the created moderation record with all mandatory fields
 * populated, suitable for audit and compliance reporting.
 *
 * @param props - Properties including the authenticated admin and moderation
 *   log request body.
 * @param props.admin - The authenticated admin performing the moderation action
 *   (injected by AdminAuth decorator).
 * @param props.body - Fields needed to log a moderation action (content_type,
 *   content_id, action, acted_at, optional message) as required by audit
 *   policies.
 * @returns The newly created moderation log record with all fields.
 * @throws {Error} If admin.id doesn't match shopping_mall_ai_admin_id in body
 *   (preventing unauthorized log entries).
 */
export async function post__shopping_mall_ai_admin_contentModerations(props: {
  admin: AdminPayload;
  body: IShoppingContentModeration.ICreate;
}): Promise<IShoppingContentModeration> {
  const { admin, body } = props;

  if (admin.id !== body.shopping_mall_ai_admin_id) {
    throw new Error(
      "Unauthorized: admin.id does not match shopping_mall_ai_admin_id in request body",
    );
  }

  const created =
    await MyGlobal.prisma.shopping_mall_ai_content_moderations.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        shopping_mall_ai_admin_id: body.shopping_mall_ai_admin_id,
        content_type: body.content_type,
        content_id: body.content_id,
        action: body.action,
        message: body.message ?? null,
        acted_at: toISOStringSafe(body.acted_at),
        // restored_at: left undefined/null on create
      },
    });

  return {
    id: created.id as string & tags.Format<"uuid">,
    shopping_mall_ai_admin_id: created.shopping_mall_ai_admin_id as string &
      tags.Format<"uuid">,
    content_type: created.content_type,
    content_id: created.content_id as string & tags.Format<"uuid">,
    action: created.action,
    message: created.message,
    acted_at: toISOStringSafe(created.acted_at),
    restored_at: created.restored_at
      ? toISOStringSafe(created.restored_at)
      : null,
  };
}

