  const mileagePoint =
    await MyGlobal.prisma.shopping_mall_ai_mileage_points.findUnique({
      where: { id: mileagePointId },
    });
  if (!mileagePoint) {
    throw new Error("Mileage point event not found");
  }

  // Only allow updating permitted fields: point_type, amount, details, occurred_at
  // Use undefined for omitted fields, and convert date to ISO string
  const updated = await MyGlobal.prisma.shopping_mall_ai_mileage_points.update({
    where: { id: mileagePointId },
    data: {
      point_type: body.point_type ?? undefined,
      amount: body.amount ?? undefined,
      details: body.details === undefined ? undefined : body.details,
      occurred_at: body.occurred_at
        ? toISOStringSafe(body.occurred_at)
        : undefined,
    },
  });

  return {
    id: updated.id,
    shopping_mall_ai_customer_id: updated.shopping_mall_ai_customer_id,
    point_type: updated.point_type,
    amount: updated.amount,
    details: updated.details ?? null,
    occurred_at: toISOStringSafe(updated.occurred_at),
