/**
 * Register new uploaded file metadata.
 *
 * Creates a new file metadata record after a file upload in the
 * shopping_mall_ai_files table. The metadata contains the file's storage URI,
 * original/final name, MIME type, file size, extension, hash, uploader (actor
 * type/id), and upload timestamp. This operation is required as part of the
 * upload flow, subsequent to actual file transfer to blob/CDN. The backend
 * validates the file hash for deduplication and maintains compliance audit
 * logs.
 *
 * Accessible to all actor roles (customer, seller, admin) once a file upload is
 * successfully completed, typically by the uploader themselves. Related
 * operations include media asset creation and file attachment mapping.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin user (must be active for access)
 * @param props.body - Metadata about the uploaded file to be registered
 *   (original_name, uri, extension, mime_type, size, hash, [actor_type],
 *   [actor_id])
 * @returns Full record of the registered file metadata (id, original_name, uri,
 *   extension, mime_type, size, hash, [actor_type], [actor_id], created_at,
 *   [deleted_at])
 * @throws {Error} When a file with the same hash already exists (deduplication
 *   failed)
 */
export async function post__shopping_mall_ai_admin_shoppingMallAiFiles(props: {
  admin: AdminPayload;
  body: IShoppingMallAiFile.ICreate;
}): Promise<IShoppingMallAiFile> {
  const { body } = props;

  // Enforce deduplication (hash must be unique)
  const existing = await MyGlobal.prisma.shopping_mall_ai_files.findFirst({
    where: {
      hash: body.hash,
    },
  });
  if (existing) {
    throw new Error("File already exists (deduplication failed)");
  }

  // Insert new record
  const created = await MyGlobal.prisma.shopping_mall_ai_files.create({
    data: {
      id: v4(),
      original_name: body.original_name,
      uri: body.uri,
      extension: body.extension,
      mime_type: body.mime_type,
      size: body.size,
      hash: body.hash,
      actor_type: body.actor_type ?? null,
      actor_id: body.actor_id ?? null,
      created_at: toISOStringSafe(new Date()),
    },
  });

  // Return result in strict DTO form
  return {
    id: created.id,
    original_name: created.original_name,
    uri: created.uri,
    extension: created.extension,
    mime_type: created.mime_type,
    size: created.size,
    hash: created.hash,
    actor_type: created.actor_type,
    actor_id: created.actor_id,
    created_at: toISOStringSafe(created.created_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiOrder";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Creates a new order record in the system as an admin or backend integration.
 *
 * This endpoint allows authenticated admins to persist a new order to the
 * shopping_mall_ai_orders table. Required input fields (customer id, channel
 * id, status) are strictly validated for presence and referential integrity;
 * all order and audit fields are populated at creation time. The resulting
 * order object includes all mandatory fields with strong typing and ISO-format
 * timestamps.
 *
 * @param props - Request properties for order creation
 * @param props.admin - AdminPayload object for authentication (must be type
 *   'admin')
 * @param props.body - IShoppingMallAiOrder.ICreate object containing atomic
 *   fields for order creation
 * @returns IShoppingMallAiOrder - fully populated created order record
 * @throws {Error} If admin is not present or authenticated
 * @throws {Error} If required fields are missing
 * @throws {Error} If customer or channel referenced does not exist
 */
export async function post__shopping_mall_ai_admin_orders(props: {
  admin: AdminPayload;
  body: IShoppingMallAiOrder.ICreate;
}): Promise<IShoppingMallAiOrder> {
  const { admin, body } = props;

  if (!admin || admin.type !== "admin")
    throw new Error("Unauthorized: Only admins may create orders");

  if (!body.shopping_mall_ai_customer_id)
    throw new Error(
      "Missing required shopping_mall_ai_customer_id for order creation",
    );
  if (!body.shopping_mall_ai_channel_id)
    throw new Error(
      "Missing required shopping_mall_ai_channel_id for order creation",
    );
  if (!body.status)
    throw new Error("Missing required status for order creation");

  // CHECK: customer exists
  const customer = await MyGlobal.prisma.shopping_mall_ai_customers.findUnique({
    where: { id: body.shopping_mall_ai_customer_id },
  });
  if (!customer) throw new Error("Referenced customer does not exist");

  // CHECK: channel exists
  const channel = await MyGlobal.prisma.shopping_mall_ai_channels.findUnique({
    where: { id: body.shopping_mall_ai_channel_id },
  });
  if (!channel) throw new Error("Referenced channel does not exist");

  // PREP: generate UUID and timestamps
  const orderId = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());

  // CREATE: persist order, mapping input/derived fields directly
  const created = await MyGlobal.prisma.shopping_mall_ai_orders.create({
    data: {
      id: orderId,
      shopping_mall_ai_customer_id: body.shopping_mall_ai_customer_id,
      shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id,
      status: body.status,
      created_at: now,
      updated_at: now,
    },
  });

  return {
    id: created.id,
    shopping_mall_ai_customer_id: created.shopping_mall_ai_customer_id,
    shopping_mall_ai_channel_id: created.shopping_mall_ai_channel_id,
    status: created.status,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

