/**
 * Retrieves a paginated list of all product snapshot records in the shopping
 * mall system. Each snapshot reflects the product state and metadata at a key
 * event (creation, update, deletion), supporting audit trails, analytics, and
 * regulatory compliance. This endpoint is accessible only to authorized
 * administrators.
 *
 * Response includes:
 *
 * - Array of historical snapshots with all fields (id, product ID, action,
 *   snapshot JSON, created_at)
 * - Pagination metadata: current page, limit, total records, and total pages
 *
 * @param props - Request properties
 * @param props.admin - Authenticated administrator credentials (required for
 *   access)
 * @returns Paginated product snapshot history for compliance/audit/analytics
 *   workflows
 * @throws {Error} If database read fails
 */
export async function get__shopping_mall_ai_admin_shoppingMallAiProductSnapshots(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiProductSnapshot> {
  const page = 1;
