import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Registers a new coupon into the system using the shopping_mall_ai_coupons
 * table and the ICreate DTO.
 *
 * Only authorized sellers may use this operation; RBAC is enforced by
 * controller. All coupon attributes are validated for schema and business rule
 * compliance, including uniqueness of code and correct typing of all fields.
 * Returns the complete coupon object after persistence.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller making the request
 *   (authorization is performed at controller)
 * @param props.body - Coupon creation fields (see
 *   IShoppingMallAiCoupon.ICreate)
 * @returns The newly created coupon as persisted in the database
 * @throws {Error} When a coupon with the same code already exists
 * @throws {Error} When required business validation fails
 */
export async function post__shopping_mall_ai_seller_coupons(props: {
  seller: SellerPayload;
  body: IShoppingMallAiCoupon.ICreate;
}): Promise<IShoppingMallAiCoupon> {
  const { seller, body } = props;

  // Enforce unique coupon code
  const existing = await MyGlobal.prisma.shopping_mall_ai_coupons.findFirst({
    where: { code: body.code },
  });
  if (existing) {
    throw new Error("A coupon with this code already exists.");
  }

  // Prepare current timestamp (ISO string)
  const now = toISOStringSafe(new Date());

  // Persist the coupon
  const coupon = await MyGlobal.prisma.shopping_mall_ai_coupons.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_ai_seller_id: body.shopping_mall_ai_seller_id ?? seller.id,
      shopping_mall_ai_product_id: body.shopping_mall_ai_product_id ?? null,
      shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id ?? null,
      code: body.code,
      type: body.type,
      value: body.value,
      min_order_value: body.min_order_value ?? null,
      max_usage: body.max_usage,
      max_usage_per_customer: body.max_usage_per_customer,
      valid_from: toISOStringSafe(body.valid_from),
      valid_until: toISOStringSafe(body.valid_until),
      stackable: body.stackable,
      status: "active",
      created_at: now,
      updated_at: now,
    },
  });

