import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Performs a legal retention cycle soft deletion of a policy document
 * change/version record.
 *
 * Sets the 'deleted_at' field (soft delete marker) for a policy change record
 * in the compliance audit log as per retention policy. Only an active admin can
 * perform this operation. Throws if record does not exist, is already deleted,
 * or if the admin is not authorized.
 *
 * @param props - Parameters for deletion
 * @param props.admin - Authenticated AdminPayload (authorization required)
 * @param props.policyChangeId - UUID of the policy change/version audit record
 *   to delete (soft/hard as per policy)
 * @returns Void
 * @throws {Error} When the admin is not found or inactive
 * @throws {Error} When the policy change record is not found
 * @throws {Error} When the policy change record is already marked as deleted
 */
export async function delete__shopping_mall_ai_admin_policyChanges_$policyChangeId(props: {
  admin: AdminPayload;
  policyChangeId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, policyChangeId } = props;

  // Contractual authorization: Only allow if admin is active
  const dbAdmin = await MyGlobal.prisma.shopping_mall_ai_admins.findUnique({
    where: { id: admin.id },
    select: { id: true, is_active: true },
  });
  if (!dbAdmin || !dbAdmin.is_active)
    throw new Error("Unauthorized: Admin is not active");

  // Fetch policy change record to ensure it exists and has not already been deleted
  const policyChange =
    await MyGlobal.prisma.shopping_mall_ai_policy_changes.findUnique({
      where: { id: policyChangeId },
      select: { id: true, deleted_at: true },
    });
  if (!policyChange) throw new Error("Policy change not found");
  if (policyChange.deleted_at)
    throw new Error("Policy change is already deleted");

  // Soft delete by setting deleted_at
  await MyGlobal.prisma.shopping_mall_ai_policy_changes.update({
    where: { id: policyChangeId },
    data: {
      deleted_at: toISOStringSafe(new Date()),
    },
  });
  // Returns void
}

