 * ignored and will not affect the file record. All updates are restricted to
 * admin users by RBAC contract.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the operation
 * @param props.shoppingMallAiFileId - The unique identifier for the file to
 *   update (UUID)
 * @param props.body - Update data (original_name, actor_type, actor_id,
 *   deleted_at)
 * @returns The updated file metadata
 * @throws Error if file does not exist
 */
export async function put__shopping_mall_ai_admin_shoppingMallAiFiles_$shoppingMallAiFileId(props: {
