/**
 * Registers a new coupon into the system using the shopping_mall_ai_coupons
 * table.
 *
 * This endpoint allows authorized administrators to create a new coupon with
 * defined scope, type, value, and constraints. All business and RBAC rules are
 * enforced:
 *
 * - Validity range (valid_from <= valid_until)
 * - Uniqueness of coupon code
 *
 * Fields like `id`, status, timestamps are set automatically. The created
 * coupon is returned in full detail. Admin authentication is required via the
 * `admin` parameter.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the operation
 * @param props.body - Coupon creation fields per schema (code, type, value,
 *   validity, etc.)
 * @returns The created coupon entity with complete detail
 * @throws {Error} If the coupon code already exists
 * @throws {Error} If the validity date range is invalid
 */
export async function post__shopping_mall_ai_admin_coupons(props: {
  admin: AdminPayload;
  body: IShoppingMallAiCoupon.ICreate;
}): Promise<IShoppingMallAiCoupon> {
  const { admin, body } = props;

  // Validity: valid_from must be <= valid_until
  if (body.valid_from > body.valid_until) {
    throw new Error("Coupon validity end must be after or equal to start.");
  }

  // Enforce unique code
  const existing = await MyGlobal.prisma.shopping_mall_ai_coupons.findFirst({
    where: { code: body.code },
  });
  if (existing !== null) {
    throw new Error("Coupon code already exists.");
  }

  // All system-generated fields
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());

  const coupon = await MyGlobal.prisma.shopping_mall_ai_coupons.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_ai_seller_id: body.shopping_mall_ai_seller_id ?? null,
      shopping_mall_ai_product_id: body.shopping_mall_ai_product_id ?? null,
