      code: body.code,
      type: body.type,
      value: body.value,
      min_order_value: body.min_order_value ?? null,
      max_usage: body.max_usage,
      max_usage_per_customer: body.max_usage_per_customer,
      valid_from: body.valid_from,
      valid_until: body.valid_until,
      stackable: body.stackable,
      status: "active",
      created_at: now,
      updated_at: now,
    },
  });

  return {
    id: coupon.id,
    shopping_mall_ai_seller_id: coupon.shopping_mall_ai_seller_id ?? null,
    shopping_mall_ai_product_id: coupon.shopping_mall_ai_product_id ?? null,
    shopping_mall_ai_channel_id: coupon.shopping_mall_ai_channel_id ?? null,
    code: coupon.code,
    type: coupon.type,
    value: coupon.value,
    min_order_value: coupon.min_order_value ?? null,
    max_usage: coupon.max_usage,
    max_usage_per_customer: coupon.max_usage_per_customer,
    valid_from: coupon.valid_from,
    valid_until: coupon.valid_until,
    stackable: coupon.stackable,
    status: coupon.status,
    created_at: coupon.created_at,
    updated_at: coupon.updated_at,
  };
}

