import { IShoppingMallAiPolicyChange } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiPolicyChange";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * List compliance policy document version change records
 * (shopping_mall_ai_policy_changes).
 *
 * Lists paginated, sorted versioned policy document changes, as required for
 * compliance and legal review. Only users with admin/compliance roles may
 * access this endpoint.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin user payload (authorization
 *   enforced; only active admins allowed)
 * @returns Paginated list of policy change/version audit records including
 *   policy code, version, summary, approver, approval timestamp, previous
 *   version, and optional deletion timestamp.
 * @throws {Error} When admin authentication fails or admin is inactive
 */
export async function get__shopping_mall_ai_admin_policyChanges(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiPolicyChange.ISummary> {
  const { admin } = props;

  // Static/default pagination (can be extended with params if required)
  const page = 1;
  const limit = 20;
  const skip = (page - 1) * limit;

  // Defensive reconfirm: is the admin account still present/active?
  const adminAccount = await MyGlobal.prisma.shopping_mall_ai_admins.findFirst({
    where: { id: admin.id, is_active: true },
  });
  if (!adminAccount)
    throw new Error("Unauthorized: admin not found or inactive");

  // Fetch total, then fetch paginated records
  const [totalRecords, items] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_policy_changes.count(),
    MyGlobal.prisma.shopping_mall_ai_policy_changes.findMany({
      orderBy: { approved_at: "desc" },
      skip,
      take: limit,
    }),
  ]);

  // Transform DB data to output DTO; always convert all dates
  const data = items.map((item) => ({
    id: item.id,
    policy_code: item.policy_code,
    policy_version: item.policy_version,
    change_summary: item.change_summary,
    approved_by: item.approved_by,
    approved_at: toISOStringSafe(item.approved_at),
    previous_version: item.previous_version ?? null,
    deleted_at: item.deleted_at ? toISOStringSafe(item.deleted_at) : null,
  }));

  return {
    pagination: {
      current: page as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      limit: limit as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      records: totalRecords as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: Math.ceil(totalRecords / limit) as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data,
  };
}

