import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Search and filter deposit records by multiple criteria from
 * shopping_mall_ai_deposits (customer-only).
 *
 * Allows customers to search and filter their own deposit (store credit)
 * records by multiple criteria, including status, origin, date ranges, and
 * pagination. Always restricts results to the authenticated customer's own
 * deposits (enforced server-side).
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer payload. Only this customer's
 *   own deposits are visible and searchable.
 * @param props.body - Filtering criteria for status, origin, date range, and
 *   pagination.
 * @returns Paginated, filtered list of deposit records matching the criteria,
 *   with summary pagination info and all required fields.
 * @throws {Error} When a database or server error occurs.
 */
export async function patch__shopping_mall_ai_customer_deposits(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiDeposit.IRequest;
}): Promise<IPageIShoppingMallAiDeposit> {
  const { customer, body } = props;

  // Only allow filtering for own deposits
  const where = {
    shopping_mall_ai_customer_id: customer.id,
    ...(body.status !== undefined &&
      body.status !== null && {
        status: body.status,
      }),
    ...(body.origin !== undefined &&
      body.origin !== null && {
        origin: body.origin,
      }),
    // expires_at (lte: before, gte: after)
    ...((body.expires_at_after !== undefined &&
      body.expires_at_after !== null) ||
    (body.expires_at_before !== undefined && body.expires_at_before !== null)
      ? {
          expires_at: {
            ...(body.expires_at_after !== undefined &&
              body.expires_at_after !== null && {
                gte: body.expires_at_after,
              }),
            ...(body.expires_at_before !== undefined &&
              body.expires_at_before !== null && {
                lte: body.expires_at_before,
              }),
          },
        }
      : {}),
    // updated_at (gte: from, lte: to)
    ...((body.updated_at_from !== undefined && body.updated_at_from !== null) ||
    (body.updated_at_to !== undefined && body.updated_at_to !== null)
      ? {
          updated_at: {
            ...(body.updated_at_from !== undefined &&
              body.updated_at_from !== null && {
                gte: body.updated_at_from,
              }),
            ...(body.updated_at_to !== undefined &&
              body.updated_at_to !== null && {
                lte: body.updated_at_to,
              }),
          },
        }
      : {}),
  };
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit = body.limit && body.limit > 0 ? body.limit : 30;
  const skip = (page - 1) * limit;

  // Query in parallel for pagination
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_deposits.findMany({
      where,
      orderBy: { updated_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_deposits.count({
      where,
    }),
  ]);

  return {
    pagination: {
      current: page as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      limit: limit as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      records: total as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: Math.ceil(total / limit) as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data: rows.map((r) => ({
      id: r.id,
      shopping_mall_ai_customer_id: r.shopping_mall_ai_customer_id,
      balance: r.balance,
      updated_at: toISOStringSafe(r.updated_at),
      status: r.status,
      origin: r.origin,
      expires_at:
        r.expires_at !== null && r.expires_at !== undefined
          ? toISOStringSafe(r.expires_at)
          : null,
    })),
  };
}

