import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Retrieves a single product review by reviewId for the authenticated customer.
 *
 * - Only the review owner can access their review (and only if not soft-deleted).
 * - Returns 404 if the review is not found or is deleted.
 * - Returns 403 if the requested review does not belong to the authenticated
 *   customer.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer payload
 * @param props.reviewId - ID of the review to fetch (UUID)
 * @returns The full review object (IShoppingMallAiReview)
 * @throws {Error} 404 if review doesn't exist or is deleted, 403 if not owned
 *   by customer
 */
export async function get__shopping_mall_ai_customer_reviews_$reviewId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiReview> {
  const { customer, reviewId } = props;
  const review = await MyGlobal.prisma.shopping_mall_ai_reviews.findUnique({
    where: { id: reviewId },
  });

  // Not found or deleted (soft-delete)
  if (!review || review.deleted_at !== null) {
    throw new Error("Review not found");
  }
  // Ownership check (customer can only see their own review)
  if (review.shopping_mall_ai_customer_id !== customer.id) {
    throw new Error(
      "Forbidden: You do not have permission to access this review",
    );
  }

  return {
    id: review.id,
    shopping_mall_ai_product_id: review.shopping_mall_ai_product_id,
    shopping_mall_ai_customer_id: review.shopping_mall_ai_customer_id,
    shopping_mall_ai_order_id: review.shopping_mall_ai_order_id,
    rating: review.rating,
    body: review.body,
    created_at: toISOStringSafe(review.created_at),
    updated_at: toISOStringSafe(review.updated_at),
    deleted_at:
      review.deleted_at !== undefined && review.deleted_at !== null
        ? toISOStringSafe(review.deleted_at)
        : undefined,
  };
}

