import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInquiry";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Updates seller's answer for a product inquiry (Q&A), if authorized.
 *
 * This endpoint allows the assigned seller to update the answer field of an
 * existing product inquiry. Only the assigned seller can update the inquiry,
 * and only if it has not been deleted. Sellers may only provide or update the
 * answer; other fields are ignored.
 *
 * @param props - Argument object
 * @param props.seller - Authenticated seller payload (must match inquiry's
 *   seller)
 * @param props.inquiryId - UUID of the inquiry to update
 * @param props.body - Inquiry update input. Only .answer is used on seller
 *   endpoints.
 * @returns The updated inquiry record, fully populated.
 * @throws {Error} If inquiry is not found, deleted, or not assigned to this
 *   seller
 */
export async function put__shopping_mall_ai_seller_inquiries_$inquiryId(props: {
  seller: SellerPayload;
  inquiryId: string & tags.Format<"uuid">;
  body: IShoppingMallAiInquiry.IUpdate;
}): Promise<IShoppingMallAiInquiry> {
  const { seller, inquiryId, body } = props;

  // Fetch inquiry
  const inquiry = await MyGlobal.prisma.shopping_mall_ai_inquiries.findUnique({
    where: { id: inquiryId },
  });
  if (!inquiry) throw new Error("Inquiry not found");
  if (inquiry.deleted_at) throw new Error("Inquiry deleted");
  if (inquiry.shopping_mall_ai_seller_id !== seller.id)
    throw new Error(
      "Forbidden: You are not the assigned seller for this inquiry",
    );

  // Only allow seller to update answer
  if (typeof body.answer !== "undefined") {
    const now = toISOStringSafe(new Date());
    const updated = await MyGlobal.prisma.shopping_mall_ai_inquiries.update({
      where: { id: inquiryId },
      data: {
        answer: body.answer,
        answered_at: now,
      },
    });
    return {
      id: updated.id,
      shopping_mall_ai_product_id: updated.shopping_mall_ai_product_id,
      shopping_mall_ai_customer_id: updated.shopping_mall_ai_customer_id,
      shopping_mall_ai_seller_id: updated.shopping_mall_ai_seller_id,
      question: updated.question,
      is_private: updated.is_private,
      answer: updated.answer,
      answer_marked_helpful: updated.answer_marked_helpful,
      created_at: toISOStringSafe(updated.created_at),
      answered_at: updated.answered_at
        ? toISOStringSafe(updated.answered_at)
        : null,
      deleted_at: updated.deleted_at
        ? toISOStringSafe(updated.deleted_at)
        : null,
    };
  }
  // No valid update for seller (nothing to change); return current state
  return {
    id: inquiry.id,
    shopping_mall_ai_product_id: inquiry.shopping_mall_ai_product_id,
    shopping_mall_ai_customer_id: inquiry.shopping_mall_ai_customer_id,
    shopping_mall_ai_seller_id: inquiry.shopping_mall_ai_seller_id,
    question: inquiry.question,
    is_private: inquiry.is_private,
    answer: inquiry.answer,
    answer_marked_helpful: inquiry.answer_marked_helpful,
    created_at: toISOStringSafe(inquiry.created_at),
    answered_at: inquiry.answered_at
      ? toISOStringSafe(inquiry.answered_at)
      : null,
    deleted_at: inquiry.deleted_at ? toISOStringSafe(inquiry.deleted_at) : null,
  };
}

