/**
 * Fetch a paginated list of all payment records for a specific order
 * (shopping_mall_ai_payments), visible to sellers only if they own at least one
 * product in the order.
 *
 * This endpoint enables sellers to audit order payments, supports BI export,
 * after-sales workflows, and assures privacy by strict RBAC: only sellers of
 * products from the specified order can access the financial details.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller making the request
 * @param props.orderId - UUID of the target order whose payments are queried
 * @returns Paginated list of payments for the order, with audit-friendly
 *   metadata
 * @throws {Error} 404 Not Found if the order does not exist or has no items
 * @throws {Error} Unauthorized if the seller is not linked to the order (owns
 *   no products in it)
 */
export async function get__shopping_mall_ai_seller_orders_$orderId_payments(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
}): Promise<IPageIShoppingPayment> {
  const { seller, orderId } = props;

  // 1. Ensure the order exists
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: { id: true },
  });
  if (!order) throw new Error("Order not found");

  // 2. Find all items in the order; get related product_ids
  const orderItems =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where: { shopping_mall_ai_order_id: orderId },
      select: { shopping_mall_ai_product_id: true },
    });
  const productIds = orderItems.map((item) => item.shopping_mall_ai_product_id);
  if (!productIds.length) throw new Error("Order has no items");

  // 3. Verify seller owns at least one product from the order
  const ownsProduct = await MyGlobal.prisma.shopping_mall_ai_products.findFirst(
    {
      where: {
        id: { in: productIds },
        shopping_mall_ai_seller_id: seller.id,
      },
      select: { id: true },
    },
  );
  if (!ownsProduct)
    throw new Error("Unauthorized: Seller is not associated with this order");

  // 4. Fetch payments for this order
  const payments = await MyGlobal.prisma.shopping_mall_ai_payments.findMany({
    where: { shopping_mall_ai_order_id: orderId },
  });

  // 5. Return paginated object (single page)
  return {
    pagination: {
      current: 1 as 1,
      limit: payments.length as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      records: payments.length as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: 1 as 1,
    },
    data: payments.map((payment) => ({
      id: payment.id,
      shopping_mall_ai_order_id: payment.shopping_mall_ai_order_id,
      shopping_mall_ai_channel_id: payment.shopping_mall_ai_channel_id,
      method: payment.method,
      status: payment.status,
      amount: payment.amount,
      initiated_at: toISOStringSafe(payment.initiated_at),
      resolved_at: payment.resolved_at
        ? toISOStringSafe(payment.resolved_at)
        : null,
    })),
  };
}

import { MyGlobal } from "../MyGlobal";
