/**
 * Update a comment for a BBS post by comment ID
 * (shopping_mall_ai_bbs_comments).
 *
 * Updates an existing comment in a BBS forum thread, only if the authenticated
 * seller is the author. Refuses edit if the comment is deleted, does not belong
 * to the specified post, or if the seller is not the author. Only the body and
 * updated_at fields are modified.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller performing the update
 * @param props.bbsPostId - UUID of the BBS post containing the comment
 * @param props.bbsCommentId - UUID of the comment to update
 * @param props.body - Object containing the new comment body text
 * @returns Updated forum comment record
 * @throws {Error} If the comment is not found, is deleted, does not belong to
 *   the post, or the seller is not the author
 */
export async function put__shopping_mall_ai_seller_bbsPosts_$bbsPostId_bbsComments_$bbsCommentId(props: {
  seller: SellerPayload;
  bbsPostId: string & tags.Format<"uuid">;
  bbsCommentId: string & tags.Format<"uuid">;
  body: IShoppingMallAiBbsComment.IUpdate;
}): Promise<IShoppingMallAiBbsComment> {
  const { seller, bbsPostId, bbsCommentId, body } = props;

  const comment =
    await MyGlobal.prisma.shopping_mall_ai_bbs_comments.findUnique({
      where: { id: bbsCommentId },
    });
  if (!comment) throw new Error("Comment not found");
  if (comment.deleted_at !== null && comment.deleted_at !== undefined) {
    throw new Error("Comment is deleted and cannot be edited");
  }
  if (comment.shopping_mall_ai_bbs_post_id !== bbsPostId) {
    throw new Error("Comment does not belong to the specified BBS post");
  }
  if (comment.shopping_mall_ai_customer_id !== seller.id) {
    throw new Error(
      "Permission denied: You are not the author of this comment.",
    );
  }

  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_mall_ai_bbs_comments.update({
    where: { id: comment.id },
    data: {
      body: body.body,
      updated_at: now,
    },
  });

  return {
    id: updated.id,
    shopping_mall_ai_bbs_post_id: updated.shopping_mall_ai_bbs_post_id,
    shopping_mall_ai_customer_id: updated.shopping_mall_ai_customer_id,
    parent_id: updated.parent_id ?? null,
    body: updated.body,
    ip: updated.ip,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: now,
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Delete a shipment (hard delete) by ID (shopping_mall_ai_shipments table).
 *
 * Erase (hard delete) a shipment tied to a specific order by exact record
 * identity (orderId + shipmentId). No soft deletion is present, so the database
 * row is removed. Used in admin or high-trust seller support tools to resolve
 * invalid shipments or operational errors.
 *
 * Security & Authorization: Only permitted for trusted actors as enforced by
 * RBAC, with full audit logging. Customers cannot call this endpoint. Related
 * shipment GET endpoints should be used for validation before deletion.
 * Operation is irreversible.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the deletion
 * @param props.orderId - The ID of the parent order containing the shipment
 * @param props.shipmentId - The shipment record ID to remove
 * @returns Void
 * @throws {Error} If shipment or order is not found; or seller does not own the
 *   shipment's order
 */
export async function delete__shopping_mall_ai_seller_orders_$orderId_shipments_$shipmentId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  shipmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, orderId, shipmentId } = props;

  // 1. Fetch the shipment to verify existence and order relationship
  const shipment = await MyGlobal.prisma.shopping_mall_ai_shipments.findUnique({
    where: { id: shipmentId },
    select: {
      id: true,
      shopping_mall_ai_order_id: true,
    },
  });
  if (!shipment) throw new Error("Shipment not found");
  if (shipment.shopping_mall_ai_order_id !== orderId)
    throw new Error("Shipment does not belong to the specified order");

  // 2. Fetch the order and confirm it exists
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: { id: true },
  });
  if (!order) throw new Error("Order not found");

  // 3. Confirm the order contains order items that belong to the current seller
  // This protects against a seller deleting a shipment for an order with no items of theirs
  const items = await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
    where: { shopping_mall_ai_order_id: orderId },
    select: { shopping_mall_ai_product_id: true },
  });
  if (items.length === 0) throw new Error("Order has no items");

  // Check if any product in the order belongs to this seller
  const productIds = items.map((i) => i.shopping_mall_ai_product_id);
  const sellerProducts =
    await MyGlobal.prisma.shopping_mall_ai_products.findMany({
      where: {
        id: { in: productIds },
        shopping_mall_ai_seller_id: seller.id,
      },
      select: { id: true },
    });
  if (sellerProducts.length === 0) {
    throw new Error(
      "Forbidden: Seller does not have permission to delete this shipment.",
    );
  }

  // 4. Perform hard delete
  await MyGlobal.prisma.shopping_mall_ai_shipments.delete({
    where: { id: shipmentId },
  });
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Permanently deletes a product from the product catalog (hard delete).
 *
 * This operation removes a product identified by its unique product ID (UUID)
 * from the shopping_mall_ai_products table. As no soft-delete field exists in
 * the schema, this is a hard delete—removing the record entirely. Admins may
 * delete any product; audit logs are written for this action. If the product is
 * referenced by other entities (e.g., active orders, inventory), deletion will
 * fail due to referential integrity constraints.
 *
 * @param props - The request properties
 * @param props.admin - Authenticated admin user performing the delete
 * @param props.shoppingMallAiProductId - Unique ID of the product to delete
 * @returns Void
 * @throws {Error} When the product does not exist
 * @throws {Error} When deletion is blocked by referential integrity
 */
export async function delete__shopping_mall_ai_admin_shoppingMallAiProducts_$shoppingMallAiProductId(props: {
  admin: AdminPayload;
  shoppingMallAiProductId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, shoppingMallAiProductId } = props;

  // Step 1: Ensure the product exists; throw if not
  const product = await MyGlobal.prisma.shopping_mall_ai_products.findUnique({
    where: { id: shoppingMallAiProductId },
    select: { id: true },
  });
  if (!product) throw new Error("Product not found");

  // Step 2: Hard delete, handling referential integrity errors
  try {
    await MyGlobal.prisma.shopping_mall_ai_products.delete({
      where: { id: shoppingMallAiProductId },
    });
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2003"
    ) {
      throw new Error("Cannot delete product: referential integrity violation");
    }
    throw error;
  }

  // Step 3: Audit log the action
  await MyGlobal.prisma.shopping_mall_ai_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      entity_type: "shopping_mall_ai_products",
      entity_id: shoppingMallAiProductId,
      actor_id: admin.id,
      actor_role: "admin",
      operation: "delete",
      detail: "Product deleted by admin",
      occurred_at: toISOStringSafe(new Date()),
    },
  });
}

