/**
 * Get a paginated list of all file metadata records in the system.
 *
 * List all file resources managed by the platform. This operation is typically
 * used by administrators or system staff for performing audits, monitoring
 * storage, or troubleshooting upload issues. It queries all records in the
 * shopping_mall_ai_files table and returns an array of file metadata, such as
 * original name, extension, URI, and upload date.
 *
 * Access to this endpoint is strictly restricted to admin users. Customers and
 * sellers do not have access.
 *
 * This endpoint never returns file contents—only metadata. Used for audit and
 * compliance.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user making the request
 * @returns A paginated collection of file metadata records
 * @throws {Error} When access is denied or unexpected DB error occurs
 */
export async function get__shopping_mall_ai_admin_shoppingMallAiFiles(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiFile> {
  // No page/limit in API, so use default first page size 100
  const page = 1;
  const limit = 100;

  // Query metadata rows and total count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_files.findMany({
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_files.count(),
  ]);

  // Map to DTO, converting Date fields to ISO strings
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((row) => ({
      id: row.id,
      original_name: row.original_name,
      uri: row.uri,
      extension: row.extension,
      mime_type: row.mime_type,
      size: row.size,
      hash: row.hash,
      actor_type: row.actor_type ?? null,
      actor_id: row.actor_id ?? null,
      created_at: toISOStringSafe(row.created_at),
      deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
    })),
  };
}

