 * comment's unique identifier and its parent post's ID. Ensures the comment is
 * not deleted and the requesting customer has access permission (restricted to
 * comments on posts in the user's channel).
 *
 * Access is denied if the comment does not exist, is deleted, or the customer
 * does not belong to the post's channel.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request (must
 *   match channel)
 * @param props.bbsPostId - UUID of the parent BBS post
 * @param props.bbsCommentId - UUID of the target comment
 * @returns The full detail of the comment in IShoppingMallAiBbsComment format
 * @throws {Error} If the comment or post does not exist, is deleted, or the
 *   customer lacks channel permission
 */
export async function get__shopping_mall_ai_customer_bbsPosts_$bbsPostId_bbsComments_$bbsCommentId(props: {
  customer: CustomerPayload;
  bbsPostId: string & tags.Format<"uuid">;
  bbsCommentId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiBbsComment> {
  const { customer, bbsPostId, bbsCommentId } = props;

  // 1. Fetch comment ensuring it belongs to the post and is not deleted
  const comment = await MyGlobal.prisma.shopping_mall_ai_bbs_comments.findFirst(
    {
      where: {
        id: bbsCommentId,
        shopping_mall_ai_bbs_post_id: bbsPostId,
        deleted_at: null,
      },
    },
  );
  if (!comment) throw new Error("Comment not found or has been deleted");

  // 2. Fetch the parent post for channel-level auth; must not be deleted
  const post = await MyGlobal.prisma.shopping_mall_ai_bbs_posts.findFirst({
    where: {
      id: bbsPostId,
      deleted_at: null,
    },
