/**
 * List all shipments for a specific order (shopping_mall_ai_shipments table).
 *
 * Fetch a list of all shipment records associated with a given order. This
 * endpoint references the shopping_mall_ai_shipments table to extract every
 * shipment event tied to the specified order, identified by orderId. The
 * returned data includes shipping states, tracking numbers, provider names when
 * present, and audit timestamps for each shipment record.
 *
 * Security: Only actors allowed by RBAC matrix (customer: their order; seller:
 * their fulfilled orders; admin: all) can query this endpoint. Unauthorized
 * queries result in RBAC error.
 *
 * Data Integrity: Pulls direct data from the shopping_mall_ai_shipments table,
 * ensuring accuracy. Linked product or order data must be obtained via related
 * endpoints. Returns empty list if no shipments exist.
 *
 * Related APIs: For shipment detail view, use the endpoint with an added
 * {shipmentId} parameter. For updating, use the corresponding PUT operation.
 *
 * Errors: Invalid orderId, authorization violations, or system failures will
 * result in relevant error codes and messages.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request
 *   (CustomerPayload)
 * @param props.orderId - Unique identifier of the target order whose shipments
 *   are to be listed (UUID)
 * @returns An object with a 'shipments' array containing shipment records for
 *   the order
 * @throws {Error} When the order does not exist
 * @throws {Error} When the customer is not allowed to view this order's
 *   shipments
 */
export async function get__shopping_mall_ai_customer_orders_$orderId_shipments(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiShipmentList> {
  const { customer, orderId } = props;
  // Step 1: Check order existence and ownership
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: { id: true, shopping_mall_ai_customer_id: true },
