  return {
    shipments: rows.map((shipment) => ({
      id: shipment.id,
      shopping_mall_ai_order_id: shipment.shopping_mall_ai_order_id,
      status: shipment.status,
      tracking_number: shipment.tracking_number ?? null,
      provider: shipment.provider ?? null,
      created_at: toISOStringSafe(shipment.created_at),
      updated_at: toISOStringSafe(shipment.updated_at),
    })),
  };
}

