/**
 * Register file metadata post-upload (shopping_mall_ai_files).
 *
 * Registers new file metadata for a recently uploaded file in the shopping mall
 * platform. This writes all atomic asset metadata fields to the
 * shopping_mall_ai_files table, including original file name, public/private
 * URI, MIME type, extension, file size, deduplication hash, and audit context.
 *
 * - Admin privilege is required (enforced by parameter contract)
 * - Enforces uniqueness for file content hash
 * - Sets all timestamps using toISOStringSafe
 * - Strictly types all IDs and times per tags.Format
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the registration
 * @param props.body - New file metadata as stored in the asset table
 * @returns Details of the newly registered file asset record
 * @throws {Error} When a file with the same hash already exists
 */
export async function post__shopping_mall_ai_admin_files(props: {
  admin: AdminPayload;
  body: IShoppingMallAiFile.ICreate;
}): Promise<IShoppingMallAiFile> {
  const { admin, body } = props;

  // 1. Enforce uniqueness of file hash (deduplication)
  const existing = await MyGlobal.prisma.shopping_mall_ai_files.findFirst({
    where: { hash: body.hash },
    select: { id: true },
  });
  if (existing) {
    throw new Error("File with this hash already exists");
  }

  // 2. Create file metadata record (atomic, strict, immutable)
  const created = await MyGlobal.prisma.shopping_mall_ai_files.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      original_name: body.original_name,
      uri: body.uri,
      extension: body.extension,
      mime_type: body.mime_type,
      size: body.size,
      hash: body.hash,
      actor_type: body.actor_type ?? null,
      actor_id: body.actor_id ?? null,
      created_at: toISOStringSafe(new Date()),
      deleted_at: null,
    },
  });

  // 3. Return full file DTO with correct types for all properties
  return {
    id: created.id,
    original_name: created.original_name,
    uri: created.uri,
    extension: created.extension,
    mime_type: created.mime_type,
    size: created.size,
    hash: created.hash,
    actor_type: created.actor_type ?? null,
    actor_id: created.actor_id ?? null,
    created_at: toISOStringSafe(created.created_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IPageIShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBbsPost";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Get a paginated list of shopping mall BBS posts visible to the authenticated
 * customer.
 *
 * Returns only posts that have not been soft-deleted (deleted_at IS NULL) and
 * belong to the same channel as the customer. Each post includes metadata such
 * as title, timestamps, section, channel, and author nickname (from the
 * customers table). Pagination is fixed at page=1, limit=20 for simplicity in
 * this provider layer; advanced parameters can be added later if needed.
 *
 * @param props - Function parameters
 * @param props.customer - The authenticated customer payload (enforced by
 *   CustomerAuth decorator)
 * @returns Paginated summary information for BBS posts per
 *   IPageIShoppingMallAiBbsPost.ISummary
 * @throws {Error} If database or infrastructure issues prevent operation
 */
export async function get__shopping_mall_ai_customer_bbsPosts(props: {
  customer: CustomerPayload;
}): Promise<IPageIShoppingMallAiBbsPost.ISummary> {
  const { customer } = props;
  const page = 1 as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;
  const limit = 20 as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;
  const offset = (page - 1) * limit;

  // Fetch visible posts for customer's channel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_bbs_posts.findMany({
      where: {
        deleted_at: null,
        shopping_mall_ai_channel_id: customer.shopping_mall_ai_channel_id,
      },
      orderBy: { created_at: "desc" },
      skip: offset,
      take: limit,
      select: {
        id: true,
        title: true,
        created_at: true,
        updated_at: true,
        shopping_mall_ai_section_id: true,
        shopping_mall_ai_channel_id: true,
        shopping_mall_ai_customer_id: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_bbs_posts.count({
      where: {
        deleted_at: null,
        shopping_mall_ai_channel_id: customer.shopping_mall_ai_channel_id,
      },
    }),
  ]);

  // Batch load author nicknames
  const authorIds: (string & tags.Format<"uuid">)[] = Array.from(
    new Set(rows.map((row) => row.shopping_mall_ai_customer_id)),
  );
  const authors = await MyGlobal.prisma.shopping_mall_ai_customers.findMany({
    where: { id: { in: authorIds } },
    select: { id: true, nickname: true },
  });
  const authorMap = new Map(authors.map((a) => [a.id, a.nickname]));

  const data = rows.map((row) => ({
    id: row.id,
    title: row.title,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    shopping_mall_ai_section_id: row.shopping_mall_ai_section_id,
    shopping_mall_ai_channel_id: row.shopping_mall_ai_channel_id,
    author_nickname: authorMap.get(row.shopping_mall_ai_customer_id) ?? "",
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: Math.ceil(total / limit) as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data,
  };
}

