/**
 * Advanced filtered and paginated search of order items for a given order
 * (shopping_mall_ai_order_items).
 *
 * This endpoint allows platform administrators to search for and retrieve a
 * paginated, filtered list of all order items belonging to a specific order. It
 * supports field-based and status filtering, date range queries, and robust
 * pagination for dashboard or audit/reporting use cases.
 *
 * Authorization: Requires a valid admin user; only active administrators may
 * query order items. Access checks are enforced.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin making the request (must be
 *   active)
 * @param props.orderId - UUID of the parent order (shopping_mall_ai_orders.id)
 * @param props.body - Search/filter and pagination criteria
 *   (IShoppingOrderItem.IRequest)
 * @returns Paginated list of order items (IPageIShoppingOrderItem)
 * @throws {Error} If the admin is inactive, unauthorized, or missing
 */
export async function patch__shopping_mall_ai_admin_orders_$orderId_orderItems(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingOrderItem.IRequest;
}): Promise<IPageIShoppingOrderItem> {
  const { admin, orderId, body } = props;
  if (!admin || admin.type !== "admin")
    throw new Error("Unauthorized: Admin login required");
  if (typeof admin.is_active !== "undefined" && !admin.is_active)
    throw new Error("Admin access denied: inactive account");

  // Pagination: defaults
  const page: number =
    typeof body.page === "number" && body.page > 0 ? body.page : 1;
  const limit: number =
    typeof body.limit === "number" && body.limit > 0 ? body.limit : 100;
  const skip: number = (page - 1) * limit;

  // WHERE filter inline, strong typing: only include optional fields if defined & not null
  const where = {
    shopping_mall_ai_order_id: orderId,
    ...(body.shopping_mall_ai_product_id !== undefined &&
      body.shopping_mall_ai_product_id !== null && {
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
      }),
    ...(body.status !== undefined &&
      body.status !== null && {
        status: body.status,
      }),
    ...(body.created_from || body.created_to
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && {
                gte: body.created_from,
              }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && {
                lte: body.created_to,
              }),
          },
        }
      : {}),
  };

  // Query concurrently for items and total count
  const [items, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_order_items.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: items.map((item) => ({
      id: item.id,
      shopping_mall_ai_order_id: item.shopping_mall_ai_order_id,
      shopping_mall_ai_product_id: item.shopping_mall_ai_product_id,
      shopping_mall_ai_product_option_id:
        typeof item.shopping_mall_ai_product_option_id !== "undefined" &&
        item.shopping_mall_ai_product_option_id !== null
          ? item.shopping_mall_ai_product_option_id
          : null,
      price: item.price,
      quantity: item.quantity,
      status: item.status,
      created_at: toISOStringSafe(item.created_at),
      updated_at: toISOStringSafe(item.updated_at),
    })),
  };
}

