 */
export async function patch__shopping_mall_ai_admin_mediaAssets(props: {
  admin: AdminPayload;
  body: IShoppingMallAiMediaAsset.IRequest;
}): Promise<IPageIShoppingMallAiMediaAsset.ISummary> {
  const { body } = props;
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;

  // Build where clause safely and inline
  const where = {
    ...(body.asset_type !== undefined &&
