 *   fields
 * @throws {Error} When the provided SKU is already used for the product
 *   (duplicate)
 * @throws {Error} When a database or system error occurs
 */
export async function post__shopping_mall_ai_admin_shoppingMallAiProductOptions(props: {
  admin: AdminPayload;
  body: IShoppingMallAiProductOption.ICreate;
}): Promise<IShoppingMallAiProductOption> {
