  try {
    const created =
      await MyGlobal.prisma.shopping_mall_ai_product_options.create({
        data: {
          id: v4() as string & tags.Format<"uuid">,
          shopping_mall_ai_product_id: props.body.shopping_mall_ai_product_id,
