/**
 * Create a new product tag entity by associating a tag string with a target
 * product.
 *
 * This operation supports both ongoing product catalog management (such as
 * seasonal, promotional, or AI-inferred tags) and ensures normalized tag data
 * for downstream analytics or recommendation models.
 *
 * Strict validation prevents creation of duplicate tags or inconsistent
 * mappings. System enforces admin-level authorization to maintain integrity of
 * platform-level tagging and analytic schemes.
 *
 * @param props - Properties for product tag creation
 * @param props.admin - The authenticated admin performing the operation
 * @param props.body - Information and target product for new tag mapping entry
 * @returns The newly created product tag entity with all metadata fields
 * @throws {Error} When a duplicate tag for the same product exists
 */
export async function post__shopping_mall_ai_admin_shoppingMallAiProductTags(props: {
  admin: AdminPayload;
  body: IShoppingMallAiProductTag.ICreate;
}): Promise<IShoppingMallAiProductTag> {
