  // Step 1: Enforce uniqueness - check that the tag/product pair is not already present
  const existing =
    await MyGlobal.prisma.shopping_mall_ai_product_tags.findFirst({
      where: {
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
        tag: body.tag,
      },
