/**
 * Advanced filtered and paginated search of order items for a given order
 * (shopping_mall_ai_order_items).
 *
 * This operation allows authenticated customers to perform robust, paginated
 * and filtered queries of order items tied to a specific order. Supported
 * filters include product, status, and created_at range. Pagination is handled
 * safely, with default and custom limit/page handling. Strict authorization is
 * enforced so customers can only view their own orders.
 *
 * @param props - Request context
 * @param props.customer - The authenticated customer (authorization)
 * @param props.orderId - The UUID for the shopping order whose items are being
 *   queried
 * @param props.body - Filter and pagination options (@see
 *   IShoppingOrderItem.IRequest)
 * @returns Paginated result with order items matching the input filters
 * @throws {Error} If the order does not exist or is not accessible by the
 *   customer
 */
export async function patch__shopping_mall_ai_customer_orders_$orderId_orderItems(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingOrderItem.IRequest;
}): Promise<IPageIShoppingOrderItem> {
  const { customer, orderId, body } = props;
  // Step 1: Authorize the customer can access the order
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: { id: true, shopping_mall_ai_customer_id: true },
  });
  if (!order) throw new Error("Order not found");
  if (order.shopping_mall_ai_customer_id !== customer.id) {
    throw new Error("Unauthorized: customer cannot access this order");
  }

  // Step 2: Resolve pagination (default to 1/20 if not set)
  const page = body.page != null ? body.page : 1;
  const limit = body.limit != null ? body.limit : 20;
  const skip = (page - 1) * limit;

  // Step 3: Build filter for order items tied to this order
  const where = {
    shopping_mall_ai_order_id: orderId,
    ...(body.shopping_mall_ai_product_id != null && {
      shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
    }),
    ...(body.status != null && {
      status: body.status,
    }),
    ...((body.created_from != null || body.created_to != null) && {
      created_at: {
        ...(body.created_from != null && { gte: body.created_from }),
        ...(body.created_to != null && { lte: body.created_to }),
      },
    }),
  };

  // Step 4: Query concurrently for paginated results and total count
  const [items, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_order_items.count({ where }),
  ]);

  // Step 5: Map DB results to API structure, with safe datetime conversion
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: total > 0 ? Math.ceil(total / limit) : 0,
    },
    data: items.map((item) => ({
      id: item.id,
      shopping_mall_ai_order_id: item.shopping_mall_ai_order_id,
      shopping_mall_ai_product_id: item.shopping_mall_ai_product_id,
      shopping_mall_ai_product_option_id:
        item.shopping_mall_ai_product_option_id ?? null,
      price: item.price,
      quantity: item.quantity,
      status: item.status,
      created_at: toISOStringSafe(item.created_at),
      updated_at: toISOStringSafe(item.updated_at),
    })),
  };
}

