/**
 * Lists all file metadata records uploaded to the platform for administrative
 * or operational review.
 *
 * Retrieves all records from shopping_mall_ai_files including soft-deleted
 * files. Only users with admin privileges are permitted. Each file summary
 * includes original file name, URI, extension, MIME type, size, hash, and audit
 * timestamps. The result conforms to IPageIShoppingMallAiFile.ISummary and
 * includes a single page of all files for admin overview (not true
 * pagination).
 *
 * @param props - The request context containing the authenticated admin
 *   payload.
 * @param props.admin - The authenticated admin user context (enforced by
 *   AdminAuth decorator).
 * @returns Paginated summary of all uploaded files for platform audit and admin
 *   review.
 * @throws {Error} If props.admin is missing (should not occur if properly
 *   decorated).
 */
export async function get__shopping_mall_ai_admin_files(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiFile.ISummary> {
  // Authorization is enforced by the presence of props.admin.
  const files = await MyGlobal.prisma.shopping_mall_ai_files.findMany();

  const data = files.map((f) => ({
    id: f.id,
    original_name: f.original_name,
    uri: f.uri,
    extension: f.extension,
    mime_type: f.mime_type,
    size: f.size,
    hash: f.hash,
    created_at: toISOStringSafe(f.created_at),
    deleted_at: f.deleted_at ? toISOStringSafe(f.deleted_at) : null,
  }));

  const pagination = {
    current: 1 as 1 &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{ format: "uint32" }>,
    limit: data.length as number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{ format: "uint32" }>,
    records: data.length as number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{ format: "uint32" }>,
    pages: 1 as 1 &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{ format: "uint32" }>,
  };

  return { pagination, data };
}

