  // 1. Ensure the coupon exists and the seller owns it
  const coupon = await MyGlobal.prisma.shopping_mall_ai_coupons.findFirst({
    where: { id: couponId },
    select: { id: true, shopping_mall_ai_seller_id: true },
  });
  if (!coupon) throw new Error("Coupon not found");
  if (
    !coupon.shopping_mall_ai_seller_id ||
    coupon.shopping_mall_ai_seller_id !== seller.id
  ) {
    throw new Error("You do not have access to this coupon's events");
  }

  // 2. Fetch up to 100 coupon event rows + total count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_coupon_events.findMany({
      where: { shopping_mall_ai_coupon_id: couponId },
      orderBy: { occurred_at: "desc" },
      take: 100,
    }),
    MyGlobal.prisma.shopping_mall_ai_coupon_events.count({
      where: { shopping_mall_ai_coupon_id: couponId },
    }),
  ]);

  // 3. Map database records to IShoppingMallAiCouponEvent[] (with correct null/default handling)
  const data = rows.map((ev) => ({
    id: ev.id,
    shopping_mall_ai_coupon_id: ev.shopping_mall_ai_coupon_id,
    shopping_mall_ai_customer_id: ev.shopping_mall_ai_customer_id ?? null,
    shopping_mall_ai_order_id: ev.shopping_mall_ai_order_id ?? null,
    shopping_mall_ai_actor_id: ev.shopping_mall_ai_actor_id ?? null,
    event_type: ev.event_type,
    occurred_at: toISOStringSafe(ev.occurred_at),
    details: ev.details ?? null,
  }));

  // 4. Return paginated response
  return {
    pagination: {
      current: 1,
      limit: 100,
      records: total,
      pages: Math.ceil(total / 100),
    },
    data,
  };
}

