/**
 * Updates an existing product in the product catalog.
 *
 * Allows an authenticated seller (product owner) to update selected mutable
 * fields of their product in the shopping mall catalog. Only the title,
 * description, category, price, status, SKU, and updated_at can be changed.
 * Ownership is verified and unauthorized updates are rejected. The response
 * returns all product fields, with date fields formatted as ISO strings.
 * Business constraints and FK/uniqueness are enforced by the database.
 *
 * @param props - Request object.
 * @param props.seller - Authenticated seller context (must own the product).
 * @param props.shoppingMallAiProductId - Product UUID to be updated.
 * @param props.body - Fields to update; all optional per DTO.
 * @returns The updated product, with all fields populated and audit dates as
 *   ISO strings.
 * @throws {Error} If the product does not exist or the seller is unauthorized.
 */
export async function put__shopping_mall_ai_seller_shoppingMallAiProducts_$shoppingMallAiProductId(props: {
  seller: SellerPayload;
  shoppingMallAiProductId: string & tags.Format<"uuid">;
  body: IShoppingMallAiProduct.IUpdate;
}): Promise<IShoppingMallAiProduct> {
  const { seller, shoppingMallAiProductId, body } = props;

  // Step 1: Fetch the product and verify ownership
  const product = await MyGlobal.prisma.shopping_mall_ai_products.findUnique({
    where: { id: shoppingMallAiProductId },
    select: {
      id: true,
      shopping_mall_ai_seller_id: true,
    },
  });
  if (!product) throw new Error("Product not found");
  if (product.shopping_mall_ai_seller_id !== seller.id) {
    throw new Error(
      "Forbidden: Only the product owner may update this product.",
    );
  }

  // Step 2: Update only fields provided in body, skip undefineds, always update updated_at
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_mall_ai_products.update({
    where: { id: shoppingMallAiProductId },
    data: {
      shopping_mall_ai_product_category_id:
        body.shopping_mall_ai_product_category_id ?? undefined,
      title: body.title ?? undefined,
      description: body.description ?? undefined,
      price: body.price ?? undefined,
      status: body.status ?? undefined,
      sku: body.sku ?? undefined,
      updated_at: now,
    },
  });

  // Step 3: Return the updated product with audit timestamps as ISO strings
  return {
    id: updated.id,
    shopping_mall_ai_seller_id: updated.shopping_mall_ai_seller_id,
    shopping_mall_ai_product_category_id:
      updated.shopping_mall_ai_product_category_id,
    title: updated.title,
    description: updated.description,
    price: updated.price,
    status: updated.status,
    sku: updated.sku,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

