/**
 * Create new AI recommendation mapping (admin).
 *
 * Creates an AI recommendation entry, mapping a product to a channel and
 * attaching metadata such as model output, reasoning, or trace. This enables
 * manual curation or import of recommendations and is critical for compliant,
 * explainable AI in regulated domains.
 *
 * Strict validation is applied to avoid duplicate or conflicting
 * recommendations (one mapping per channel/product pair). Only administrators
 * may create mappings, and all operations are logged for auditability.
 *
 * @param props - Properties for AI mapping creation
 * @param props.admin - Admin authentication payload (must be present and
 *   validated)
 * @param props.body - AI recommendation mapping creation payload, containing
 *   mappings and metadata
 * @returns The created AI recommendation mapping entity, including id, mapping
 *   fields, and audit timestamps
 * @throws {Error} When a mapping already exists for the given product/channel
 *   pair
 */
export async function post__shopping_mall_ai_admin_shoppingMallAiAiRecommendations(props: {
  admin: AdminPayload;
  body: IShoppingMallAiAiRecommendation.ICreate;
}): Promise<IShoppingMallAiAiRecommendation> {
  const { body } = props;

  // Step 1: Enforce uniqueness (one per channel/product)
  const recommendation =
    await MyGlobal.prisma.shopping_mall_ai_ai_recommendations.findFirst({
      where: {
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
        shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id,
      },
    });
  if (recommendation !== null) {
    throw new Error(
      "Duplicate recommendation mapping already exists for this channel/product pair.",
    );
  }

  const now = toISOStringSafe(new Date());

  // Step 2: Insert new unique mapping
  const created =
    await MyGlobal.prisma.shopping_mall_ai_ai_recommendations.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
        shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id,
        metadata_json: body.metadata_json,
        created_at: now,
        updated_at: now,
      },
    });

  // Step 3: Return result with all audit fields
  return {
    id: created.id,
    shopping_mall_ai_product_id: created.shopping_mall_ai_product_id,
    shopping_mall_ai_channel_id: created.shopping_mall_ai_channel_id,
    metadata_json: created.metadata_json,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

