  });

  // 4. Map back to DTO/response, converting all dates properly
  return {
    id: updated.id,
    user_id: updated.user_id,
    policy_code: updated.policy_code,
    policy_version: updated.policy_version,
    consented_at: toISOStringSafe(updated.consented_at),
    consent_method: updated.consent_method,
