/**
 * Get detail for a single comment on a BBS post (shopping_mall_ai_bbs_comments)
 * by ID.
 *
 * Retrieve detailed information on a single comment in a BBS post thread, using
 * the comment's unique identifier and its parent post's ID. The comment
 * information provided includes author, content, parent reference (if any for
 * nesting), IP, timestamps, soft-delete state, and all fields mandated by the
 * shopping_mall_ai_bbs_comments schema.
 *
 * Access control: Seller can only retrieve comments belonging to posts within
 * their own channel. Throws error if comment is soft-deleted, not found, or
 * seller is unauthorized.
 *
 * @param props - Function argument object
 * @param props.seller - Authenticated seller payload (must match post's
 *   channel)
 * @param props.bbsPostId - UUID of parent BBS post
 * @param props.bbsCommentId - UUID of comment attached to the post
 * @returns Detailed info of the comment as IShoppingMallAiBbsComment
 * @throws {Error} When comment or post not found, deleted, or seller is
 *   unauthorized
 */
export async function get__shopping_mall_ai_seller_bbsPosts_$bbsPostId_bbsComments_$bbsCommentId(props: {
  seller: SellerPayload;
  bbsPostId: string & tags.Format<"uuid">;
  bbsCommentId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAiBbsComment> {
  const { seller, bbsPostId, bbsCommentId } = props;

  // 1. Find the comment for the requested post and not deleted
  const comment = await MyGlobal.prisma.shopping_mall_ai_bbs_comments.findFirst(
    {
      where: {
        id: bbsCommentId,
        shopping_mall_ai_bbs_post_id: bbsPostId,
        deleted_at: null,
      },
    },
  );
  if (!comment) {
    throw new Error("Comment not found or deleted");
  }

  // 2. Find the post for access control
  const post = await MyGlobal.prisma.shopping_mall_ai_bbs_posts.findFirst({
    where: {
      id: bbsPostId,
      deleted_at: null,
    },
  });
  if (!post) {
    throw new Error("BBS post not found or deleted");
  }

  // 3. Confirm seller is allowed (their channel matches the post's channel)
  const sellerObj = await MyGlobal.prisma.shopping_mall_ai_sellers.findFirst({
    where: {
      id: seller.id,
    },
  });
  if (!sellerObj) {
    throw new Error("Seller account not found");
  }
  if (
    post.shopping_mall_ai_channel_id !== sellerObj.shopping_mall_ai_channel_id
  ) {
    throw new Error(
      "Unauthorized: Cannot view comment from a post outside your channel",
    );
  }

  // 4. Map database record to DTO, converting datetimes strictly as string & tags.Format<'date-time'>
  return {
    id: comment.id,
    shopping_mall_ai_bbs_post_id: comment.shopping_mall_ai_bbs_post_id,
    shopping_mall_ai_customer_id: comment.shopping_mall_ai_customer_id,
    parent_id: comment.parent_id ?? null,
    body: comment.body,
    ip: comment.ip,
    created_at: toISOStringSafe(comment.created_at),
    updated_at: toISOStringSafe(comment.updated_at),
    deleted_at: comment.deleted_at ? toISOStringSafe(comment.deleted_at) : null,
  };
}

