 *
 * @param props - 요청 속성
 * @param props.admin - 인증된 관리자 JWT 페이로드 객체
 * @param props.body - 검색 필터 조건 및 페이징 정보 (IShoppingMallAiDeposit.IRequest)
 * @returns IPageIShoppingMallAiDeposit - 페이징 정보와 적립금 데이터 목록
 * @throws {Error} 인증 실패, DB 오류 등 예외 상황 발생 시
 */
export async function patch__shopping_mall_ai_admin_deposits(props: {
  admin: AdminPayload;
  body: IShoppingMallAiDeposit.IRequest;
}): Promise<IPageIShoppingMallAiDeposit> {
  const { body } = props;
  const page = body.page ?? 1;
  const limit = body.limit ?? 100;

  // 날짜 검색 조건 생성
  const expiresAtRange =
    body.expires_at_after || body.expires_at_before
      ? {
          ...(body.expires_at_after !== undefined &&
            body.expires_at_after !== null && { gte: body.expires_at_after }),
          ...(body.expires_at_before !== undefined &&
            body.expires_at_before !== null && { lte: body.expires_at_before }),
        }
      : undefined;
  const updatedAtRange =
    body.updated_at_from || body.updated_at_to
      ? {
          ...(body.updated_at_from !== undefined &&
            body.updated_at_from !== null && { gte: body.updated_at_from }),
          ...(body.updated_at_to !== undefined &&
            body.updated_at_to !== null && { lte: body.updated_at_to }),
        }
      : undefined;

  const where = {
    ...(body.shopping_mall_ai_customer_id !== undefined &&
      body.shopping_mall_ai_customer_id !== null && {
        shopping_mall_ai_customer_id: body.shopping_mall_ai_customer_id,
      }),
    ...(body.status !== undefined &&
      body.status !== null && { status: body.status }),
    ...(body.origin !== undefined &&
      body.origin !== null && { origin: body.origin }),
    ...(expiresAtRange && { expires_at: expiresAtRange }),
    ...(updatedAtRange && { updated_at: updatedAtRange }),
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_deposits.findMany({
      where,
      orderBy: { updated_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_deposits.count({ where }),
  ]);

  return {
    pagination: {
      current: page as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      limit: limit as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      records: total as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: Math.ceil(total / limit) as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data: rows.map((row) => ({
