import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Register new uploaded file metadata (seller upload).
 *
 * Creates a new metadata record in the shopping_mall_ai_files table after file
 * upload by a seller. Ensures system-populated fields (id, created_at),
 * enforces file hash deduplication, and links audit data to the seller. Throws
 * error if the file hash already exists among non-deleted metadata
 * (deduplication enforced).
 *
 * @param props - Request properties
 * @param props.seller - Authenticated, active, verified seller performing the
 *   upload
 * @param props.body - File metadata (original_name, uri, extension, mime_type,
 *   size, hash, etc)
 * @returns Full record of the registered file metadata, with system-generated
 *   fields populated
 * @throws {Error} If a file with the given hash already exists (hash
 *   deduplication enforced)
 */
export async function post__shopping_mall_ai_seller_shoppingMallAiFiles(props: {
  seller: SellerPayload;
  body: IShoppingMallAiFile.ICreate;
}): Promise<IShoppingMallAiFile> {
  // Check hash for active, not-deleted files (enforce deduplication)
  const duplicate = await MyGlobal.prisma.shopping_mall_ai_files.findFirst({
    where: {
      hash: props.body.hash,
      deleted_at: null,
    },
  });
  if (duplicate) {
    throw new Error("Conflict: File already registered (hash deduplication)");
  }

  // Insert the new metadata row
  const created = await MyGlobal.prisma.shopping_mall_ai_files.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      original_name: props.body.original_name,
      uri: props.body.uri,
      extension: props.body.extension,
      mime_type: props.body.mime_type,
      size: props.body.size,
      hash: props.body.hash,
      actor_type: "seller",
      actor_id: props.seller.id,
      created_at: toISOStringSafe(new Date()),
    },
  });

  // Map DB result to output DTO, using toISOStringSafe for all date fields
  return {
    id: created.id,
    original_name: created.original_name,
    uri: created.uri,
    extension: created.extension,
    mime_type: created.mime_type,
    size: created.size,
    hash: created.hash,
    actor_type: created.actor_type,
    actor_id: created.actor_id,
    created_at: toISOStringSafe(created.created_at),
    deleted_at:
      created.deleted_at !== null && created.deleted_at !== undefined
        ? toISOStringSafe(created.deleted_at)
        : null,
  };
}

