/**
 * Update a legal consent record (shopping_mall_ai_legal_consents).
 *
 * Modifies fields on an existing legal consent record (e.g., withdrawal,
 * method, or audit correction). Access is restricted to the seller
 * (record.user_id === seller.id). All mutations are logged for compliance.
 * Throws error if record not found or not owned by seller.
 *
 * @param props - Function arguments
 * @param props.seller - Authenticated seller making the update (must own
 *   record)
 * @param props.legalConsentId - Unique UUID of the consent entity
 * @param props.body - Update fields (IShoppingMallAiLegalConsent.IUpdate)
 * @returns The updated legal consent record
 * @throws Error if record not found or not owned by the seller
 */
export async function put__shopping_mall_ai_seller_legalConsents_$legalConsentId(props: {
  seller: SellerPayload;
  legalConsentId: string & tags.Format<"uuid">;
  body: IShoppingMallAiLegalConsent.IUpdate;
}): Promise<IShoppingMallAiLegalConsent> {
  const { seller, legalConsentId, body } = props;

  // 1. Fetch and authorize
  const record =
    await MyGlobal.prisma.shopping_mall_ai_legal_consents.findUnique({
      where: { id: legalConsentId },
    });
  if (!record) throw new Error("Legal consent record not found");
  if (record.user_id !== seller.id)
    throw new Error(
      "Unauthorized: seller does not own this legal consent record",
    );

  // 2. Normalize input for updatable fields
  const updateData: Record<string, any> = {
    withdrawn_at: body.withdrawn_at ?? undefined,
    consent_method: body.consent_method ?? undefined,
    consent_ip: body.consent_ip ?? undefined,
    deleted_at: body.deleted_at ?? undefined,
  };
  // Actual update
  const updated = await MyGlobal.prisma.shopping_mall_ai_legal_consents.update({
    where: { id: legalConsentId },
    data: updateData,
  });

  // 3. Return DTO with proper datetime string conversion
  return {
    id: updated.id,
    user_id: updated.user_id,
    policy_code: updated.policy_code,
    policy_version: updated.policy_version,
    consented_at: toISOStringSafe(updated.consented_at),
    consent_method: updated.consent_method,
    withdrawn_at: updated.withdrawn_at
      ? toISOStringSafe(updated.withdrawn_at)
      : null,
    consent_ip: updated.consent_ip ?? null,
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

