/**
 * Retrieve a paginated list of file access log records, each recording an
 * individual read/write/delete or similar event as per the
 * 'shopping_mall_ai_file_access_logs' schema. Returns full log history for
 * files, including details of actor, access type, outcome/result, and
 * timestamp.
 *
 * Only authorized admin users may view the entire access history of files for
 * audit purposes. Pagination ensures performance and allows analysis over long
 * system operation periods.
 *
 * @param props - Call parameters
 * @param props.admin - Authenticated admin user (required)
 * @returns Paginated list of file access log entries
 * @throws {Error} When admin is not provided or not authorized
 */
export async function get__shopping_mall_ai_admin_fileAccessLogs(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiFileAccessLog> {
  const { admin } = props;
  if (!admin) throw new Error("Unauthorized: admin login required");

  // Default pagination: page 1, 100 records per page
  const current = 1;
  const limit = 100;
  const skip = (current - 1) * limit;

  // Fetch paginated log entries and total count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_file_access_logs.findMany({
      skip,
      take: limit,
      orderBy: { accessed_at: "desc" },
      select: {
        id: true,
        shopping_mall_ai_file_id: true,
        actor_type: true,
        actor_id: true,
        access_type: true,
        channel: true,
        outcome: true,
        ip_address: true,
        accessed_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_file_access_logs.count(),
  ]);

  // Map DB results to API DTO (date/time safely stringified & branded)
  const data = rows.map((log) => ({
    id: log.id,
    shopping_mall_ai_file_id: log.shopping_mall_ai_file_id,
    actor_type: log.actor_type ?? null,
    actor_id: log.actor_id ?? null,
    access_type: log.access_type,
    channel: log.channel,
    outcome: log.outcome,
    ip_address: log.ip_address,
    accessed_at: toISOStringSafe(log.accessed_at),
  }));

  // Pagination info as per IPage.IPagination
  const pages = Math.ceil(total / limit);

  return {
    pagination: {
      current,
      limit,
      records: total,
      pages,
    },
    data,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Update a BBS post by ID (shopping_mall_ai_bbs_posts).
 *
 * Authenticated sellers may update the content of their own BBS posts. Only the
 * post's original author (by customer_id) may edit that post. This function
 * checks for existence, deletion, and correct ownership. Timestamp is refreshed
 * upon successful update.
 *
 * @param props - The provider props object.
 * @param props.seller - The authenticated seller. The seller's id must match
 *   the post's shopping_mall_ai_customer_id.
 * @param props.bbsPostId - The UUID of the post to be updated.
 * @param props.body - The update payload (partial fields: title and/or body).
 * @returns The updated BBS post record, with all date fields normalized as
 *   ISO8601 strings. If the post does not exist, has been deleted, or is not
 *   owned by the seller, an error is thrown.
 * @throws {Error} When post is not found, the post is deleted, or the seller is
 *   not authorized to update this post.
 */
export async function put__shopping_mall_ai_seller_bbsPosts_$bbsPostId(props: {
  seller: SellerPayload;
  bbsPostId: string & tags.Format<"uuid">;
  body: IShoppingMallAiBbsPost.IUpdate;
}): Promise<IShoppingMallAiBbsPost> {
  const { seller, bbsPostId, body } = props;

  const post = await MyGlobal.prisma.shopping_mall_ai_bbs_posts.findUnique({
    where: { id: bbsPostId },
  });
  if (!post) throw new Error("Post not found");
  if (post.deleted_at !== null) throw new Error("Cannot update a deleted post");
  if (post.shopping_mall_ai_customer_id !== seller.id) {
    throw new Error("Forbidden: Only the post author can update this post.");
  }

  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_mall_ai_bbs_posts.update({
    where: { id: bbsPostId },
    data: {
      title: body.title ?? undefined,
      body: body.body ?? undefined,
      updated_at: now,
    },
  });

  return {
    id: updated.id,
    shopping_mall_ai_channel_id: updated.shopping_mall_ai_channel_id,
    shopping_mall_ai_section_id: updated.shopping_mall_ai_section_id,
    shopping_mall_ai_customer_id: updated.shopping_mall_ai_customer_id,
    title: updated.title,
    body: updated.body,
    ip: updated.ip,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: now,
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
