/**
 * Soft-delete a legal consent record (shopping_mall_ai_legal_consents) by
 * setting the deleted_at field. Does not physically delete the record for audit
 * and compliance purposes. Only accessible by admin.
 *
 * If the specified legal consent record does not exist, or has already been
 * removed via soft delete, this will throw an error (typically resulting in a
 * 404). All requests require admin authentication (props.admin).
 *
 * @param props - Request object containing:
 *
 *   - Admin: authenticated admin payload
 *   - LegalConsentId: unique identifier (UUID) of the legal consent to delete
 *       (soft-delete)
 *
 * @returns Void (fulfills via soft delete)
 * @throws {Error} If the record is not found or already deleted
 */
export async function delete__shopping_mall_ai_admin_legalConsents_$legalConsentId(props: {
  admin: AdminPayload;
  legalConsentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, legalConsentId } = props;

  // Fetch record; ensure it exists and isn't already deleted
  const consent =
    await MyGlobal.prisma.shopping_mall_ai_legal_consents.findFirst({
      where: { id: legalConsentId },
    });
  if (!consent || consent.deleted_at !== null) {
    throw new Error("Not found");
  }

  // Apply soft-delete (set deleted_at)
  await MyGlobal.prisma.shopping_mall_ai_legal_consents.update({
    where: { id: legalConsentId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
}

