 *   IShoppingMallAiInquiry.IRequest).
 * @returns Paginated, filtered list of inquiries matching filters and role
 *   permissions.
 * @throws {Error} If an unexpected database or query error occurs.
 */
export async function patch__shopping_mall_ai_admin_inquiries(props: {
  admin: AdminPayload;
  body: IShoppingMallAiInquiry.IRequest;
}): Promise<IPageIShoppingMallAiInquiry> {
  const { body } = props;
  const filter = body.filter ?? {};
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const sort = body.sort ?? "created_at";
  const order = body.order ?? "desc";

  // Build where condition: only allow fields that exist in the schema
  const where = {
    ...(filter.shopping_mall_ai_product_id !== undefined &&
      filter.shopping_mall_ai_product_id !== null && {
        shopping_mall_ai_product_id: filter.shopping_mall_ai_product_id,
      }),
    ...(filter.shopping_mall_ai_customer_id !== undefined &&
      filter.shopping_mall_ai_customer_id !== null && {
        shopping_mall_ai_customer_id: filter.shopping_mall_ai_customer_id,
