    ...(filter.shopping_mall_ai_seller_id !== undefined &&
      filter.shopping_mall_ai_seller_id !== null && {
        shopping_mall_ai_seller_id: filter.shopping_mall_ai_seller_id,
      }),
    ...(typeof filter.is_private === "boolean" && {
      is_private: filter.is_private,
    }),
    ...(typeof filter.answered === "boolean" &&
      (filter.answered
        ? { answered_at: { not: null } }
        : { answered_at: null })),
    // Add future filter mappings if schema expands
  };

  const [data, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_inquiries.findMany({
      where,
      orderBy: { [sort]: order },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_inquiries.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: data.map((row) => ({
      id: row.id,
      shopping_mall_ai_product_id: row.shopping_mall_ai_product_id,
      shopping_mall_ai_customer_id: row.shopping_mall_ai_customer_id,
      shopping_mall_ai_seller_id: row.shopping_mall_ai_seller_id,
      question: row.question,
      is_private: row.is_private,
      answer: row.answer ?? null,
      answer_marked_helpful: row.answer_marked_helpful ?? null,
