/**
 * Retrieves a paginated list of all order items belonging to a given order,
 * limited to those owned by the authenticated seller.
 *
 * This endpoint enforces access control: sellers may only retrieve order items
 * for products they own; other sellers are denied access. If the order does not
 * exist or does not include any items for this seller, returns a forbidden
 * error.
 *
 * All date-time fields are returned as ISO8601 branded strings.
 *
 * @param props - Function props
 * @param props.seller - Authenticated seller payload (must own the product in
 *   order)
 * @param props.orderId - Unique identifier for the order (uuid)
 * @returns Paginated result of order item DTOs owned by the seller
 * @throws {Error} When order does not exist, seller does not own any products
 *   in order, or unauthorized access is attempted.
 */
export async function get__shopping_mall_ai_seller_orders_$orderId_orderItems(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
}): Promise<IPageIShoppingOrderItem> {
  const { seller, orderId } = props;

  // Find all order items for this order owned by this seller via product relationship
  const items = await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
    where: {
      shopping_mall_ai_order_id: orderId,
      product: {
        shopping_mall_ai_seller_id: seller.id,
      },
    },
    orderBy: { created_at: "asc" },
  });

  // Throw error if unauthorized/no items
  if (!items.length)
    throw new Error("Forbidden or order not found for this seller.");

  // Map each item to DTO, converting date fields with toISOStringSafe
  const data: IShoppingOrderItem[] = items.map((item) => ({
    id: item.id,
    shopping_mall_ai_order_id: item.shopping_mall_ai_order_id,
    shopping_mall_ai_product_id: item.shopping_mall_ai_product_id,
    shopping_mall_ai_product_option_id:
      item.shopping_mall_ai_product_option_id ?? null,
    price: item.price,
    quantity: item.quantity,
    status: item.status,
    created_at: toISOStringSafe(item.created_at),
    updated_at: toISOStringSafe(item.updated_at),
  }));

  // Pagination: all results in a single page (default, as no page/limit params supplied)
  return {
    pagination: {
      current: 1,
      limit: 100,
      records: data.length as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: 1 as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data,
  };
}

