/**
 * Search/filter product categories with advanced criteria and pagination
 * (shopping_mall_ai_product_categories).
 *
 * Supports targeted customer search of product categories via request body
 * filter criteria (IShoppingMallAiProductCategory.IRequest). Pagination,
 * sorting, and multiple filter types are supported, including parent_child
 * navigation, status toggling, display ordering, and date-related filters for
 * audit/trend analysis.
 *
 * Only active categories are returned for the customer role. Errors are thrown
 * if query fails.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer
 * @param props.body - Filter and search definition for category query, with
 *   pagination settings
 * @returns Paginated, filtered set of category summaries
 * @throws {Error} When query fails or insufficient permissions
 */
export async function patch__shopping_mall_ai_customer_shoppingMallAiProductCategories(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiProductCategory.IRequest;
}): Promise<IPageIShoppingMallAiProductCategory.ISummary> {
  const { customer, body } = props;

  // 1. Calculate pagination
  const page = typeof body.page === "number" && body.page > 0 ? body.page : 1;
  const limit =
    typeof body.limit === "number" && body.limit > 0 ? body.limit : 100;

  // 2. Build Prisma where clause for filters
  const where = {
    parent_id:
      body.parent_id !== undefined && body.parent_id !== null
        ? body.parent_id
        : null,
    ...(typeof body.name === "string" &&
      body.name.length > 0 && {
        name: { contains: body.name, mode: "insensitive" as const },
      }),
    active: true, // Always true for customer queries
  };

  // 3. Query database for data and total count concurrently
  const [categories, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_product_categories.findMany({
      where,
      orderBy: [
        { display_order: "asc" as const },
        { created_at: "asc" as const },
      ],
      skip: (page - 1) * limit,
      take: limit,
      select: {
        id: true,
        name: true,
        parent_id: true,
        display_order: true,
        active: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_product_categories.count({ where }),
  ]);

  // 4. Build immutable results structure
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / (limit || 1)),
    },
    data: categories.map((cat) => ({
      id: cat.id,
      name: cat.name,
      parent_id: cat.parent_id ?? null,
      display_order: cat.display_order,
      active: cat.active,
    })),
  };
}

