import { IPageIShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingOrderItem";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Advanced filtered and paginated search of order items for a given order.
 *
 * This operation powers robust, paginated searches and filtered retrieval of
 * order items linked to a particular order, enforcing seller ownership via
 * order-product mapping. The operation returns a paginated structure matching
 * IPageIShoppingOrderItem, with strict transformation of date fields and robust
 * type enforcement throughout.
 *
 * @param props - Properties for the search
 * @param props.seller - Authenticated seller performing query
 * @param props.orderId - Target order UUID
 * @param props.body - Filter/pagination criteria for items within the order
 * @returns A paginated list of detailed order item records, all belonging to
 *   products owned/managed by the seller
 * @throws {Error} When the order does not exist or the seller is not authorized
 */
export async function patch__shopping_mall_ai_seller_orders_$orderId_orderItems(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingOrderItem.IRequest;
}): Promise<IPageIShoppingOrderItem> {
  const { seller, orderId, body } = props;
  const {
    page: pageRaw,
    limit: limitRaw,
    shopping_mall_ai_product_id,
    status,
    created_from,
    created_to,
  } = body;
  // Pagination enforcement
  const maxLimit = 100;
  const page = Math.max(Number(pageRaw ?? 1), 1);
  const limit = Math.max(Math.min(Number(limitRaw ?? 20), maxLimit), 1);
  const skip = (page - 1) * limit;

  // Verify order exists
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
  });
  if (!order) throw new Error("Order not found");

  // Find all order item product IDs for this order
  const itemProductIds = (
    await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where: { shopping_mall_ai_order_id: orderId },
      select: { shopping_mall_ai_product_id: true },
    })
  ).map((r) => r.shopping_mall_ai_product_id);

  // Check that all products are owned by seller
  if (itemProductIds.length > 0) {
    const sellerOwns = await MyGlobal.prisma.shopping_mall_ai_products.count({
      where: {
        id: { in: itemProductIds },
        shopping_mall_ai_seller_id: seller.id,
      },
    });
    if (sellerOwns < itemProductIds.length) {
      throw new Error(
        "Unauthorized: Seller does not own all products in this order",
      );
    }
  }

  // Build where clause for filters
  const where = {
    shopping_mall_ai_order_id: orderId,
    ...(shopping_mall_ai_product_id !== undefined &&
      shopping_mall_ai_product_id !== null && {
        shopping_mall_ai_product_id,
      }),
    ...(status !== undefined &&
      status !== null && {
        status,
      }),
    ...((created_from !== undefined && created_from !== null) ||
    (created_to !== undefined && created_to !== null)
      ? {
          created_at: {
            ...(created_from !== undefined &&
              created_from !== null && {
                gte: created_from,
              }),
            ...(created_to !== undefined &&
              created_to !== null && {
                lte: created_to,
              }),
          },
        }
      : {}),
  };

  // Fetch order items and count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where,
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
    }),
    MyGlobal.prisma.shopping_mall_ai_order_items.count({ where }),
  ]);

  // Format to IShoppingOrderItem, converting Date fields
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.max(1, Math.ceil(total / limit)),
    },
    data: rows.map((row) => ({
      id: row.id,
      shopping_mall_ai_order_id: row.shopping_mall_ai_order_id,
      shopping_mall_ai_product_id: row.shopping_mall_ai_product_id,
      shopping_mall_ai_product_option_id:
        row.shopping_mall_ai_product_option_id ?? null,
      price: row.price,
      quantity: row.quantity,
      status: row.status,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    })),
  };
}

