    });

  // 3. 불변 필드 변조 시도 차단
  if (
    Object.prototype.hasOwnProperty.call(body, "shopping_mall_ai_file_id") ||
    Object.prototype.hasOwnProperty.call(body, "created_at")
  ) {
    throw new Error(
