 * @param props.admin - Payload of the authenticated admin (authorization
 *   enforced before logic)
 * @returns Paginated result containing moderation event summaries and page
 *   metadata
 * @throws {Error} If database access fails
 */
export async function get__shopping_mall_ai_admin_contentModerations(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingContentModeration.ISummary> {
  const page = 1 as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;
  const limit = 50 as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;

