import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiProductOption";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Registers a new product option (variant) for a seller-owned product in
 * shopping_mall_ai_product_options.
 *
 * This endpoint allows an authenticated seller to add a new option (such as a
 * size or color variant) to one of their listed products. The seller must own
 * the product they're attaching the option to, and each option SKU must be
 * unique within the parent product. Audit fields and PK are system-generated.
 * Attempts to violate SKU uniqueness, create options for a nonexistent or
 * unauthorized product will result in a rejected request.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller (from SellerAuth decorator)
 * @param props.body - New option creation data (must include parent product id,
 *   name, value, unique option_sku)
 * @returns The created option record with full catalog/audit fields
 * @throws {Error} When product does not exist, does not belong to seller, or
 *   SKU is duplicated
 */
export async function post__shopping_mall_ai_seller_shoppingMallAiProductOptions(props: {
  seller: SellerPayload;
  body: IShoppingMallAiProductOption.ICreate;
}): Promise<IShoppingMallAiProductOption> {
  const { seller, body } = props;

  // Step 1: Ensure target product exists and is owned by this seller
  const product = await MyGlobal.prisma.shopping_mall_ai_products.findUnique({
    where: { id: body.shopping_mall_ai_product_id },
  });
  if (!product) {
    throw new Error("Product not found");
  }
  if (product.shopping_mall_ai_seller_id !== seller.id) {
    throw new Error(
      "Unauthorized: Cannot add options to a product you do not own",
    );
  }

  // Step 2: Prepare new product option payload
  const now = toISOStringSafe(new Date());
  let created;
  try {
    created = await MyGlobal.prisma.shopping_mall_ai_product_options.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
        name: body.name,
        value: body.value,
        option_sku: body.option_sku,
        created_at: now,
        updated_at: now,
      },
    });
  } catch (exp) {
    // Prisma error codes: P2002 is unique constraint violation for option_sku
    if (
      typeof exp === "object" &&
      exp !== null &&
      "code" in exp &&
      (exp as any).code === "P2002"
    ) {
      throw new Error("Duplicate option_sku for this product.");
    }
    throw exp;
  }
  return {
    id: created.id,
    shopping_mall_ai_product_id: created.shopping_mall_ai_product_id,
    name: created.name,
    value: created.value,
    option_sku: created.option_sku,
    created_at: now, // re-use prepared timestamp to guarantee branded string
    updated_at: now,
  };
}

