import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * 고급 검색 및 쇼핑몰 게시글(BBS) 필터링 (shopping_mall_ai_bbs_posts).
 *
 * 이 엔드포인트는 판매자 인증을 받아, 쇼핑몰 게시글(BBS) 리스트를 상세하게 검색/필터링 할 수 있는 기능을 제공합니다. 쿼리 옵션에는
 * 게시글 채널/섹션/작성자, 제목(키워드) 부분 검색, 생성일 범위, 활성글 여부(soft delete 미포함) 조건 등이 포함됩니다. 오직
 * 삭제되지 않은 게시물만 기본적으로 조회됩니다(deleted_at == null). 결과는 페이지네이션·정렬 및 게시글 목록 요약 정보로
 * 반환됩니다.
 *
 * @param props - 요청 프로퍼티
 * @param props.seller - 인증된 판매자 정보
 * @param props.body - 포럼(게시판) 게시글 검색·필터 파라미터
 * @returns 검색 조건/페이지에 맞는 BBS 게시글 요약 목록(페이지네이션 정보 포함)
 * @throws {Error} 필터 파라미터가 잘못되었거나, 내부 오류 발생 시
 */
export async function patch__shopping_mall_ai_seller_bbsPosts(props: {
  seller: SellerPayload;
  body: IShoppingMallAiBbsPost.IRequest;
}): Promise<IPageIShoppingMallAiBbsPost.ISummary> {
  const { body } = props;
  // 페이지네이션 처리 (page 1-base, 기본값 적용)
  const page = body.page != null ? body.page : 1;
  const limit = body.limit != null ? body.limit : 20;
  const skip = (page - 1) * limit;

  // 복합 where절 생성
  const where = {
    ...(body.shopping_mall_ai_channel_id !== undefined &&
      body.shopping_mall_ai_channel_id !== null && {
        shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id,
      }),
    ...(body.shopping_mall_ai_section_id !== undefined &&
      body.shopping_mall_ai_section_id !== null && {
        shopping_mall_ai_section_id: body.shopping_mall_ai_section_id,
      }),
    ...(body.shopping_mall_ai_customer_id !== undefined &&
      body.shopping_mall_ai_customer_id !== null && {
        shopping_mall_ai_customer_id: body.shopping_mall_ai_customer_id,
      }),
    ...(body.title !== undefined &&
      body.title !== null &&
      body.title.trim().length > 0 && {
        title: { contains: body.title, mode: "insensitive" as const },
      }),
    ...((body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && { gte: body.created_from }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && { lte: body.created_to }),
          },
        }
      : {}),
    // active_only==undefined/null/true -> 미삭제글만 조회. false면 삭제포함 전체 조회
    ...(body.active_only === undefined ||
    body.active_only === null ||
    body.active_only === true
      ? { deleted_at: null }
      : {}),
  };

  // 총 개수와 페이지 데이터 동시 조회
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_bbs_posts.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_bbs_posts.count({ where }),
  ]);

  // 게시글별 작성자 customer id -> 닉네임 매핑
  const customerIds = Array.from(
    new Set(rows.map((row) => row.shopping_mall_ai_customer_id)),
  );
  const customers = await MyGlobal.prisma.shopping_mall_ai_customers.findMany({
    where: { id: { in: customerIds } },
    select: { id: true, nickname: true },
  });
  const customerMap = new Map<string, string>(
    customers.map((c) => [c.id, c.nickname]),
  );

  // 반환 데이터 변환 (모든 date 필드 toISOStringSafe)
  const data = rows.map((row) => ({
    id: row.id,
    title: row.title,
    shopping_mall_ai_section_id: row.shopping_mall_ai_section_id,
    shopping_mall_ai_channel_id: row.shopping_mall_ai_channel_id,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    author_nickname: customerMap.get(row.shopping_mall_ai_customer_id) ?? "",
  }));

  // 페이지네이션 메타
  const pagination = {
    current: page,
    limit: limit,
    records: total,
    pages: Math.ceil(total / limit),
  };

  return { pagination, data };
}

