 *
 * Creates a new deposit (store credit) for a user by authenticated admin. This
 * endpoint ensures business rules are satisfied by preventing duplicate
 * deposits for the same customer, origin, and status combination. Returns the
 * fully persisted deposit record.
 *
 * @param props - Request parameters
 * @param props.admin - The authenticated admin performing the operation
 *   (AdminPayload authentication)
 * @param props.body - The deposit creation input
 *   (IShoppingMallAiDeposit.ICreate)
 * @returns The newly created deposit record (IShoppingMallAiDeposit)
 * @throws {Error} If a deposit for the same customer with the same origin and
 *   status already exists (business rule violation)
 */
export async function post__shopping_mall_ai_admin_deposits(props: {
  admin: AdminPayload;
  body: IShoppingMallAiDeposit.ICreate;
}): Promise<IShoppingMallAiDeposit> {
  const { admin, body } = props;

  // Prevent duplicate deposit for the same customer, origin, and status (business rule)
  const exists = await MyGlobal.prisma.shopping_mall_ai_deposits.findFirst({
    where: {
      shopping_mall_ai_customer_id: body.shopping_mall_ai_customer_id,
      origin: body.origin,
      status: body.status,
    },
  });
  if (exists) {
    throw new Error(
      "A deposit with the same customer, origin, and status already exists",
    );
  }

  // Prepare the new deposit fields
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());

  // Create the deposit
  const created = await MyGlobal.prisma.shopping_mall_ai_deposits.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_ai_customer_id: body.shopping_mall_ai_customer_id,
      balance: body.balance,
      updated_at: now,
      status: body.status,
      origin: body.origin,
      expires_at: body.expires_at ?? undefined,
    },
  });

  // Return the DTO with all string dates properly formatted
  return {
    id: created.id as string & tags.Format<"uuid">,
    shopping_mall_ai_customer_id:
      created.shopping_mall_ai_customer_id as string & tags.Format<"uuid">,
    balance: created.balance,
    updated_at: toISOStringSafe(created.updated_at),
    status: created.status,
    origin: created.origin,
    expires_at: created.expires_at ? toISOStringSafe(created.expires_at) : null,
