 * owns at least one product in the order, and only allows updates to permitted
 * shipment fields (status, tracking_number, provider). Returns updated shipment
 * record.
 *
 * @param props - Function properties
 * @param props.seller - Authenticated SellerPayload
 * @param props.orderId - Order that owns the shipment
 * @param props.shipmentId - ID of the shipment to update
 * @param props.body - IShoppingMallAiShipment.IUpdate; only mutable fields are
 *   permitted
 * @returns The updated IShoppingMallAiShipment record
 * @throws {Error} If shipment/order not found, association check fails, or not
 *   authorized
 */
export async function put__shopping_mall_ai_seller_orders_$orderId_shipments_$shipmentId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  shipmentId: string & tags.Format<"uuid">;
  body: IShoppingMallAiShipment.IUpdate;
}): Promise<IShoppingMallAiShipment> {
  const { seller, orderId, shipmentId, body } = props;
  // Step 1: Fetch shipment and verify association
  const shipment = await MyGlobal.prisma.shopping_mall_ai_shipments.findUnique({
    where: { id: shipmentId },
  });
  if (!shipment || shipment.shopping_mall_ai_order_id !== orderId) {
    throw new Error("Shipment not found or does not belong to specified order");
  }
  // Step 2: Fetch the associated order
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
  });
  if (!order) {
    throw new Error("Order not found");
  }
  // Step 3: Confirm seller owns at least one product in this order
  const orderItems =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where: { shopping_mall_ai_order_id: orderId },
    });
  if (!orderItems.length) {
    throw new Error("No items found for this order");
  }
  const productIds = orderItems.map((item) => item.shopping_mall_ai_product_id);
  const ownedProducts =
    await MyGlobal.prisma.shopping_mall_ai_products.findMany({
      where: {
        id: { in: productIds },
        shopping_mall_ai_seller_id: seller.id,
      },
    });
  if (!ownedProducts.length) {
    throw new Error(
      "Unauthorized: Seller does not own any products in this order",
    );
  }
  // Step 4: Update only allowed/mutable fields
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_mall_ai_shipments.update({
    where: { id: shipmentId },
    data: {
      status: body.status ?? undefined,
      tracking_number: body.tracking_number ?? undefined,
      provider: body.provider ?? undefined,
      updated_at: now,
    },
  });
  // Step 5: Return strictly typed, formatted result
  return {
    id: updated.id,
    shopping_mall_ai_order_id: updated.shopping_mall_ai_order_id,
    status: updated.status,
    tracking_number:
      typeof updated.tracking_number === "undefined"
        ? null
        : updated.tracking_number,
    provider: typeof updated.provider === "undefined" ? null : updated.provider,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

