import { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Update a specific item in a shopping cart.
 *
 * This endpoint allows an admin to update the quantity and/or product option
 * (variant/SKU) of an existing cart item, referenced by its parent cart and its
 * own unique ID. Ensures referential integrity and that updates obey inventory
 * constraints—even admins cannot exceed available inventory. Optionally, the
 * item variant may be changed, but only to an option belonging to the same
 * product.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin user (authorization enforced by
 *   decorator)
 * @param props.cartId - UUID of the cart containing the item
 * @param props.cartItemId - UUID of the specific cart item to update
 * @param props.body - Fields to update: quantity (required),
 *   shopping_mall_ai_product_option_id (optional/null for base product)
 * @returns Updated cart item reflecting the change (with all metadata and
 *   timestamps)
 * @throws {Error} If cart or cart item is not found, item not owned by cart,
 *   option is invalid, quantity is illegal, or inventory is insufficient
 */
export async function put__shopping_mall_ai_admin_carts_$cartId_cartItems_$cartItemId(props: {
  admin: AdminPayload;
  cartId: string & tags.Format<"uuid">;
  cartItemId: string & tags.Format<"uuid">;
  body: IShoppingMallAiCartItem.IUpdate;
}): Promise<IShoppingMallAiCartItem> {
  const { admin, cartId, cartItemId, body } = props;

  // 1. Fetch and validate cart
  const cart = await MyGlobal.prisma.shopping_mall_ai_carts.findUnique({
    where: { id: cartId },
  });
  if (!cart) throw new Error("Cart not found");

  // 2. Fetch and validate cart item
  const item = await MyGlobal.prisma.shopping_mall_ai_cart_items.findUnique({
    where: { id: cartItemId },
  });
  if (!item) throw new Error("Cart item not found");
  if (item.shopping_mall_ai_cart_id !== cartId) {
    throw new Error("Cart item does not belong to the specified cart");
  }

  // 3. Validate quantity
  if (
    typeof body.quantity !== "number" ||
    !Number.isInteger(body.quantity) ||
    body.quantity <= 0
  ) {
    throw new Error("Quantity must be a positive integer");
  }

  // 4. Validate product option (if updating to a specific option)
  let validatedOptionId: (string & tags.Format<"uuid">) | null | undefined =
    undefined;
  if (body.shopping_mall_ai_product_option_id !== undefined) {
    if (body.shopping_mall_ai_product_option_id === null) {
      validatedOptionId = null;
    } else {
      // Must be a valid option belonging to the same product as the cart item
      const option =
        await MyGlobal.prisma.shopping_mall_ai_product_options.findUnique({
          where: { id: body.shopping_mall_ai_product_option_id },
        });
      if (
        !option ||
        option.shopping_mall_ai_product_id !== item.shopping_mall_ai_product_id
      ) {
        throw new Error("Invalid product option for this cart item");
      }
      validatedOptionId = body.shopping_mall_ai_product_option_id;
    }
  }

  // 5. Inventory validation: ensure requested quantity is available (option-specific if present)
  const inventory =
    await MyGlobal.prisma.shopping_mall_ai_inventories.findFirst({
      where: {
        shopping_mall_ai_product_id: item.shopping_mall_ai_product_id,
        shopping_mall_ai_product_option_id:
          validatedOptionId !== undefined
            ? validatedOptionId
            : (item.shopping_mall_ai_product_option_id ?? null),
      },
    });
  if (!inventory) throw new Error("Inventory record not found");
  const available = inventory.quantity - inventory.reserved_quantity;
  if (body.quantity > available) {
    throw new Error("Insufficient inventory for the requested quantity");
  }

  // 6. Perform update
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_mall_ai_cart_items.update({
    where: { id: cartItemId },
    data: {
      quantity: body.quantity,
      shopping_mall_ai_product_option_id: validatedOptionId,
      updated_at: now,
    },
  });

  // 7. Return updated item (with ISO-branded dates)
  return {
    id: updated.id,
    shopping_mall_ai_cart_id: updated.shopping_mall_ai_cart_id,
    shopping_mall_ai_product_id: updated.shopping_mall_ai_product_id,
    shopping_mall_ai_product_option_id:
      updated.shopping_mall_ai_product_option_id ?? undefined,
    quantity: updated.quantity,
    added_at: toISOStringSafe(updated.added_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

