import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Retrieves all non-deleted (deleted_at = null) comments for the given BBS
 * post, paginated and ordered, including threading (parent_id). Only
 * authenticated customers may access this endpoint. Returns a paginated list
 * with parent_id for client-side threading.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer (payload)
 * @param props.bbsPostId - UUID of the BBS post to fetch comments for
 * @returns Paginated IPageIShoppingMallAiBbsComment, with all comment date
 *   fields as ISO8601 strings
 * @throws {Error} If the post ID is invalid or other query errors occur
 */
export async function get__shopping_mall_ai_customer_bbsPosts_$bbsPostId_bbsComments(props: {
  customer: CustomerPayload;
  bbsPostId: string & tags.Format<"uuid">;
}): Promise<IPageIShoppingMallAiBbsComment> {
  const { bbsPostId } = props;

  // Pagination fixed: page 1, limit 100
  const page = 1;
  const limit = 100;

  // Step 1: Count total non-deleted comments for this post
  const totalRecords =
    await MyGlobal.prisma.shopping_mall_ai_bbs_comments.count({
      where: {
        shopping_mall_ai_bbs_post_id: bbsPostId,
        deleted_at: null,
      },
    });

  // Step 2: Fetch paginated comments (ordered by created_at, ascending)
  const rows = await MyGlobal.prisma.shopping_mall_ai_bbs_comments.findMany({
    where: {
      shopping_mall_ai_bbs_post_id: bbsPostId,
      deleted_at: null,
    },
    orderBy: { created_at: "asc" },
    skip: (page - 1) * limit,
    take: limit,
  });

  // Step 3: Map rows to DTO, ensuring ISO string conversion for dates
  const data = rows.map(
    (row): IShoppingMallAiBbsComment => ({
      id: row.id,
      shopping_mall_ai_bbs_post_id: row.shopping_mall_ai_bbs_post_id,
      shopping_mall_ai_customer_id: row.shopping_mall_ai_customer_id,
      parent_id: row.parent_id ?? null,
      body: row.body,
      ip: row.ip,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
      deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
    }),
  );

  // Step 4: Return paginated DTO
  return {
    pagination: {
      current: page,
      limit,
      records: totalRecords,
      pages: Math.ceil(totalRecords / limit),
    },
    data,
  };
}

