/**
 * 고급 필터로 법적 동의(legal consent) 레코드를 조회합니다.
 *
 * 이 엔드포인트는 관리자의 승인 하에 제공되며, 다양한 검색 기준(유저, 정책, 버전, 방법, 기간, IP, 삭제/철회 상태 등)을 기반으로
 * 법적 동의 기록을 페이징하여 반환합니다. 쿼리 결과는 감사, 드릴다운, 고객 법률 서비스 제공을 지원하며, 모든 결과는 원본 기록의
 * 신뢰성을 보장합니다.
 *
 * @param props - 요청 속성 (인증된 관리자, 검색 DTO)
 * @param props.admin - 인증된 관리자 페이로드 (AdminAuth 데코레이터로 주입)
 * @param props.body - 검색 및 페이징 파라미터 (IShoppingMallAiLegalConsent.IRequest)
 * @returns {IPageIShoppingMallAiLegalConsent} 복합 기준에 맞는 법적 동의 목록(페이지네이션 포함)
 * @throws {Error} 인증되지 않았거나 요청이 잘못된 경우
 */
export async function patch__shopping_mall_ai_admin_legalConsents(props: {
  admin: AdminPayload;
  body: IShoppingMallAiLegalConsent.IRequest;
}): Promise<IPageIShoppingMallAiLegalConsent> {
  const { admin, body } = props;

  // 페이지네이션 설정 (기본값: page=1, limit=100)
  const page = body.page ?? 1;
  const limit = body.limit ?? 100;
  const skip = (page - 1) * limit;

  // 동적 where 조건
  const where = {
    ...(body.user_id ? { user_id: body.user_id } : {}),
    ...(body.policy_code ? { policy_code: body.policy_code } : {}),
    ...(body.policy_version ? { policy_version: body.policy_version } : {}),
    ...(body.consent_method ? { consent_method: body.consent_method } : {}),
    // deleted_at는 null도 허용, 명시적으로 undefined가 아닌 경우만 포함
    ...(body.deleted_at !== undefined ? { deleted_at: body.deleted_at } : {}),
    // consented_at: 날짜 범위(gte, lte)
    ...((body.consented_at_from !== undefined &&
      body.consented_at_from !== null) ||
    (body.consented_at_to !== undefined && body.consented_at_to !== null)
      ? {
          consented_at: {
            ...(body.consented_at_from !== undefined &&
              body.consented_at_from !== null && {
                gte: body.consented_at_from,
              }),
            ...(body.consented_at_to !== undefined &&
              body.consented_at_to !== null && {
                lte: body.consented_at_to,
              }),
          },
        }
      : {}),
    // withdrawn_at: 날짜 범위(gte, lte), withdrawn_at은 null 허용
    ...((body.withdrawn_at_from !== undefined &&
      body.withdrawn_at_from !== null) ||
    (body.withdrawn_at_to !== undefined && body.withdrawn_at_to !== null)
      ? {
          withdrawn_at: {
            ...(body.withdrawn_at_from !== undefined &&
              body.withdrawn_at_from !== null && {
                gte: body.withdrawn_at_from,
              }),
            ...(body.withdrawn_at_to !== undefined &&
              body.withdrawn_at_to !== null && {
                lte: body.withdrawn_at_to,
              }),
          },
        }
      : {}),
  };

  // 페이징/필터 결과 및 총 개수 동시 조회
  const [records, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_legal_consents.findMany({
      where,
      orderBy: { consented_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_legal_consents.count({ where }),
  ]);

  // 결과 변환 (DateTime -> string & tags.Format<'date-time'>)
  const data = records.map((row) => ({
    id: row.id,
    user_id: row.user_id,
    policy_code: row.policy_code,
    policy_version: row.policy_version,
    consented_at: toISOStringSafe(row.consented_at),
    consent_method: row.consent_method,
    withdrawn_at:
      row.withdrawn_at !== null && row.withdrawn_at !== undefined
        ? toISOStringSafe(row.withdrawn_at)
        : null,
    consent_ip: row.consent_ip ?? null,
    deleted_at:
      row.deleted_at !== null && row.deleted_at !== undefined
        ? toISOStringSafe(row.deleted_at)
        : null,
  }));

  // 페이지네이션 정보 반환
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

