/**
 * Update a shipment for a given order (shopping_mall_ai_shipments table).
 *
 * Allows platform admins to modify shipment fields such as status, tracking
 * number, or provider for a shipment associated with a specific order.
 *
 * Only administrators (AdminPayload) may update shipments. The function
 * enforces that the target shipment both exists and belongs to the specified
 * order, preventing cross-order tampering. It only allows the status,
 * tracking_number, and provider fields to be changed.
 *
 * All date and timestamp fields use string & tags.Format<'date-time'>, with
 * conversion via toISOStringSafe; native Date is never used in type
 * assignments. All values are immutable and strictly typed.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin user performing the update (platform
 *   authorization enforced)
 * @param props.orderId - The order ID which the shipment belongs to
 * @param props.shipmentId - The shipment ID to update
 * @param props.body - Partial update, only allowed fields (status,
 *   tracking_number, provider)
 * @returns The updated shipment
 * @throws {Error} When the shipment does not exist, or does not belong to the
 *   specified order ID
 */
export async function put__shopping_mall_ai_admin_orders_$orderId_shipments_$shipmentId(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  shipmentId: string & tags.Format<"uuid">;
  body: IShoppingMallAiShipment.IUpdate;
}): Promise<IShoppingMallAiShipment> {
  const { orderId, shipmentId, body } = props;

  // STEP 1: Confirm the shipment exists and belongs to specified order
  const shipment = await MyGlobal.prisma.shopping_mall_ai_shipments.findUnique({
    where: { id: shipmentId },
  });
  if (!shipment || shipment.shopping_mall_ai_order_id !== orderId) {
    throw new Error("Not found or shipment does not match the order");
  }

  // STEP 2: Update only permitted, mutable fields
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_mall_ai_shipments.update({
    where: { id: shipmentId },
    data: {
      status: body.status ?? shipment.status,
      tracking_number:
        body.tracking_number !== undefined
          ? body.tracking_number
          : shipment.tracking_number,
      provider: body.provider !== undefined ? body.provider : shipment.provider,
      updated_at: now,
    },
  });

  // STEP 3: Strictly structure and return DTO
  return {
    id: updated.id,
    shopping_mall_ai_order_id: updated.shopping_mall_ai_order_id,
    status: updated.status,
    tracking_number: updated.tracking_number ?? null,
    provider: updated.provider ?? null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

