import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderItem";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Create a new order item in a specified order (shopping_mall_ai_order_items).
 *
 * This endpoint allows a seller to create a new order item under a given
 * orderId. It enforces that the seller owns the product being added, and that
 * the order belongs to a channel the seller operates in. Duplicate order items
 * (same order, product, and, if applicable, option) are not permitted. Business
 * rules enforce referential integrity and avoid item-level conflicts.
 *
 * @param props - Function props
 * @param props.seller - Authenticated Seller account payload (JWT). Must be
 *   active and verified.
 * @param props.orderId - Target order UUID. The order must be accessible for
 *   this seller (matching seller's channel).
 * @param props.body - Item creation details (see IShoppingOrderItem.ICreate).
 *   Must provide valid product and optional product option IDs.
 * @returns The newly created IShoppingOrderItem, including system-generated IDs
 *   and timestamps.
 * @throws {Error} If ownership checks or referential integrity validation
 *   fails, or if a duplicate order item exists.
 */
export async function post__shopping_mall_ai_seller_orders_$orderId_orderItems(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingOrderItem.ICreate;
}): Promise<IShoppingOrderItem> {
  const { seller, orderId, body } = props;

  // 1. Verify order exists
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findFirst({
    where: { id: orderId },
  });
  if (!order) throw new Error("Order not found");

  // 2. Check product exists and is owned by this seller
  const product = await MyGlobal.prisma.shopping_mall_ai_products.findFirst({
    where: { id: body.shopping_mall_ai_product_id },
  });
  if (!product) throw new Error("Product not found");
  if (product.shopping_mall_ai_seller_id !== seller.id)
    throw new Error("Forbidden: Product does not belong to seller");

  // 3. If option id present, check it exists and belongs to the product
  if (body.shopping_mall_ai_product_option_id) {
    const option =
      await MyGlobal.prisma.shopping_mall_ai_product_options.findFirst({
        where: {
          id: body.shopping_mall_ai_product_option_id,
          shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
        },
      });
    if (!option) {
      throw new Error("Product option not found or does not belong to product");
    }
  }

  // 4. Check duplicate row (same order/product/option)
  const duplicate =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findFirst({
      where: {
        shopping_mall_ai_order_id: orderId,
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
        shopping_mall_ai_product_option_id:
          body.shopping_mall_ai_product_option_id ?? null,
      },
    });
  if (duplicate) {
    throw new Error(
      "Order item with same product and option already exists in this order",
    );
  }

