/**
 * Soft delete (logical delete) a product inquiry by inquiryId.
 *
 * Soft deletes a product inquiry by setting its deleted_at timestamp. Only the
 * customer who created the question may remove an inquiry; sellers are not
 * authorized.
 *
 * This operation retains the inquiry for audit/compliance purposes and removes
 * it from all standard queries. The record remains in the database but is
 * omitted from API responses by default.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer attempting to delete the
 *   inquiry
 * @param props.inquiryId - Target inquiry’s ID (UUID) to (soft) delete
 * @returns Void
 * @throws {Error} When the inquiry does not exist or is already deleted
 * @throws {Error} When the authenticated customer is not the author
 */
export async function delete__shopping_mall_ai_customer_inquiries_$inquiryId(props: {
  customer: CustomerPayload;
  inquiryId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, inquiryId } = props;
  // 1. Fetch inquiry (if not found or was already deleted, throw 404)
  const inquiry = await MyGlobal.prisma.shopping_mall_ai_inquiries.findFirst({
    where: { id: inquiryId, deleted_at: null },
  });
  if (!inquiry) {
    throw new Error("Inquiry not found");
  }
  // 2. Only the customer who created may delete
  if (inquiry.shopping_mall_ai_customer_id !== customer.id) {
    throw new Error("Forbidden: Only the author can delete this inquiry");
  }
  // 3. Soft delete (set deleted_at to now)
  await MyGlobal.prisma.shopping_mall_ai_inquiries.update({
    where: { id: inquiryId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
}

