 *
 * This endpoint allows creation of a new order item under a given orderId. The
 * required payload (IShoppingOrderItem.ICreate) must contain all atomic item
 * fields such as product reference, optional variant/option, unit price,
 * quantity, and initial item status. The endpoint checks referential integrity
 * (orderId and productId must exist, links must match order context). Only
 * authorized system actors (typically admin, or seller in fulfillment error
 * scenarios) may use this endpoint—customer direct use is typically not
 * permitted.
 *
 * Business logic checks for duplicate item entries, enforces item-level
 * constraints, and records all item creation for audit and compliance purposes.
 * Successful requests return the fully instantiated order item object,
 * including system-generated fields such as timestamps. On error, validation
 * messages provide actionable feedback for correction.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin making the request (validated by
 *   decorator)
 * @param props.orderId - Order ID where the new item will be created
 * @param props.body - Details for the new order item
 *   (IShoppingOrderItem.ICreate)
 * @returns Created order item record with all fields and system-generated
 *   timestamps
 * @throws {Error} If referenced order, product, or option does not exist; or if
 *   duplicate item exists
 */
export async function post__shopping_mall_ai_admin_orders_$orderId_orderItems(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingOrderItem.ICreate;
}): Promise<IShoppingOrderItem> {
  const { admin, orderId, body } = props;

  // 1. Authorization: handled by decorator; admin is validated

  // 2. Validate order existence
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: { id: true },
  });
  if (!order) throw new Error("Order not found");

  // 3. Validate product existence
  const product = await MyGlobal.prisma.shopping_mall_ai_products.findUnique({
    where: { id: body.shopping_mall_ai_product_id },
    select: { id: true },
  });
  if (!product) throw new Error("Product not found");

  // 4. Validate product option existence if provided
  if (body.shopping_mall_ai_product_option_id != null) {
    const option =
      await MyGlobal.prisma.shopping_mall_ai_product_options.findUnique({
        where: { id: body.shopping_mall_ai_product_option_id },
        select: { id: true },
      });
    if (!option) throw new Error("Product option not found");
  }

  // 5. Prevent duplicate order item (by product and option)
  const duplicate =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findFirst({
      where: {
        shopping_mall_ai_order_id: orderId,
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
        shopping_mall_ai_product_option_id:
          body.shopping_mall_ai_product_option_id ?? null,
      },
      select: { id: true },
    });
  if (duplicate)
    throw new Error(
      "Duplicate order item (same product/option) is not allowed",
    );

  // 6. Create order item with system-generated id and timestamps
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_order_items.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_ai_order_id: orderId,
      shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
      shopping_mall_ai_product_option_id:
        body.shopping_mall_ai_product_option_id ?? null,
      price: body.price,
      quantity: body.quantity,
      status: body.status,
      created_at: now,
      updated_at: now,
    },
  });

  return {
    id: created.id,
    shopping_mall_ai_order_id: created.shopping_mall_ai_order_id,
    shopping_mall_ai_product_id: created.shopping_mall_ai_product_id,
    shopping_mall_ai_product_option_id:
      created.shopping_mall_ai_product_option_id ?? null,
    price: created.price,
    quantity: created.quantity,
    status: created.status,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

