 * Irreversibly removes a product option/variant identified by its UUID from the
 * shopping_mall_ai_product_options table. Only the owning seller (authenticated
 * via SellerPayload) may perform this deletion. All successful deletions are
 * recorded in the audit log (shopping_mall_ai_audit_logs) for compliance
 * purposes. Attempts to delete options belonging to other sellers or
 * non-existent options will result in errors. Deletions may fail if other
 * dependent data (such as inventory or order lines) reference this option.
 *
 * @param props - Parameters for the operation.
 * @param props.seller - The authenticated seller (must be owner of the product
 *   option).
 * @param props.shoppingMallAiProductOptionId - UUID of the option/variant to
 *   delete.
 * @returns Void
 * @throws {Error} If the product option does not exist.
 * @throws {Error} If the product option does not belong to the seller.
 * @throws {Error} On constraint violations or database errors during delete.
 */
export async function delete__shopping_mall_ai_seller_shoppingMallAiProductOptions_$shoppingMallAiProductOptionId(props: {
  seller: SellerPayload;
  shoppingMallAiProductOptionId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, shoppingMallAiProductOptionId } = props;
  // Fetch option and related product (including seller_id for authorization check)
  const option =
    await MyGlobal.prisma.shopping_mall_ai_product_options.findUnique({
      where: { id: shoppingMallAiProductOptionId },
