      actor_id: seller.id,
      actor_role: "seller",
      operation: "delete",
      detail: JSON.stringify({
        product_option_id: shoppingMallAiProductOptionId,
        product_id: option.shopping_mall_ai_product_id,
      }),
      occurred_at: toISOStringSafe(new Date()),
      context: null,
      deleted_at: null,
    },
  });
}

