/**
 * Create a new forum post in the shopping mall BBS.
 *
 * Allows an authenticated seller to create a post in the shopping mall forum
 * (BBS). The post is associated with the specified channel and section, and the
 * organizer is set as the customer entity mapped from the seller. All
 * date/datetime fields use strict ISO strings (string &
 * tags.Format<'date-time'>). No native Date type is used.
 *
 * @param props - Object containing the authenticated seller payload and request
 *   body.
 * @param props.seller - Authenticated seller information (SellerPayload).
 * @param props.body - Details for the new BBS post
 *   (IShoppingMallAiBbsPost.ICreate).
 * @returns The newly created BBS post record, strictly typed with all required
 *   audit/compliance fields.
 * @throws {Error} If the channel or section does not exist, or if authorization
 *   fails.
 */
export async function post__shopping_mall_ai_seller_bbsPosts(props: {
  seller: SellerPayload;
  body: IShoppingMallAiBbsPost.ICreate;
}): Promise<IShoppingMallAiBbsPost> {
  const { seller, body } = props;

  // Verify channel exists
  const channel = await MyGlobal.prisma.shopping_mall_ai_channels.findUnique({
    where: { id: body.shopping_mall_ai_channel_id },
  });
  if (!channel) {
    throw new Error("Channel not found");
  }

  // Verify section exists and is mapped to correct channel
  const section = await MyGlobal.prisma.shopping_mall_ai_sections.findUnique({
    where: { id: body.shopping_mall_ai_section_id },
  });
  if (!section) {
    throw new Error("Section not found");
  }
  if (
    section.shopping_mall_ai_channel_id !== body.shopping_mall_ai_channel_id
  ) {
    throw new Error("Section does not belong to specified channel");
  }

  // Map seller to customer (author) - assumes same id in both models; this may need adjustment per business rule.
  const customer = await MyGlobal.prisma.shopping_mall_ai_customers.findFirst({
    where: {
      id: seller.id,
      is_active: true,
    },
  });
  if (!customer) {
    throw new Error(
      "Seller is not authorized as forum post author (customer record required).",
    );
  }

  // Current timestamp strings
  const now = toISOStringSafe(new Date());

  // Create BBS post with immutably constructed payload
  const created = await MyGlobal.prisma.shopping_mall_ai_bbs_posts.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id,
      shopping_mall_ai_section_id: body.shopping_mall_ai_section_id,
      shopping_mall_ai_customer_id: customer.id,
      title: body.title,
      body: body.body,
      ip: "127.0.0.1", // In production, extract real IP from request context
      created_at: now,
      updated_at: now,
      // deleted_at omitted => null
    },
  });

  // Return produced value, mapping datetimes to correct representation and omitting native Date
  return {
    id: created.id,
    shopping_mall_ai_channel_id: created.shopping_mall_ai_channel_id,
    shopping_mall_ai_section_id: created.shopping_mall_ai_section_id,
    shopping_mall_ai_customer_id: created.shopping_mall_ai_customer_id,
    title: created.title,
    body: created.body,
    ip: created.ip,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

