/**
 * Fetch a paginated list of BBS posts available in the shopping mall forum for
 * administrators.
 *
 * Each post includes metadata such as title, content, author nickname (linked
 * to customer id), and timestamps for creation and updates. Only posts with
 * deleted_at as null are considered visible (not soft deleted).
 *
 * Admin authentication is required—only authenticated admins can access this
 * endpoint. Admins see all non-deleted posts regardless of author or channel.
 * No pagination/filtering query params exist yet (future extension). Returns up
 * to 100 posts sorted by created_at descending.
 *
 * @param props - Request parameter object
 * @param props.admin - The authenticated admin payload as injected by AdminAuth
 * @returns Paginated view (IPageIShoppingMallAiBbsPost.ISummary) with up to 100
 *   latest forum posts
 * @throws {Error} If customer(s) for a post could not be found (should not
 *   happen)
 */
export async function get__shopping_mall_ai_admin_bbsPosts(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiBbsPost.ISummary> {
  const posts = await MyGlobal.prisma.shopping_mall_ai_bbs_posts.findMany({
    where: { deleted_at: null },
    orderBy: { created_at: "desc" },
    take: 100,
    select: {
      id: true,
      title: true,
      created_at: true,
      updated_at: true,
      shopping_mall_ai_section_id: true,
      shopping_mall_ai_channel_id: true,
      shopping_mall_ai_customer_id: true,
    },
  });

  // Extract all distinct customer IDs
  const customerIds = Array.from(
    new Set(posts.map((post) => post.shopping_mall_ai_customer_id)),
  );
  const customers = await MyGlobal.prisma.shopping_mall_ai_customers.findMany({
    where: { id: { in: customerIds } },
    select: { id: true, nickname: true },
  });
  const nicknameMap = new Map<string, string>(
    customers.map((c) => [c.id, c.nickname]),
  );

  const summaries = posts.map((post) => {
    const author_nickname = nicknameMap.get(post.shopping_mall_ai_customer_id);
    if (author_nickname === undefined) {
      throw new Error(
        `Internal data integrity error: No customer found for post author with id ${post.shopping_mall_ai_customer_id}`,
      );
    }
    return {
      id: post.id,
      title: post.title,
      created_at: toISOStringSafe(post.created_at),
      updated_at: toISOStringSafe(post.updated_at),
      shopping_mall_ai_section_id: post.shopping_mall_ai_section_id,
      shopping_mall_ai_channel_id: post.shopping_mall_ai_channel_id,
      author_nickname,
    };
  });

  // Calculate pagination fields
  // Since input has no paging params, default to single page solution
  const returnValue: IPageIShoppingMallAiBbsPost.ISummary = {
    pagination: {
      current: 1 as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      limit: 100 as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      records: summaries.length as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: 1 as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
    },
    data: summaries,
  };
  return returnValue;
}

