 */
export async function patch__shopping_mall_ai_admin_reviews(props: {
  admin: AdminPayload;
  body: IShoppingMallAiReview.IRequest;
}): Promise<IPageIShoppingMallAiReview> {
  const { admin, body } = props;

  // Validate admin payload is present
  if (!admin || !admin.id || admin.type !== "admin") {
    throw new Error("Unauthorized: admin authentication required");
  }

  // Only allow filters on known fields
  const validFields = [
    "id",
    "shopping_mall_ai_product_id",
    "shopping_mall_ai_customer_id",
    "shopping_mall_ai_order_id",
    "rating",
    "body",
    "created_at",
    "updated_at",
    "deleted_at",
  ];

  const rawFilter =
    typeof body.filter === "object" && body.filter !== null ? body.filter : {};

  // Build a type-safe where clause, supporting text search and date range
  const where: Record<string, unknown> = {};
  for (const key of validFields) {
    if (
      Object.prototype.hasOwnProperty.call(rawFilter, key) &&
      rawFilter[key] != null
    ) {
      if (key === "body") {
        where.body = { contains: rawFilter.body, mode: "insensitive" as const };
      } else if (["created_at", "updated_at", "deleted_at"].includes(key)) {
        if (
          typeof rawFilter[key] === "object" &&
          rawFilter[key] !== null &&
          (rawFilter[key]?.gte !== undefined ||
            rawFilter[key]?.lte !== undefined)
        ) {
          where[key] = {
            ...(rawFilter[key]?.gte !== undefined && {
              gte: rawFilter[key].gte,
            }),
            ...(rawFilter[key]?.lte !== undefined && {
              lte: rawFilter[key].lte,
            }),
          };
        } else {
          where[key] = rawFilter[key];
        }
      } else {
        where[key] = rawFilter[key];
      }
    }
  }

  // Pagination (default: page 1, limit 20, max limit 100)
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit =
    body.limit && body.limit > 0 && body.limit <= 100 ? body.limit : 20;
  const skip = (page - 1) * limit;

  // Sorting
  const allowedSortFields = validFields;
  const sortField =
    body.sort && allowedSortFields.includes(body.sort)
      ? body.sort
      : "created_at";
  const order = body.order === "asc" ? ("asc" as const) : ("desc" as const);

  // Main query
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_reviews.findMany({
      where,
      orderBy: { [sortField]: order },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_reviews.count({ where }),
  ]);

  // Convert Date objects from Prisma to ISO string (never use native Date)
  const data = rows.map(
    (row): IShoppingMallAiReview => ({
      id: row.id,
      shopping_mall_ai_product_id: row.shopping_mall_ai_product_id,
      shopping_mall_ai_customer_id: row.shopping_mall_ai_customer_id,
