 * This endpoint allows a seller to filter, search, and paginate payment records
 * belonging to an order they participated in. Applies business RBAC so only
 * sellers of any product in the order can access its payments.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller requesting payments for their
 *   order
 * @param props.orderId - UUID of the order whose payments are being queried
 * @param props.body - Filter/search request for payment query, supports
 *   paging/filters
 * @returns Paginated payment results matching filter and RBAC compliance
 * @throws {Error} If order not found, or seller not associated to any order
 *   item
 */
export async function patch__shopping_mall_ai_seller_orders_$orderId_payments(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingPayment.IRequest;
}): Promise<IPageIShoppingPayment> {
  const { seller, orderId, body } = props;

  // 1. Fetch order, error if not found
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: { id: true },
  });
  if (!order) throw new Error("Order not found");

  // 2. Fetch order items for this order
  const orderItems =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where: { shopping_mall_ai_order_id: orderId },
      select: { shopping_mall_ai_product_id: true },
    });
  if (!orderItems.length) throw new Error("Order contains no items");

  // 3. Check seller owns any product in this order
  const orderProductIds = orderItems.map((i) => i.shopping_mall_ai_product_id);
  const sellerProducts =
    await MyGlobal.prisma.shopping_mall_ai_products.findMany({
      where: {
        id: { in: orderProductIds },
        shopping_mall_ai_seller_id: seller.id,
      },
      select: { id: true },
    });
  if (!sellerProducts.length)
    throw new Error(
      "Unauthorized: Seller does not own any products in this order",
    );

  // 4. Apply filters
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const where: Record<string, any> = {
    shopping_mall_ai_order_id: orderId,
    ...(body.method !== undefined &&
      body.method !== null && { method: body.method }),
    ...(body.status !== undefined &&
      body.status !== null && { status: body.status }),
    ...((body.initiated_from !== undefined && body.initiated_from !== null) ||
    (body.initiated_to !== undefined && body.initiated_to !== null)
      ? {
          initiated_at: {
            ...(body.initiated_from !== undefined &&
              body.initiated_from !== null && {
                gte: body.initiated_from,
              }),
            ...(body.initiated_to !== undefined &&
              body.initiated_to !== null && {
                lte: body.initiated_to,
              }),
          },
        }
      : {}),
  };

  // 5. Query payments and total count concurrently
  const [payments, count] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_payments.findMany({
      where,
      orderBy: { initiated_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_payments.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: count,
      pages: count === 0 ? 1 : Math.ceil(count / limit),
    },
    data: payments.map((p) => ({
      id: p.id,
      shopping_mall_ai_order_id: p.shopping_mall_ai_order_id,
      shopping_mall_ai_channel_id: p.shopping_mall_ai_channel_id,
      method: p.method,
      status: p.status,
      amount: p.amount,
      initiated_at: toISOStringSafe(p.initiated_at),
      resolved_at: p.resolved_at ? toISOStringSafe(p.resolved_at) : null,
    })),
  };
}

