 *
 * Allows the customer who created a product inquiry to update their question,
 * privacy flag, or mark an answer as helpful. Does not allow answer changes or
 * admin-level overrides.
 *
 * Business rules enforced:
 *
 * - Only the customer who owns the inquiry may update it
 * - Cannot update a deleted inquiry
 * - Only allowed fields (question, is_private, answer_marked_helpful) are
 *   updatable
 * - Cannot mark answer as helpful until a seller has responded
 * - All updates are fully audited (updated_at always set)
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer payload
 * @param props.inquiryId - Target inquiry's ID (UUID)
 * @param props.body - Fields to update (question, is_private,
 *   answer_marked_helpful)
 * @returns The fully updated inquiry object in DTO format
 * @throws {Error} When inquiry not found, deleted, not owned by customer, or
 *   illegal operation attempted
 */
export async function put__shopping_mall_ai_customer_inquiries_$inquiryId(props: {
  customer: CustomerPayload;
  inquiryId: string & tags.Format<"uuid">;
  body: IShoppingMallAiInquiry.IUpdate;
}): Promise<IShoppingMallAiInquiry> {
  const { customer, inquiryId, body } = props;

  // 1. Fetch the inquiry, verify existence and that it's not deleted
  const inquiry = await MyGlobal.prisma.shopping_mall_ai_inquiries.findUnique({
    where: { id: inquiryId },
  });
  if (!inquiry) throw new Error("Inquiry not found");
  if (inquiry.deleted_at) throw new Error("Inquiry is deleted");

  // 2. Authorization: Only the creator may update
  if (inquiry.shopping_mall_ai_customer_id !== customer.id) {
    throw new Error("You can only update your own inquiry");
  }

  // 3. Prepare update object: Only include defined fields per rules
  const updateInput: Partial<IShoppingMallAiInquiry.IUpdate> = {};
  if (body.question !== undefined) {
    updateInput.question = body.question;
  }
  if (body.is_private !== undefined) {
    updateInput.is_private = body.is_private;
  }
  if (body.answer_marked_helpful !== undefined) {
    if (!inquiry.answer) {
      throw new Error("Cannot mark helpful before there is an answer");
    }
    updateInput.answer_marked_helpful = body.answer_marked_helpful;
  }

  // 4. Always update the updated_at field
  const updated = await MyGlobal.prisma.shopping_mall_ai_inquiries.update({
    where: { id: inquiryId },
    data: {
      ...updateInput,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // 5. Return value, convert all timestamps and nullables as required
  return {
    id: updated.id,
    shopping_mall_ai_product_id: updated.shopping_mall_ai_product_id,
    shopping_mall_ai_customer_id: updated.shopping_mall_ai_customer_id,
    shopping_mall_ai_seller_id: updated.shopping_mall_ai_seller_id,
    question: updated.question,
    is_private: updated.is_private,
    answer: updated.answer ?? null,
    answer_marked_helpful: updated.answer_marked_helpful ?? null,
    created_at: toISOStringSafe(updated.created_at),
    answered_at: updated.answered_at
      ? toISOStringSafe(updated.answered_at)
      : null,
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

