import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Advanced search/filter/pagination on product reviews for sellers.
 *
 * Only returns reviews that belong to products owned by the authenticated
 * seller, and that are not soft-deleted. Supports powerful filtering, sorting,
 * and pagination. All date fields are converted to ISO strings, and all UUIDs
 * are returned as branded. Does not use the native Date type. Follows strict
 * business/data privacy rules.
 *
 * @param props - Contains the authenticated seller and search request
 * @param props.seller - The JWT-authenticated seller performing the search
 * @param props.body - Search filters, sort, and pagination config
 *   (IShoppingMallAiReview.IRequest)
 * @returns Paginated search result with review DTOs
 *   (IPageIShoppingMallAiReview)
 * @throws {Error} If search query is unauthorized, malformed, or page size is
 *   invalid
 */
export async function patch__shopping_mall_ai_seller_reviews(props: {
  seller: SellerPayload;
  body: IShoppingMallAiReview.IRequest;
}): Promise<IPageIShoppingMallAiReview> {
  const { seller, body } = props;

  // Step 1: Collect all product IDs owned by this seller
  const sellerProducts =
    await MyGlobal.prisma.shopping_mall_ai_products.findMany({
      where: { shopping_mall_ai_seller_id: seller.id },
      select: { id: true },
    });
  const productIds = sellerProducts.map((p) => p.id);
  if (!productIds.length) {
    // No products owned by this seller - return empty
    return {
      pagination: {
        current: body.page ?? 1,
        limit: body.limit ?? 20,
        records: 0,
        pages: 0,
      },
      data: [],
    };
  }

  // Step 2: Build safe filter for permitted fields only
  const filter = body.filter ?? {};
  // Compose the where clause
  const where = {
    shopping_mall_ai_product_id: { in: productIds },
    deleted_at: null,
    // Optional safe fields (only if provided)
    ...(filter.id !== undefined && filter.id !== null && { id: filter.id }),
    ...(filter.shopping_mall_ai_product_id !== undefined &&
      filter.shopping_mall_ai_product_id !== null && {
        shopping_mall_ai_product_id: filter.shopping_mall_ai_product_id,
      }),
    ...(filter.shopping_mall_ai_customer_id !== undefined &&
      filter.shopping_mall_ai_customer_id !== null && {
        shopping_mall_ai_customer_id: filter.shopping_mall_ai_customer_id,
      }),
    ...(filter.shopping_mall_ai_order_id !== undefined &&
      filter.shopping_mall_ai_order_id !== null && {
        shopping_mall_ai_order_id: filter.shopping_mall_ai_order_id,
      }),
    ...(filter.rating !== undefined &&
      filter.rating !== null && {
        rating: filter.rating,
      }),
    ...(filter.body !== undefined &&
      filter.body !== null && {
        body: { contains: filter.body, mode: "insensitive" as const },
      }),
    // Date range filtering for created_at and updated_at (allow filter.created_at_from/created_at_to)
    ...(filter.created_at_from !== undefined ||
    filter.created_at_to !== undefined
      ? {
          created_at: {
            ...(filter.created_at_from !== undefined &&
              filter.created_at_from !== null && {
                gte: filter.created_at_from,
              }),
            ...(filter.created_at_to !== undefined &&
              filter.created_at_to !== null && {
                lte: filter.created_at_to,
              }),
          },
        }
      : {}),
    ...(filter.updated_at_from !== undefined ||
    filter.updated_at_to !== undefined
      ? {
          updated_at: {
            ...(filter.updated_at_from !== undefined &&
              filter.updated_at_from !== null && {
                gte: filter.updated_at_from,
              }),
            ...(filter.updated_at_to !== undefined &&
              filter.updated_at_to !== null && {
                lte: filter.updated_at_to,
              }),
          },
        }
      : {}),
  };

  // Step 3: Pagination & ordering
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  const orderBy = body.sort
    ? { [body.sort]: body.order === "asc" ? "asc" : "desc" }
    : { created_at: "desc" };

  // Step 4: Query DB in parallel
  const [reviews, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_reviews.findMany({
      where,
      orderBy,
      skip,
      take: limit,
      select: {
        id: true,
        shopping_mall_ai_product_id: true,
        shopping_mall_ai_customer_id: true,
        shopping_mall_ai_order_id: true,
        rating: true,
        body: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_reviews.count({ where }),
  ]);

  // Step 5: Project to API DTO, ensure all types strictly match DTO (especially for dates)
  const data = reviews.map((r) => ({
    id: r.id,
    shopping_mall_ai_product_id: r.shopping_mall_ai_product_id,
    shopping_mall_ai_customer_id: r.shopping_mall_ai_customer_id,
    shopping_mall_ai_order_id: r.shopping_mall_ai_order_id,
    rating: r.rating,
    body: r.body,
    created_at: toISOStringSafe(r.created_at),
    updated_at: toISOStringSafe(r.updated_at),
    deleted_at: r.deleted_at ? toISOStringSafe(r.deleted_at) : null,
  }));

  const pages = total === 0 ? 0 : Math.ceil(total / limit);
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages,
    },
    data,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
