/**
 * Modifies an existing coupon's details by unique couponId.
 *
 * Allows a seller to update specific coupon fields (value, expiration, usage
 * caps, etc.) but only if they are the issuer of the coupon. Admin coupons
 * (platform coupons) cannot be updated by a seller. All changes are atomically
 * persisted to the database and strict type handling (no native Date) is
 * enforced. Timestamps are guaranteed as strings.
 *
 * @param props - Props object containing: seller: Authenticated SellerPayload
 *   (must match coupon's issuer field) couponId: Target coupon's UUID body:
 *   Fields to update on the coupon (IShoppingMallAiCoupon.IUpdate)
 * @returns The fully updated coupon object
 * @throws {Error} If the coupon does not exist or the seller does not have
 *   update rights
 */
export async function put__shopping_mall_ai_seller_coupons_$couponId(props: {
  seller: SellerPayload;
  couponId: string & tags.Format<"uuid">;
  body: IShoppingMallAiCoupon.IUpdate;
}): Promise<IShoppingMallAiCoupon> {
  const { seller, couponId, body } = props;
  const coupon = await MyGlobal.prisma.shopping_mall_ai_coupons.findUnique({
    where: { id: couponId },
  });
  if (!coupon) throw new Error("Coupon not found");
  if (coupon.shopping_mall_ai_seller_id !== seller.id) {
    throw new Error(
      "Unauthorized: Only the issuing seller can update this coupon",
    );
  }
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_mall_ai_coupons.update({
    where: { id: couponId },
    data: {
      value: body.value ?? undefined,
      min_order_value: body.min_order_value ?? undefined,
      max_usage: body.max_usage ?? undefined,
      max_usage_per_customer: body.max_usage_per_customer ?? undefined,
      valid_from: body.valid_from ?? undefined,
      valid_until: body.valid_until ?? undefined,
      stackable: body.stackable ?? undefined,
      status: body.status ?? undefined,
      updated_at: now,
    },
  });
  return {
    id: updated.id,
    shopping_mall_ai_seller_id: updated.shopping_mall_ai_seller_id ?? null,
    shopping_mall_ai_product_id: updated.shopping_mall_ai_product_id ?? null,
    shopping_mall_ai_channel_id: updated.shopping_mall_ai_channel_id ?? null,
    code: updated.code,
    type: updated.type,
    value: updated.value,
    min_order_value: updated.min_order_value ?? null,
    max_usage: updated.max_usage,
    max_usage_per_customer: updated.max_usage_per_customer,
    valid_from: toISOStringSafe(updated.valid_from),
    valid_until: toISOStringSafe(updated.valid_until),
    stackable: updated.stackable,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Create a new product review for a purchased product.
 *
 * Customers can submit a product review for a completed purchase—review is
 * stored in shopping_mall_ai_reviews. Caller must be authenticated, and order
 * linkage must validate customer ownership and order status. Body and rating
 * are required, and uniqueness is enforced for (customer, product, order).
 *
 * Returned object contains submitted data and system-populated fields. Use
 * case: post-purchase review panel or incentive flow. Triggers analytics,
 * optional moderation, and seller notification workflows. Errors: 400 for
 * invalid/missing fields, 409 for duplicate, 403/401 for unauthorized. Audited
 * for compliance requirements.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer (CustomerPayload)
 * @param props.body - All required fields for a new review
 *   (IShoppingMallAiReview.ICreate)
 * @returns Newly created review object (IShoppingMallAiReview), including
 *   generated fields
 * @throws {Error} When order does not exist or is not owned by customer (403)
 * @throws {Error} When the specified product does not exist in the order (400)
 * @throws {Error} When a review already exists for this customer/product/order
 *   (409)
 */
export async function post__shopping_mall_ai_customer_reviews(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiReview.ICreate;
}): Promise<IShoppingMallAiReview> {
  const { customer, body } = props;

  // 1. Validate order exists and is owned by this customer
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findFirst({
    where: {
      id: body.shopping_mall_ai_order_id,
      shopping_mall_ai_customer_id: customer.id,
    },
  });
  if (!order) {
    throw new Error(
      "Forbidden: Order does not exist or is not owned by customer",
    );
  }

  // 2. Ensure the product is part of the order's order items
  const orderItem =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findFirst({
      where: {
        shopping_mall_ai_order_id: body.shopping_mall_ai_order_id,
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
      },
    });
  if (!orderItem) {
    throw new Error("Bad Request: Product was not purchased in this order");
  }

  // 3. Ensure no existing review for this (customer, product, order) exists
  const duplicate = await MyGlobal.prisma.shopping_mall_ai_reviews.findFirst({
    where: {
      shopping_mall_ai_customer_id: customer.id,
      shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
      shopping_mall_ai_order_id: body.shopping_mall_ai_order_id,
    },
  });
  if (duplicate) {
    throw new Error(
      "Conflict: A review for this product and order already exists",
    );
  }

  // 4. Insert new review
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_reviews.create({
    data: {
      id: typia.assert<string & tags.Format<"uuid">>(v4()),
      shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
      shopping_mall_ai_customer_id: customer.id,
      shopping_mall_ai_order_id: body.shopping_mall_ai_order_id,
      rating: body.rating,
      body: body.body,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // 5. Return as IShoppingMallAiReview
  return {
    id: created.id,
    shopping_mall_ai_product_id: created.shopping_mall_ai_product_id,
    shopping_mall_ai_customer_id: created.shopping_mall_ai_customer_id,
    shopping_mall_ai_order_id: created.shopping_mall_ai_order_id,
    rating: created.rating,
    body: created.body,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
