/**
 * Register a new legal consent event for a seller agreeing to a policy
 * document.
 *
 * This endpoint registers a new legal consent event in the compliance system on
 * behalf of an authenticated seller. It ensures that only one consent record
 * may exist for any (user, policy, version) tuple, enforcing business and
 * compliance rules via a unique constraint. The record is immutable after
 * creation (unless withdrawn), and all audit fields are handled consistently
 * for compliance purposes.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller registering legal consent
 * @param props.body - Legal consent registration details (policy_code,
 *   policy_version, consent_method, consented_at, etc.)
 * @returns The created legal consent entity, reflecting user, policy, and
 *   timestamp
 * @throws {Error} If a consent record already exists for this (user, policy,
 *   version)
 */
export async function post__shopping_mall_ai_seller_legalConsents(props: {
  seller: SellerPayload;
  body: IShoppingMallAiLegalConsent.ICreate;
}): Promise<IShoppingMallAiLegalConsent> {
  const { seller, body } = props;
  try {
    const created =
      await MyGlobal.prisma.shopping_mall_ai_legal_consents.create({
        data: {
          id: v4() as string & tags.Format<"uuid">,
          user_id: seller.id,
          policy_code: body.policy_code,
          policy_version: body.policy_version,
          consented_at: toISOStringSafe(body.consented_at),
          consent_method: body.consent_method,
          consent_ip: body.consent_ip ?? null,
          // withdrawn_at, deleted_at intentionally are not set on creation
        },
      });
    return {
      id: created.id as string & tags.Format<"uuid">,
      user_id: created.user_id,
      policy_code: created.policy_code,
      policy_version: created.policy_version,
      consented_at: toISOStringSafe(created.consented_at),
      consent_method: created.consent_method,
      withdrawn_at: created.withdrawn_at
        ? toISOStringSafe(created.withdrawn_at)
        : null,
      consent_ip: created.consent_ip ?? null,
      deleted_at: created.deleted_at
        ? toISOStringSafe(created.deleted_at)
        : null,
    };
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      throw new Error(
        "A legal consent already exists for this user, policy, and version.",
      );
    }
    throw error;
  }
}

