 *   date range, page/limit)
 * @returns Paginated product snapshot results matching filter criteria.
 * @throws {Error} When authentication is missing or props.admin is not an
 *   admin; or database issues occur.
 */
export async function patch__shopping_mall_ai_admin_shoppingMallAiProductSnapshots(props: {
  admin: AdminPayload;
  body: IShoppingMallAiProductSnapshot.IRequest;
}): Promise<IPageIShoppingMallAiProductSnapshot> {
  const { admin, body } = props;

  if (!admin || admin.type !== "admin")
    throw new Error("Unauthorized: admin access required");

  // Pagination calculations and defaults
  const page = typeof body.page === "number" && body.page >= 0 ? body.page : 0;
  const limit =
    typeof body.limit === "number" && body.limit > 0 ? body.limit : 100;
  const skip = page * limit;

  // Build Prisma where clause inline per all filter rules
  const where = {
    ...(body.shopping_mall_ai_product_id !== undefined &&
      body.shopping_mall_ai_product_id !== null && {
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
      }),
    ...(body.action !== undefined &&
      body.action !== null && {
        action: body.action,
      }),
    ...((body.created_after !== undefined && body.created_after !== null) ||
    (body.created_before !== undefined && body.created_before !== null)
      ? {
          created_at: {
            ...(body.created_after !== undefined &&
              body.created_after !== null && {
                gte: body.created_after,
              }),
            ...(body.created_before !== undefined &&
              body.created_before !== null && {
                lte: body.created_before,
              }),
          },
        }
      : {}),
  };

  // Query count and page in parallel
  const [total, rows] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_product_snapshots.count({ where }),
    MyGlobal.prisma.shopping_mall_ai_product_snapshots.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
      select: {
        id: true,
        shopping_mall_ai_product_id: true,
        action: true,
        snapshot_json: true,
        created_at: true,
      },
    }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: limit > 0 ? Math.ceil(total / limit) : 1,
    },
    data: rows.map((row) => ({
      id: row.id,
      shopping_mall_ai_product_id: row.shopping_mall_ai_product_id,
      action: row.action,
      snapshot_json: row.snapshot_json,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

