 * This API erases a specified order item from a given order using a hard delete
 * (row removal) process, since the underlying schema does not include
 * deleted_at or other soft deletion fields. Only admin or the seller with
 * rights to the affected order may invoke this operation; customer initiation
 * is not supported. Typical use cases include order correction (admin
 * override), returns that remove order items entirely, or error resolution
 * within fulfillment operations.
 *
 * Proper referential integrity is enforced, and all delete operations are
 * logged for compliance. Response codes differentiate between successful
 * erasure and scenarios where deletion is forbidden due to immutable order
 * states (completed orders, regulatory lock). No content is returned on
 * successful hard delete; errors are returned for invalid requests.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller, must own the product in the order
 *   item
 * @param props.orderId - Parent order ID for the item to delete
 * @param props.orderItemId - ID of the order item to delete
 * @returns Void (if successful, item is deleted from DB)
 * @throws {Error} When the order item does not exist in this order
 * @throws {Error} When the order does not exist
 * @throws {Error} When the order cannot be modified (completed/locked)
 * @throws {Error} When the seller does not own the product in the order item
 */
export async function delete__shopping_mall_ai_seller_orders_$orderId_orderItems_$orderItemId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  orderItemId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, orderId, orderItemId } = props;

  // 1. Fetch the order item and required relations for ownership checks
  const orderItem =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findUnique({
      where: { id: orderItemId },
      select: {
        shopping_mall_ai_order_id: true,
        shopping_mall_ai_product_id: true,
      },
    });
  if (!orderItem || orderItem.shopping_mall_ai_order_id !== orderId) {
    throw new Error("Order item doesn't exist in this order");
  }

  // 2. Fetch the order to check status
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: { status: true },
  });
  if (!order) {
    throw new Error("Order does not exist");
  }
  if (order.status === "completed" || order.status === "locked") {
    throw new Error("Order cannot be modified in current state");
  }

  // 3. Fetch the product to check seller ownership
  const product = await MyGlobal.prisma.shopping_mall_ai_products.findUnique({
    where: { id: orderItem.shopping_mall_ai_product_id },
    select: { shopping_mall_ai_seller_id: true },
  });
  if (!product || product.shopping_mall_ai_seller_id !== seller.id) {
    throw new Error("Forbidden: Not authorized to delete this order item");
  }

  // 4. Hard delete
  await MyGlobal.prisma.shopping_mall_ai_order_items.delete({
    where: { id: orderItemId },
  });
  // No return content (void)
}

