/**
 * Advanced multi-dimensional coupon search for sellers.
 *
 * Enables sellers to search for their own coupons using filter, sort, and
 * pagination criteria. Enforces seller-level RBAC boundary: only the
 * authenticated seller's coupons are returned, regardless of filter input.
 * Filters include code, status, type, validity windows, and related FKs. Only
 * whitelisted sort fields are allowed; default is descending by creation date.
 * Returns paginated summaries, strictly type-safe, with all date fields as ISO
 * strings.
 *
 * @param props - Seller: SellerPayload (authenticated seller context) body:
 *   IShoppingMallAiCoupon.IRequest (filter/search input)
 * @returns IPageIShoppingMallAiCoupon.ISummary — Paginated, filtered list of
 *   matching coupon summaries.
 * @throws {Error} When sort_by/limit/page input is invalid, or if Prisma errors
 *   occur.
 */
export async function patch__shopping_mall_ai_seller_coupons(props: {
  seller: SellerPayload;
  body: IShoppingMallAiCoupon.IRequest;
}): Promise<IPageIShoppingMallAiCoupon.ISummary> {
  const { seller, body } = props;

  // Pagination defaults (enforce max)
  const page = body.page && body.page > 0 ? body.page : 1;
  let limit = body.limit && body.limit > 0 ? body.limit : 20;
  if (limit > 100) limit = 100;
  const skip = (page - 1) * limit;

  // Allow only specific sort fields
  const allowedSorts = [
    "code",
    "type",
    "value",
    "status",
    "valid_from",
    "valid_until",
    "created_at",
  ];
  const sortBy = allowedSorts.includes(body.sort_by || "")
    ? (body.sort_by as (typeof allowedSorts)[number])
    : "created_at";
  const sortOrder = body.sort_order === "asc" ? "asc" : "desc";

  // Build range filters for date fields
  let valid_fromFilter:
    | Record<string, string & tags.Format<"date-time">>
    | undefined = undefined;
  if (body.valid_from_from || body.valid_from_to) {
    valid_fromFilter = {
      ...(body.valid_from_from && { gte: body.valid_from_from }),
      ...(body.valid_from_to && { lt: body.valid_from_to }),
    };
  }
  let valid_untilFilter:
    | Record<string, string & tags.Format<"date-time">>
    | undefined = undefined;
  if (body.valid_until_from || body.valid_until_to) {
    valid_untilFilter = {
      ...(body.valid_until_from && { gte: body.valid_until_from }),
      ...(body.valid_until_to && { lt: body.valid_until_to }),
    };
  }

  // Generate query filter (where)
  const where = {
    shopping_mall_ai_seller_id: seller.id,
    ...(body.code && {
      code: { contains: body.code, mode: "insensitive" as const },
    }),
    ...(body.type && { type: body.type }),
    ...(body.status && { status: body.status }),
    ...(valid_fromFilter && { valid_from: valid_fromFilter }),
    ...(valid_untilFilter && { valid_until: valid_untilFilter }),
    ...(body.shopping_mall_ai_channel_id && {
      shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id,
    }),
    ...(body.shopping_mall_ai_product_id && {
      shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
    }),
  };

  // Query and count in parallel (never create intermediate variable for params)
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_coupons.findMany({
      where,
      orderBy: { [sortBy]: sortOrder },
      skip,
      take: limit,
      select: {
        id: true,
        code: true,
        type: true,
        value: true,
        status: true,
        valid_from: true,
        valid_until: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_coupons.count({ where }),
  ]);

  // Map to DTO, converting Date -> string & tags.Format<'date-time'>
  const data = rows.map((row) => ({
    id: row.id,
    code: row.code,
    type: row.type,
    value: row.value,
    status: row.status,
    valid_from: toISOStringSafe(row.valid_from),
    valid_until: toISOStringSafe(row.valid_until),
    created_at: toISOStringSafe(row.created_at),
  }));

  // Paginated response structure
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.max(1, Math.ceil(total / limit)),
    },
    data,
  };
}

