/**
 * Soft delete a BBS post by ID (shopping_mall_ai_bbs_posts).
 *
 * Soft delete a BBS forum post using its unique identifier. Post is not
 * permanently removed; instead, the deleted_at timestamp is set to the current
 * time, ensuring full compliance with audit and retention policies of the
 * shopping_mall_ai_bbs_posts schema. Only the original author may initiate
 * deletion (customer role).
 *
 * Deleted posts become invisible to regular users. If the post is already
 * deleted or the user lacks permission, error states are returned accordingly.
 * All delete operations are audited.
 *
 * @param props - Object with authenticated customer payload and bbsPostId
 * @param props.customer - Authenticated customer; must match the post author
 * @param props.bbsPostId - UUID for target BBS post, must exist
 * @returns Void
 * @throws {Error} If the post does not exist, is already deleted, or the
 *   customer is not the author
 */
export async function delete__shopping_mall_ai_customer_bbsPosts_$bbsPostId(props: {
  customer: CustomerPayload;
  bbsPostId: string & tags.Format<"uuid">;
}): Promise<void> {
