  const post =
    await MyGlobal.prisma.shopping_mall_ai_bbs_posts.findUniqueOrThrow({
      where: { id: bbsPostId },
    });

  if (post.shopping_mall_ai_customer_id !== customer.id) {
    throw new Error(
      "Unauthorized: Only the original author may delete this post",
    );
  }

  if (post.deleted_at !== null && post.deleted_at !== undefined) {
    throw new Error("Already deleted");
