/**
 * Register a new shipment event under a target order.
 *
 * Creates a shipment row for the order specified by orderId, only if the
 * authenticated seller is responsible for at least one product in the order.
 * Enforces that only sellers of the relevant products (RBAC) can register
 * shipment events. All IDs and dates use strict tagged formats; array, mapping,
 * and properties follow functional immutable principles. No native Date or 'as'
 * is used.
 *
 * @param props - Props for shipment creation
 * @param props.seller - Authenticated seller payload
 * @param props.orderId - UUID of existing order
 * @param props.body - DTO data required to create shipment (status,
 *   tracking_number, provider)
 * @returns The created shipment record
 * @throws {Error} If order does not exist, has no items, or seller is not
 *   responsible for any product in order
 */
export async function post__shopping_mall_ai_seller_orders_$orderId_shipments(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingMallAiShipment.ICreate;
}): Promise<IShoppingMallAiShipment> {
  const { seller, orderId, body } = props;

  // 1. Confirm order exists
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: { id: true },
  });
  if (!order) throw new Error("Order not found");

  // 2. Fetch order items and verify the seller owns at least one product in order
  const orderItems =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where: { shopping_mall_ai_order_id: orderId },
      select: { shopping_mall_ai_product_id: true },
    });
  if (orderItems.length === 0) throw new Error("No items in order");
  const productIds = orderItems.map((item) => item.shopping_mall_ai_product_id);

  // Verify seller ownership
  const ownsProduct = await MyGlobal.prisma.shopping_mall_ai_products.findFirst(
    {
      where: {
        id: { in: productIds },
        shopping_mall_ai_seller_id: seller.id,
      },
      select: { id: true },
    },
  );
  if (!ownsProduct)
    throw new Error(
      "Forbidden: seller cannot register shipment for this order",
    );

  // 3. Create shipment (fully typed, all dates ISO string, no Date, no 'as')
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_shipments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_ai_order_id: orderId,
      status: body.status,
      tracking_number: body.tracking_number ?? null,
      provider: body.provider ?? null,
      created_at: now,
      updated_at: now,
    },
    select: {
      id: true,
      shopping_mall_ai_order_id: true,
      status: true,
      tracking_number: true,
      provider: true,
      created_at: true,
      updated_at: true,
    },
  });

  return {
    id: created.id,
    shopping_mall_ai_order_id: created.shopping_mall_ai_order_id,
    status: created.status,
    tracking_number: created.tracking_number ?? null,
    provider: created.provider ?? null,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

