import { IShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiInquiry";
import { IPageIShoppingMallAiInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiInquiry";
