import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Advanced search, filter, and pagination for product inquiries by an
 * authenticated customer.
 *
 * Provides dashboard and analytic search for inquiries, fully RBAC-enforced to
 * the current customer. Supports filtering on product, seller, privacy,
 * answered status, and creation time. Paginated and sortable. Only inquiries
 * owned by the authenticated customer are returned, with proper privacy.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer (payload injected by
 *   CustomerAuth)
 * @param props.body - Search/query/filter/pagination params
 *   (IShoppingMallAiInquiry.IRequest)
 * @returns Paginated, filtered list of inquiries belonging to the customer
 * @throws {Error} If invalid filter key is provided or Prisma query fails
 */
export async function patch__shopping_mall_ai_customer_inquiries(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiInquiry.IRequest;
}): Promise<IPageIShoppingMallAiInquiry> {
  const { customer, body } = props;
  const page = typeof body.page === "number" && body.page >= 1 ? body.page : 1;
  const limit =
    typeof body.limit === "number" && body.limit > 0 && body.limit <= 100
      ? body.limit
      : 20;
  const skip = (page - 1) * limit;

  // Allowlist filter keys:
  const ALLOWED_FILTERS = [
    "shopping_mall_ai_product_id",
    "shopping_mall_ai_seller_id",
    "is_private",
    "answered",
    // extendable if more fields are added
  ] as const;

  // Construct Prisma where clause
  const where = {
    shopping_mall_ai_customer_id: customer.id,
    deleted_at: null,
    ...(body.filter && typeof body.filter === "object"
      ? Object.entries(body.filter).reduce(
          (acc, [key, value]) => {
            if (
              !ALLOWED_FILTERS.includes(key as (typeof ALLOWED_FILTERS)[number])
            ) {
              return acc; // Skip unknown keys
            }
            if (key === "shopping_mall_ai_product_id" && value) {
              acc.shopping_mall_ai_product_id = value;
            } else if (key === "shopping_mall_ai_seller_id" && value) {
              acc.shopping_mall_ai_seller_id = value;
            } else if (
              key === "is_private" &&
              value !== undefined &&
              value !== null
            ) {
              acc.is_private = value;
            } else if (
              key === "answered" &&
              value !== undefined &&
              value !== null
            ) {
              acc.answered_at = value ? { not: null } : null;
            }
            return acc;
          },
          {} as Record<string, unknown>,
        )
      : {}),
  };

  // Sorting logic
  let orderBy: Record<string, "asc" | "desc">;
  if (
    body.sort &&
    typeof body.sort === "string" &&
    [
      "created_at",
      "answered_at",
      "question",
      "is_private",
      // Add other sort fields as needed
    ].includes(body.sort)
  ) {
    orderBy = { [body.sort]: body.order === "asc" ? "asc" : "desc" };
  } else {
    orderBy = { created_at: "desc" };
  }

  // Query Prisma
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_inquiries.findMany({
      where,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_inquiries.count({ where }),
  ]);

  // Transform to API DTO with date formatting
  const data: IShoppingMallAiInquiry[] = rows.map((row) => ({
    id: row.id,
    shopping_mall_ai_product_id: row.shopping_mall_ai_product_id,
    shopping_mall_ai_customer_id: row.shopping_mall_ai_customer_id,
    shopping_mall_ai_seller_id: row.shopping_mall_ai_seller_id,
    question: row.question,
    is_private: row.is_private,
    answer: row.answer ?? null,
    answer_marked_helpful: row.answer_marked_helpful ?? null,
    created_at: toISOStringSafe(row.created_at),
    answered_at: row.answered_at ? toISOStringSafe(row.answered_at) : null,
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

