import { IShoppingMallAiReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiReview";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * 상품 리뷰(쇼핑몰)의 기본 목록을 조회합니다. (고객 본인 작성/미삭제 내역, 페이지네이션)
 *
 * 이 함수는 인증된 고객의 식별자(customer.id)를 통해 본인이 작성한 상품 리뷰만 조회합니다. - 소프트 삭제된
 * 리뷰(deleted_at != null)는 제외합니다. - 각 리뷰에는 평점, 본문, 생성/수정/삭제(소프트 삭제) 시각 정보가
 * 포함됩니다. - 기본적으로 1페이지 20건씩 내림차순(created_at 기준)으로 반환합니다.
 *
 * @param props - 요청 속성 객체
 * @param props.customer - 인증된 고객 정보 페이로드(CustomerPayload)
 * @returns IPageIShoppingMallAiReview (page, limit, 전체 개수, 페이지 수, 리뷰 배열)
 * @throws {Error} 고객이 미인증/활성화되지 않은 경우
 */
export async function get__shopping_mall_ai_customer_reviews(props: {
  customer: CustomerPayload;
}): Promise<IPageIShoppingMallAiReview> {
