 * @returns 필터링/정렬/페이징된 인벤토리 목록 (메타 포함)
 * @throws {Error} 판매자가 소유한 상품이 없을 경우 empty page 반환
 * @throws {Error} 입력 조건이 잘못되거나 시스템 오류 발생 시
 */
export async function patch__shopping_mall_ai_seller_shoppingMallAiInventories(props: {
  seller: SellerPayload;
  body: IShoppingMallAiInventory.IRequest;
}): Promise<IPageIShoppingMallAiInventory> {
  const { seller, body } = props;

  // 1. 인증된 판매자의 상품 id 목록 조회
  const ownedProducts =
    await MyGlobal.prisma.shopping_mall_ai_products.findMany({
      where: { shopping_mall_ai_seller_id: seller.id },
      select: { id: true },
    });
  const ownedProductIds = ownedProducts.map((p) => p.id);
  if (ownedProductIds.length === 0) {
