      pagination: {
        current: (body.page ?? 0) as number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{ format: "uint32" }>,
        limit: (body.limit ?? 100) as number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{ format: "uint32" }>,
        records: 0 as number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{ format: "uint32" }>,
        pages: 0 as number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{ format: "uint32" }>,
      },
      data: [],
    };
  }

  // 2. 인벤토리 where 조건 동적 구성
  const where = {
    shopping_mall_ai_product_id: { in: ownedProductIds },
    ...(body.shopping_mall_ai_product_id !== undefined &&
      body.shopping_mall_ai_product_id !== null && {
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
