    ...(body.shopping_mall_ai_product_option_id !== undefined &&
      body.shopping_mall_ai_product_option_id !== null && {
        shopping_mall_ai_product_option_id:
          body.shopping_mall_ai_product_option_id,
      }),
    ...(body.min_quantity !== undefined &&
    body.min_quantity !== null &&
    body.max_quantity !== undefined &&
    body.max_quantity !== null
      ? {
          quantity: {
            gte: body.min_quantity,
            lte: body.max_quantity,
          },
        }
      : body.min_quantity !== undefined && body.min_quantity !== null
        ? { quantity: { gte: body.min_quantity } }
        : body.max_quantity !== undefined && body.max_quantity !== null
          ? { quantity: { lte: body.max_quantity } }
          : {}),
    ...(body.has_reservations !== undefined &&
      body.has_reservations !== null && {
        reserved_quantity: body.has_reservations ? { gt: 0 } : 0,
      }),
    ...((body.restock_after !== undefined && body.restock_after !== null) ||
    (body.restock_before !== undefined && body.restock_before !== null)
      ? {
          restock_at: {
            ...(body.restock_after !== undefined &&
              body.restock_after !== null && { gte: body.restock_after }),
            ...(body.restock_before !== undefined &&
              body.restock_before !== null && { lte: body.restock_before }),
          },
        }
      : {}),
  };

  // 3. 정렬조건 (기본 updated_at desc)
  const orderBy = body.sort_by
    ? {
        [body.sort_by]:
          body.sort_order === "desc" ? "desc" : ("asc" as "asc" | "desc"),
      }
    : { updated_at: "desc" as "desc" };

  const page = (body.page ?? 0) as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;
  const limit = (body.limit ?? 100) as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;
  const skip = page * limit;

  // 4. 총 개수 + 목록 동시 조회
  const [records, data] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_inventories.count({ where }),
    MyGlobal.prisma.shopping_mall_ai_inventories.findMany({
      where,
      orderBy,
      skip,
      take: limit,
    }),
  ]);
  const pages = Math.ceil(records / limit) as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;

  // 5. 응답 변환 (타입 태그, 날짜 ISO 변환)
  return {
    pagination: {
      current: page,
      limit: limit,
      records: records as number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>,
      pages: pages,
    },
    data: data.map((inv) => ({
      id: inv.id,
      shopping_mall_ai_product_id: inv.shopping_mall_ai_product_id,
      shopping_mall_ai_product_option_id:
