 *
 * Update an inventory record by UUID, using data specified in the
 * IShoppingMallAiInventory.IUpdate request structure. The ID path parameter
 * targets the row, and the payload includes any mutable fields. All business
 * validations (quantity cannot be negative, reserved below available, etc.) are
 * performed per shopping_mall_ai_inventories schema requirements.
 *
 * This operation is audit-logged for compliance and returns the full, updated
 * inventory object. Only sellers/admin may update their own inventories;
 * permission checks apply.
 *
 * Returns object reflecting post-update inventory state.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user making the request
 * @param props.shoppingMallAiInventoryId - UUID of the inventory record to
 *   update
 * @param props.body - Requested inventory updates per allowed fields
 * @returns The updated inventory object, fully hydrated
 * @throws {Error} When the inventory record does not exist
 * @throws {Error} When business validations fail (negative/over-reserved
 *   quantities)
 */
export async function put__shopping_mall_ai_admin_shoppingMallAiInventories_$shoppingMallAiInventoryId(props: {
  admin: AdminPayload;
  shoppingMallAiInventoryId: string & tags.Format<"uuid">;
  body: IShoppingMallAiInventory.IUpdate;
}): Promise<IShoppingMallAiInventory> {
  const { admin, shoppingMallAiInventoryId, body } = props;
  // Fetch the existing inventory record for validation
  const inventory =
    await MyGlobal.prisma.shopping_mall_ai_inventories.findUnique({
      where: { id: shoppingMallAiInventoryId },
    });
  if (!inventory) throw new Error("Inventory record not found");

  // Next values for business validation
  const nextQuantity = body.quantity ?? inventory.quantity;
  const nextReserved = body.reserved_quantity ?? inventory.reserved_quantity;

  if (nextQuantity < 0) throw new Error("Quantity cannot be negative");
  if (nextReserved < 0) throw new Error("Reserved quantity cannot be negative");
  if (nextReserved > nextQuantity)
    throw new Error("Reserved cannot exceed quantity");

  // Prepare update - only include fields present in body
  const updated = await MyGlobal.prisma.shopping_mall_ai_inventories.update({
    where: { id: shoppingMallAiInventoryId },
    data: {
      shopping_mall_ai_product_id:
        body.shopping_mall_ai_product_id ?? undefined,
      shopping_mall_ai_product_option_id:
        body.shopping_mall_ai_product_option_id ?? undefined,
      quantity: body.quantity ?? undefined,
      reserved_quantity: body.reserved_quantity ?? undefined,
      restock_at:
        body.restock_at === null ? null : (body.restock_at ?? undefined),
      updated_at: toISOStringSafe(new Date()),
    },
  });

  return {
    id: updated.id,
    shopping_mall_ai_product_id: updated.shopping_mall_ai_product_id,
    shopping_mall_ai_product_option_id:
      updated.shopping_mall_ai_product_option_id,
    quantity: updated.quantity,
    reserved_quantity: updated.reserved_quantity,
    restock_at: updated.restock_at ? toISOStringSafe(updated.restock_at) : null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

