  orderId: string & tags.Format<"uuid">;
  body: IShoppingMallAiShipment.IRequest;
}): Promise<IPageIShoppingMallAiShipment> {
  const { customer, orderId, body } = props;

  // Fetch the order and check ownership
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUniqueOrThrow(
    {
      where: { id: orderId },
      select: { shopping_mall_ai_customer_id: true },
    },
  );
  if (order.shopping_mall_ai_customer_id !== customer.id) {
    throw new Error("Forbidden: Only the order owner can view shipments.");
  }

  // Extract and normalize filters with defaults
  const {
    page = 1,
    limit = 20,
    status,
    provider,
    created_from,
    created_to,
    sort_by = "created_at",
    sort_order = "desc",
  } = body;

  // Build exact where condition inline, following best practices
  const whereCond = {
    shopping_mall_ai_order_id: orderId,
    ...(status ? { status } : {}),
    ...(provider ? { provider } : {}),
    // Date range filtering if any
    ...(created_from || created_to
      ? {
          created_at: {
            ...(created_from ? { gte: created_from } : {}),
            ...(created_to ? { lt: created_to } : {}),
          },
        }
      : {}),
  };

  // Pagination math
  const skip = (page - 1) * limit;

  // Fetch shipments and total count in parallel for speed
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_shipments.findMany({
      where: whereCond,
      orderBy: { [sort_by]: sort_order },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_shipments.count({ where: whereCond }),
  ]);

  // Map rows to API DTO, formatting all date fields via toISOStringSafe
  const data = rows.map(
    (row): IShoppingMallAiShipment => ({
      id: row.id,
      shopping_mall_ai_order_id: row.shopping_mall_ai_order_id,
      status: row.status,
      tracking_number: row.tracking_number ?? null,
      provider: row.provider ?? null,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    }),
  );

  // Compose and return paginated DTO structure
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit) || 1,
    },
    data,
  };
}

