/**
 * 쇼핑몰 BBS 게시글 고급 검색 및 필터 API.
 *
 * 상세 조건(채널, 섹션, 작성자, 타이틀/본문 텍스트 검색, 생성일 범위 등)으로 게시글 컬렉션을 조회합니다. 반환 결과는 논리
 * 삭제(deleted_at=null)를 제외하며, 활성 섹션 필터(active_only) 또한 지원합니다. 결과는 페이지네이션 구조로
 * 반환합니다.
 *
 * @param props - 요청 속성
 * @param props.customer - 인증된 고객 페이로드
 * @param props.body - BBS 게시글 검색 조건 및 페이징/필터 파라미터
 * @returns 조건에 맞는 게시글 목록 (페이지네이션 형태)
 * @throws {Error} 잘못된 쿼리, DB 오류, 권한 문제 등
 */
export async function patch__shopping_mall_ai_customer_bbsPosts(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiBbsPost.IRequest;
}): Promise<IPageIShoppingMallAiBbsPost.ISummary> {
  const { body } = props;
  // 기본값 지정 (page: 1, limit: 20)
  const page = typeof body.page === "number" && body.page > 0 ? body.page : 1;
  const limit =
    typeof body.limit === "number" && body.limit > 0 ? body.limit : 20;

  // where 조건 생성
  const where = {
    deleted_at: null,
    ...(body.shopping_mall_ai_channel_id !== undefined &&
      body.shopping_mall_ai_channel_id !== null && {
        shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id,
      }),
    ...(body.shopping_mall_ai_section_id !== undefined &&
      body.shopping_mall_ai_section_id !== null && {
        shopping_mall_ai_section_id: body.shopping_mall_ai_section_id,
      }),
    ...(body.shopping_mall_ai_customer_id !== undefined &&
      body.shopping_mall_ai_customer_id !== null && {
        shopping_mall_ai_customer_id: body.shopping_mall_ai_customer_id,
      }),
    ...(body.title !== undefined &&
      body.title !== null &&
      body.title.length > 0 && {
        title: { contains: body.title, mode: "insensitive" as const },
      }),
    ...((body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && { gte: body.created_from }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && { lte: body.created_to }),
          },
        }
      : {}),
  };

  // 섹션 활성 필터(active_only)
  let sectionActiveWhere: undefined | { id: string; active: boolean } =
    undefined;
  if (body.active_only === true && body.shopping_mall_ai_section_id) {
    sectionActiveWhere = {
      id: body.shopping_mall_ai_section_id,
      active: true,
    };
  }

  // 데이터/total 동시 조회
  const [posts, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_bbs_posts.findMany({
      where: where,
      ...(sectionActiveWhere && { section: sectionActiveWhere }),
      skip: (page - 1) * limit,
      take: limit,
      orderBy: { created_at: "desc" },
      include: { author: true },
    }),
    MyGlobal.prisma.shopping_mall_ai_bbs_posts.count({
      where: where,
      ...(sectionActiveWhere && { section: sectionActiveWhere }),
    }),
  ]);

  // 결과 매핑 (날짜 변환)
  const summaries = posts.map((post) => ({
    id: post.id,
    title: post.title,
    created_at: toISOStringSafe(post.created_at),
    updated_at: toISOStringSafe(post.updated_at),
    shopping_mall_ai_section_id: post.shopping_mall_ai_section_id,
    shopping_mall_ai_channel_id: post.shopping_mall_ai_channel_id,
    author_nickname: post.author.nickname,
  }));

  // 페이지네이션 number 타입을 DTO에서 요구하는 타입(branding)으로 변환
  return {
    pagination: {
      current: typia.assert<
        typeof page &
          import("typia").tags.Type<"int32"> &
          import("typia").tags.JsonSchemaPlugin<{ format: "uint32" }>
      >(page),
      limit: typia.assert<
        typeof limit &
          import("typia").tags.Type<"int32"> &
          import("typia").tags.JsonSchemaPlugin<{ format: "uint32" }>
      >(limit),
      records: typia.assert<
        typeof total &
          import("typia").tags.Type<"int32"> &
          import("typia").tags.JsonSchemaPlugin<{ format: "uint32" }>
      >(total),
      pages: typia.assert<
        typeof total &
          import("typia").tags.Type<"int32"> &
          import("typia").tags.JsonSchemaPlugin<{ format: "uint32" }>
      >(Math.ceil(total / limit)),
    },
    data: summaries,
  };
}

