/**
 * Creates a new cart session linking a session token to a cart.
 *
 * This endpoint allows an authenticated admin to create a new cart session
 * (shopping_mall_ai_cart_sessions), establishing a mapping between a session
 * token and a specific shopping cart. This enables device/guest/member cart
 * recovery, session synchronization, and analytics.
 *
 * - All fields are required.
 * - The 'id' field (primary key) is generated server-side as a UUID.
 * - 'session_token' uniqueness is enforced; if violated, an error is thrown.
 * - Only admins (validated by the AdminPayload) may use this endpoint.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin user performing the operation (must
 *   have AdminPayload)
 * @param props.body - The cart session creation payload
 *   (shopping_mall_ai_cart_id, session_token, created_at, last_active_at)
 * @returns The newly created cart session
 * @throws {Error} If the session_token is already in use (unique constraint
 *   violation)
 */
export async function post__shopping_mall_ai_admin_cartSessions(props: {
  admin: AdminPayload;
  body: IShoppingMallAiCartSession.ICreate;
}): Promise<IShoppingMallAiCartSession> {
  const { admin, body } = props;
  try {
    const created = await MyGlobal.prisma.shopping_mall_ai_cart_sessions.create(
      {
        data: {
          id: v4() as string & tags.Format<"uuid">,
          shopping_mall_ai_cart_id: body.shopping_mall_ai_cart_id,
          session_token: body.session_token,
          created_at: body.created_at,
          last_active_at: body.last_active_at,
        },
      },
    );
    return {
      id: created.id,
      shopping_mall_ai_cart_id: created.shopping_mall_ai_cart_id,
      session_token: created.session_token,
      created_at: toISOStringSafe(created.created_at),
      last_active_at: toISOStringSafe(created.last_active_at),
    };
  } catch (err) {
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2002" &&
      Array.isArray(err.meta?.target) &&
      err.meta?.target.includes("session_token")
    ) {
      throw new Error("Session token must be unique");
    }
    throw err;
  }
}

