 *
 * Fetches a paginated list of all payment events recorded for a specific order,
 * referencing the shopping_mall_ai_payments table. Each entry details method
 * (e.g., card, deposit), status (pending, successful, failed, refunded),
 * amount, and timestamps for audit. Admin-only operation; strict RBAC
 * enforcement and audit logging are handled via authentication mechanisms
 * (AdminPayload required).
 *
 * Enables audit trails for financial history, multi-method payment support,
 * refunds, and compliance review. The data structure is optimized for
 * dashboard, BI export, and after-sales workflow support, and complies with
 * platform-wide financial reporting requirements.
 *
 * @param props - Operation props
 * @param props.admin - Authenticated admin payload
 * @param props.orderId - The order ID to retrieve payments for
 * @returns Paginated list of payments for the order
 * @throws {Error} When the referenced order does not exist
 */
export async function get__shopping_mall_ai_admin_orders_$orderId_payments(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
}): Promise<IPageIShoppingPayment> {
  const { orderId } = props;
  // Ensure order existence for security/audit (avoid leaking payments of deleted/non-existent orders)
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
  });
  if (!order) throw new Error("Order not found");

  // Pagination logic (hardcoded: page 1, limit 100 for admin screens - can parameterize as needed)
  const page = 1;
  const limit = 100;

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_payments.findMany({
      where: { shopping_mall_ai_order_id: orderId },
      orderBy: { initiated_at: "asc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_payments.count({
      where: { shopping_mall_ai_order_id: orderId },
    }),
  ]);

  const payments = rows.map((row) => ({
    id: row.id,
    shopping_mall_ai_order_id: row.shopping_mall_ai_order_id,
    shopping_mall_ai_channel_id: row.shopping_mall_ai_channel_id,
    method: row.method,
    status: row.status,
    amount: row.amount,
    initiated_at: toISOStringSafe(row.initiated_at),
    resolved_at: row.resolved_at ? toISOStringSafe(row.resolved_at) : null,
  }));

  const pagination = {
    current: page,
    limit,
    records: total,
    pages: Math.ceil(total / limit),
  };

  return { pagination, data: payments };
}

