import { IPageIShoppingPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingPayment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Search, filter, and paginate payments for a given order
 * (shopping_mall_ai_payments).
 *
 * This endpoint allows complex, paginated, and sorted searches of payments
 * linked to a specified order. Supports filters on payment method, status, and
 * date, and paginates response for integration with BI tools or dashboards.
 *
 * Role-based access control: Only admins can use this endpoint (guaranteed by
 * decorator). No owner/seller check required. Fails only on missing/invalid
 * params or DB errors.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin payload (RBAC enforced by decorator)
 * @param props.orderId - UUID of the order whose payments are being queried
 * @param props.body - Filter/search criteria and pagination settings
 * @returns Paginated payment records (IPageIShoppingPayment) matching the
 *   filter
 * @throws {Error} If database errors occur, or parameters are invalid
 */
export async function patch__shopping_mall_ai_admin_orders_$orderId_payments(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingPayment.IRequest;
}): Promise<IPageIShoppingPayment> {
  const { orderId, body } = props;

  // Pagination defaults (never use null/undefined):
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // Strictly build Prisma where clause inline, using only fields present in schema/API
  const where = {
    shopping_mall_ai_order_id: orderId,
    ...(body.method !== undefined &&
      body.method !== null && {
        method: body.method,
      }),
    ...(body.status !== undefined &&
      body.status !== null && {
        status: body.status,
      }),
    ...((body.initiated_from !== undefined && body.initiated_from !== null) ||
    (body.initiated_to !== undefined && body.initiated_to !== null)
      ? {
          initiated_at: {
            ...(body.initiated_from !== undefined &&
              body.initiated_from !== null && {
                gte: body.initiated_from,
              }),
            ...(body.initiated_to !== undefined &&
              body.initiated_to !== null && {
                lte: body.initiated_to,
              }),
          },
        }
      : {}),
  };

  // Perform paginated query and total
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_payments.findMany({
      where,
      orderBy: { initiated_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_payments.count({ where }),
  ]);

  // Map result into IShoppingPayment response with date fields strictly converted
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((p) => ({
      id: p.id,
      shopping_mall_ai_order_id: p.shopping_mall_ai_order_id,
      shopping_mall_ai_channel_id: p.shopping_mall_ai_channel_id,
      method: p.method,
      status: p.status,
      amount: p.amount,
      initiated_at: toISOStringSafe(p.initiated_at),
      resolved_at: p.resolved_at ? toISOStringSafe(p.resolved_at) : null,
    })),
  };
}

