import { IShoppingMallAiBbsPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBbsPost";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Fetch a paginated list of BBS posts available in the shopping mall forum for
 * authenticated sellers.
 *
 * Only posts with deleted_at as null are considered visible. Each post includes
 * id, title, author nickname, creation/update timestamps, section, and channel
 * ids. Paginated response includes summary info for listings only (body
 * omitted).
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller making the request
 * @returns Paginated result set (IPageIShoppingMallAiBbsPost.ISummary)
 *   containing non-deleted posts and pagination metadata.
 * @throws {Error} When the seller authentication is invalid or the database
 *   operation fails
 */
export async function get__shopping_mall_ai_seller_bbsPosts(props: {
  seller: SellerPayload;
}): Promise<IPageIShoppingMallAiBbsPost.ISummary> {
  const { seller } = props;
  // Default pagination (could be extended as needed)
  const page = 1;
  const limit = 20;

  // Query visible (non-deleted) posts, order by newest
  const [posts, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_bbs_posts.findMany({
      where: {
        deleted_at: null,
      },
      orderBy: {
        created_at: "desc",
      },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_bbs_posts.count({
      where: {
        deleted_at: null,
      },
    }),
  ]);

  // Get all author/customer IDs
  const customerIds = Array.from(
    new Set(posts.map((p) => p.shopping_mall_ai_customer_id)),
  );
  const customers = await MyGlobal.prisma.shopping_mall_ai_customers.findMany({
    where: {
      id: {
        in: customerIds,
      },
    },
    select: {
      id: true,
      nickname: true,
    },
  });

  // Map customer id to nickname
  const nicknameMap = Object.fromEntries(
    customers.map((c) => [c.id, c.nickname]),
  );

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: posts.map((post) => ({
      id: post.id,
      title: post.title,
      created_at: toISOStringSafe(post.created_at),
      updated_at: toISOStringSafe(post.updated_at),
      shopping_mall_ai_section_id: post.shopping_mall_ai_section_id,
      shopping_mall_ai_channel_id: post.shopping_mall_ai_channel_id,
      author_nickname: nicknameMap[post.shopping_mall_ai_customer_id] ?? "",
    })),
  };
}

