/**
 * Modifies atomic fields of a payment record for an order, supporting business
 * and operational needs such as correcting status, updating payment method
 * information, recording refunds, or resolving payments after initial failures.
 * Only allowed roles (admin or responsible seller) can call this
 * endpoint—customers cannot edit payment records. Payload
 * (IShoppingPayment.IUpdate) mirrors payment record atomic fields, with
 * referential checks to prevent cross-order or cross-channel errors. On update,
 * audit logs record before/after state for compliance. Successful response
 * returns the full updated payment record; errors result in explicit messages
 * for validation or permission failure.
 *
 * @param props - Properties for payment update, including seller
 *   authentication, orderId, paymentId, and update body fields
 * @param props.seller - Authenticated seller
 * @param props.orderId - ID of the order being updated
 * @param props.paymentId - ID of the payment record to be updated
 * @param props.body - Fields to update (atomic, may include method, status,
 *   amount, initiated_at, resolved_at)
 * @returns The full updated payment record, with all dates formatted as ISO8601
 *   strings
 * @throws {Error} When payment not found, not associated to the order, or
 *   seller unauthorized for update
 */
export async function put__shopping_mall_ai_seller_orders_$orderId_payments_$paymentId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  paymentId: string & tags.Format<"uuid">;
  body: IShoppingPayment.IUpdate;
}): Promise<IShoppingPayment> {
  const { seller, orderId, paymentId, body } = props;

  const payment = await MyGlobal.prisma.shopping_mall_ai_payments.findUnique({
    where: { id: paymentId },
  });
  if (!payment) throw new Error("Payment not found");
  if (payment.shopping_mall_ai_order_id !== orderId)
    throw new Error("Payment does not belong to provided order");
  const orderItems =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where: { shopping_mall_ai_order_id: orderId },
      select: { shopping_mall_ai_product_id: true },
    });
  const productIds = orderItems.map((oi) => oi.shopping_mall_ai_product_id);
  const responsibleProducts =
    productIds.length === 0
      ? []
      : await MyGlobal.prisma.shopping_mall_ai_products.findMany({
          where: {
            id: { in: productIds },
            shopping_mall_ai_seller_id: seller.id,
          },
          select: { id: true },
        });
  if (responsibleProducts.length === 0)
    throw new Error("Unauthorized: you do not own any product in this order");
  const updated = await MyGlobal.prisma.shopping_mall_ai_payments.update({
    where: { id: paymentId },
    data: {
      method: body.method ?? undefined,
      status: body.status ?? undefined,
      amount: body.amount ?? undefined,
      initiated_at:
        body.initiated_at !== undefined && body.initiated_at !== null
          ? toISOStringSafe(body.initiated_at)
          : undefined,
      resolved_at:
        body.resolved_at !== undefined
          ? body.resolved_at === null
            ? null
            : toISOStringSafe(body.resolved_at)
          : undefined,
    },
  });
  return {
    id: updated.id,
    shopping_mall_ai_order_id: updated.shopping_mall_ai_order_id,
    shopping_mall_ai_channel_id: updated.shopping_mall_ai_channel_id,
    method: updated.method,
    status: updated.status,
    amount: updated.amount,
    initiated_at: toISOStringSafe(updated.initiated_at),
    resolved_at:
      updated.resolved_at !== null && updated.resolved_at !== undefined
        ? toISOStringSafe(updated.resolved_at)
        : null,
  };
}

