/**
 * Update file metadata by fileId (shopping_mall_ai_files).
 *
 * Updates metadata fields for a file asset given its unique fileId. Only
 * editable fields are allowed:
 *
 * - Original_name (string | null)
 * - Actor_type (string | null)
 * - Actor_id (string & tags.Format<'uuid'> | null)
 * - Deleted_at (string & tags.Format<'date-time'> | null)
 *
 * Attempting to update any other fields will result in a validation error. All
 * changes are logged in the audit trail for full traceability.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the operation
 * @param props.fileId - UUID of the file metadata record to update
 * @param props.body - Partial update for file metadata (editable fields only)
 * @returns Updated file metadata after modifications are applied.
 * @throws {Error} If file not found, if forbidden fields are present in body,
 *   or on database failure
 */
export async function put__shopping_mall_ai_admin_files_$fileId(props: {
  admin: AdminPayload;
  fileId: string & tags.Format<"uuid">;
  body: IShoppingMallAiFile.IUpdate;
}): Promise<IShoppingMallAiFile> {
  const { admin, fileId, body } = props;

  // Step 1: Check for forbidden/immutable fields in body
  const allowed = new Set([
    "original_name",
    "actor_type",
    "actor_id",
    "deleted_at",
  ]);
  for (const key of Object.keys(body)) {
    if (!allowed.has(key)) {
      throw new Error(`Field '${key}' is immutable and cannot be updated.`);
    }
  }

  // Step 2: Fetch file record prior to update for audit
  const record = await MyGlobal.prisma.shopping_mall_ai_files.findUnique({
    where: { id: fileId },
  });
  if (!record) throw new Error("File not found");

  // Step 3: Prepare update fields (only allow updates to allowed fields)
  const updateData = {
    ...(body.original_name !== undefined
      ? { original_name: body.original_name }
      : {}),
    ...(body.actor_type !== undefined ? { actor_type: body.actor_type } : {}),
    ...(body.actor_id !== undefined ? { actor_id: body.actor_id } : {}),
    ...(body.deleted_at !== undefined
      ? {
          deleted_at:
            body.deleted_at !== null ? toISOStringSafe(body.deleted_at) : null,
        }
      : {}),
  };

  const updated = await MyGlobal.prisma.shopping_mall_ai_files.update({
    where: { id: fileId },
    data: updateData,
  });

  // Step 4: Write audit log (before/after, all datetimes normalized)
  await MyGlobal.prisma.shopping_mall_ai_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      entity_type: "file",
      entity_id: updated.id,
      actor_id: admin.id,
      actor_role: "admin",
      operation: "update",
      detail: JSON.stringify({
        before: {
          ...record,
          created_at: toISOStringSafe(record.created_at),
          deleted_at: record.deleted_at
            ? toISOStringSafe(record.deleted_at)
            : null,
        },
        after: {
          ...updated,
          created_at: toISOStringSafe(updated.created_at),
          deleted_at: updated.deleted_at
            ? toISOStringSafe(updated.deleted_at)
            : null,
        },
      }),
      occurred_at: toISOStringSafe(new Date()),
      context: null,
      deleted_at: null,
    },
  });

  // Step 5: Return normalized IShoppingMallAiFile
  return {
    id: updated.id,
    original_name: updated.original_name,
    uri: updated.uri,
    extension: updated.extension,
    mime_type: updated.mime_type,
    size: updated.size,
    hash: updated.hash,
    actor_type: updated.actor_type ?? null,
    actor_id: updated.actor_id ?? null,
    created_at: toISOStringSafe(updated.created_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

