 *
 * Allows authenticated customers to search and paginate their own product
 * reviews with various filters (by product, order, rating, body content, or
 * created_at date range). Results are paged, sorted, and do not include
 * soft-deleted entries. Reviews from other customers are never returned.
 *
 * @param props - Request properties
 * @param props.customer - CustomerPayload (authenticated customer; only their
 *   own reviews are returned)
 * @param props.body - IShoppingMallAiReview.IRequest containing pagination,
 *   sort, and filter fields
 * @returns Paginated page of IShoppingMallAiReview with all date and uuid
 *   fields properly formatted
 * @throws {Error} If page/limit out of bounds or filter attempts fields that do
 *   not exist
 */
export async function patch__shopping_mall_ai_customer_reviews(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiReview.IRequest;
}): Promise<IPageIShoppingMallAiReview> {
  const { customer, body } = props;
  // Pagination
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit =
    body.limit && body.limit > 0 && body.limit <= 100 ? body.limit : 20;
  const allowedSorts = ["created_at", "updated_at", "rating"] as const;
  const sortField =
    body.sort && allowedSorts.includes(body.sort as any)
      ? body.sort
      : "created_at";
  const sortOrder = body.order === "asc" ? "asc" : "desc";

  // Build filtering criteria (only allow schema fields)
  const filter = body.filter ?? {};
  const where: Record<string, unknown> = {
    shopping_mall_ai_customer_id: customer.id,
    deleted_at: null,
  };
  if (typeof filter === "object" && filter !== null) {
    if (typeof filter.shopping_mall_ai_product_id === "string")
      where.shopping_mall_ai_product_id = filter.shopping_mall_ai_product_id;
    if (typeof filter.shopping_mall_ai_order_id === "string")
      where.shopping_mall_ai_order_id = filter.shopping_mall_ai_order_id;
    if (typeof filter.rating === "number") where.rating = filter.rating;
    if (typeof filter.body === "string" && filter.body.length > 0)
      where.body = { contains: filter.body, mode: "insensitive" as const };
    // Date range: created_at_from, created_at_to
    const createdAt: Record<string, string> = {};
    if (typeof filter.created_at_from === "string")
      createdAt.gte = filter.created_at_from;
    if (typeof filter.created_at_to === "string")
      createdAt.lte = filter.created_at_to;
    if (Object.keys(createdAt).length > 0) where.created_at = createdAt;
  }

  // Retrieve reviews and total count concurrently
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_reviews.findMany({
      where,
      orderBy: { [sortField]: sortOrder },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_reviews.count({ where }),
  ]);

  // Remap results, handling date/datetime fields and nulls
  const data = rows.map((row) => ({
    id: row.id,
    shopping_mall_ai_product_id: row.shopping_mall_ai_product_id,
    shopping_mall_ai_customer_id: row.shopping_mall_ai_customer_id,
    shopping_mall_ai_order_id: row.shopping_mall_ai_order_id,
    rating: row.rating,
    body: row.body,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  const pages = total > 0 ? Math.ceil(total / limit) : 0;

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages,
    },
    data,
  };
}

