import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCoupon";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Registers a new coupon into the system using the shopping_mall_ai_coupons
 * table.
 *
 * This endpoint allows authorized administrators (admin role) to create a new
 * coupon with all scope and business fields (issuer, code, type, value,
 * validity, stacking, usage caps), enforcing unique code and valid date range.
 * All business rules and RBAC are enforced.
 *
 * @param props - Request parameter object
 * @param props.admin - The authenticated admin performing the operation (RBAC
 *   enforced)
 * @param props.body - Coupon creation fields (code, type, value, etc.) per
 *   schema
 * @returns The created coupon entity as persisted in the system
 * @throws {Error} If code already exists, or validity range is invalid
 */
export async function post__shopping_mall_ai_admin_coupons(props: {
  admin: AdminPayload;
  body: IShoppingMallAiCoupon.ICreate;
}): Promise<IShoppingMallAiCoupon> {
  const { admin, body } = props;

  // RBAC via decorator+payload; additional business validation follows

  // Enforce business rule: valid_from must be <= valid_until
  if (body.valid_from > body.valid_until) {
    throw new Error("Coupon validity end must be after or equal to start.");
  }

  // Uniqueness of coupon code
  const existingCoupon =
    await MyGlobal.prisma.shopping_mall_ai_coupons.findFirst({
      where: {
        code: body.code,
      },
    });
  if (existingCoupon !== null) {
    throw new Error("Coupon code already exists.");
  }

  // Audit fields
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());

  // Create new coupon
  const created = await MyGlobal.prisma.shopping_mall_ai_coupons.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_ai_seller_id: body.shopping_mall_ai_seller_id ?? null,
      shopping_mall_ai_product_id: body.shopping_mall_ai_product_id ?? null,
      shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id ?? null,
      code: body.code,
      type: body.type,
      value: body.value,
      min_order_value: body.min_order_value ?? null,
      max_usage: body.max_usage,
      max_usage_per_customer: body.max_usage_per_customer,
      valid_from: body.valid_from,
      valid_until: body.valid_until,
      stackable: body.stackable,
      status: "active",
      created_at: now,
      updated_at: now,
    },
  });

  // Map DB result to API structure (all date fields are strings, no Date type used)
  return {
    id: created.id,
    shopping_mall_ai_seller_id: created.shopping_mall_ai_seller_id ?? null,
    shopping_mall_ai_product_id: created.shopping_mall_ai_product_id ?? null,
    shopping_mall_ai_channel_id: created.shopping_mall_ai_channel_id ?? null,
    code: created.code,
    type: created.type,
    value: created.value,
    min_order_value: created.min_order_value ?? null,
    max_usage: created.max_usage,
    max_usage_per_customer: created.max_usage_per_customer,
    valid_from: created.valid_from,
    valid_until: created.valid_until,
    stackable: created.stackable,
    status: created.status,
    created_at: created.created_at,
    updated_at: created.updated_at,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
