import { IShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiShipment";
import { IPageIShoppingMallAiShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiShipment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Provides advanced search and pagination over the list of shipments assigned
 * to the given order. Using the orderId path parameter to restrict the search
 * scope, this endpoint calls the shopping_mall_ai_shipments table matching
 * shipmentStatus, provider, creation time, or other allowed filters as set in
 * the IRequest DTO. Sorting and limit/offset or cursor-based pagination are
 * supported, following standard search patterns.
 *
 * Only the order owner, assigned seller, or platform admin may invoke this API.
 * Detailed query options are designed for contact center operators as well as
 * customers checking specific shipment events.
 *
 * Paginated output ensures clients can manage orders with dozens of shipment
 * events effectively without retrieving all at once. The underlying request DTO
 * must match the current shipment search schema, tied to audit and compliance
 * reporting for all search operations.
 *
 * @param props - Provider props (seller, orderId, body)
 * @param props.seller - Authenticated seller JWT
 * @param props.orderId - Target order id for shipment pagination
 * @param props.body - Filtering, pagination, and sorting options
 * @returns Paginated shipments filtered for the specific order and permitted
 *   seller.
 * @throws {Error} If order does not exist or seller is not assigned to any item
 *   in the order.
 */
export async function patch__shopping_mall_ai_seller_orders_$orderId_shipments(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingMallAiShipment.IRequest;
}): Promise<IPageIShoppingMallAiShipment> {
  const { seller, orderId, body } = props;

  // Authorization - seller must have at least one product in the order
  const orderItems =
    await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
      where: { shopping_mall_ai_order_id: orderId },
      select: { shopping_mall_ai_product_id: true },
    });
  if (!orderItems.length) throw new Error("Order not found");

  const productIds = orderItems.map((x) => x.shopping_mall_ai_product_id);
  const countSellerProducts =
    await MyGlobal.prisma.shopping_mall_ai_products.count({
      where: { id: { in: productIds }, shopping_mall_ai_seller_id: seller.id },
    });
  if (!countSellerProducts)
    throw new Error("Unauthorized: seller not assigned to this order");

  // Pagination - strong branding
  const page = typia.assert<
    number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "uint32" }>
  >(body.page ?? 1);
  const limit = typia.assert<
    number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "uint32" }>
  >(body.limit ?? 20);
  const skip = (page - 1) * limit;

  const where = {
    shopping_mall_ai_order_id: orderId,
    ...(body.status !== undefined &&
      body.status !== null && { status: body.status }),
    ...(body.provider !== undefined &&
      body.provider !== null && { provider: body.provider }),
    ...((body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && { gte: body.created_from }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && { lte: body.created_to }),
          },
        }
      : {}),
  };

  const allowedSort = ["created_at", "updated_at", "status"];
  const sortField = allowedSort.includes(body.sort_by ?? "")
    ? body.sort_by!
    : "created_at";
  const sortOrder = body.sort_order === "asc" ? "asc" : "desc";

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_shipments.findMany({
      where,
      orderBy: { [sortField]: sortOrder },
      skip,
      take: limit,
      select: {
        id: true,
        shopping_mall_ai_order_id: true,
        status: true,
        tracking_number: true,
        provider: true,
        created_at: true,
        updated_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_shipments.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: typia.assert<
        number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{ format: "uint32" }>
      >(total),
      pages: typia.assert<
        number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{ format: "uint32" }>
      >(Math.ceil(total / limit)),
    },
    data: rows.map((row) => ({
      id: row.id,
      shopping_mall_ai_order_id: row.shopping_mall_ai_order_id,
      status: row.status,
      tracking_number: row.tracking_number ?? null,
      provider: row.provider ?? null,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    })),
  };
}

