/**
 * Provides advanced search and pagination over the list of shipments assigned
 * to the given order.
 *
 * Using the orderId path parameter to restrict the search scope, this endpoint
 * searches the shopping_mall_ai_shipments table, filtering with shipment
 * status, provider, creation timeframe, and allows sorting/pagination per the
 * IRequest DTO. Returns paginated, filtered shipment results for the specified
 * order. Only callable by platform admins.
 *
 * @param props - Admin: Admin authentication payload orderId: Unique identifier
 *   of the order whose shipments are being searched body: Search criteria
 *   (status/provider/sort/date range/page/limit)
 * @returns Paginated and filtered shipments for the given order
 * @throws {Error} If the orderId does not exist or is invalid
 */
export async function patch__shopping_mall_ai_admin_orders_$orderId_shipments(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingMallAiShipment.IRequest;
}): Promise<IPageIShoppingMallAiShipment> {
  const { admin, orderId, body } = props;

  // 1. Validate order existence
  const orderExists = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: { id: true },
  });
  if (!orderExists) throw new Error("Order not found");

  // 2. Pagination: page/limit
  const pageRaw = body.page && body.page > 0 ? body.page : 1;
  const limitRaw = body.limit && body.limit > 0 ? body.limit : 20;
  // Safe-assert for pagination type compliance
  const page = typia.assert<IPage.IPagination["current"]>(pageRaw);
  const limit = typia.assert<IPage.IPagination["limit"]>(limitRaw);
  const skip = (page - 1) * limit;

  // 3. Build where object inline
  const where = {
    shopping_mall_ai_order_id: orderId,
    ...(body.status ? { status: body.status } : {}),
    ...(body.provider ? { provider: body.provider } : {}),
    ...(body.created_from || body.created_to
      ? {
          created_at: {
            ...(body.created_from
              ? { gte: toISOStringSafe(body.created_from) }
              : {}),
            ...(body.created_to
              ? { lte: toISOStringSafe(body.created_to) }
              : {}),
          },
        }
      : {}),
  };

  // 4. Compose orderBy only from allowed fields
  const allowedSort = ["created_at", "updated_at"] as const;
  const sortBy = allowedSort.includes(body.sort_by as any)
    ? body.sort_by
    : "created_at";
  const sortOrder = body.sort_order === "asc" ? "asc" : "desc";
  const orderBy = { [sortBy!]: sortOrder } as const;

  // 5. Query data and total count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_shipments.findMany({
      where,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_shipments.count({ where }),
  ]);

  // 6. Map rows to DTO (normalize all date fields)
  const data: IShoppingMallAiShipment[] = rows.map((row) => ({
    id: row.id,
    shopping_mall_ai_order_id: row.shopping_mall_ai_order_id,
    status: row.status,
    tracking_number: row.tracking_number ?? null,
    provider: row.provider ?? null,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));

  const pages = limit > 0 ? Math.ceil(total / limit) : 0;
  // 7. Pagination object with typia-assert for strict compliance
  const pagination = typia.assert<IPage.IPagination>({
    current: page,
    limit: limit,
    records: total,
    pages: pages,
  });

  return {
    pagination,
    data,
  };
}

