import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IShoppingMallAiCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCartItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Update a specific item in a shopping cart.
 *
 * Update an existing cart item (e.g., change quantity, option) referenced by
 * cartId and cartItemId. This applies only to the item in the identified cart,
 * allowing precise changes to quantity or product variant. Referential
 * integrity and inventory validation are enforced.
 *
 * Only the cart owner may modify items. Requests that attempt illegal changes
 * (invalid quantity, option not belonging to product, etc.) will return errors.
 * Checks ensure the cart and item exist and are linked.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request
 * @param props.cartId - The shopping cart containing the item to be updated
 * @param props.cartItemId - The unique identifier of the item to update
 * @param props.body - The fields for updating (quantity and/or product option)
 * @returns The updated cart item with all fields populated
 * @throws {Error} When the cart item is not found, ownership is invalid, the
 *   option is invalid, the quantity is out of bounds, or the inventory is
 *   insufficient
 */
export async function put__shopping_mall_ai_customer_carts_$cartId_cartItems_$cartItemId(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  cartItemId: string & tags.Format<"uuid">;
  body: IShoppingMallAiCartItem.IUpdate;
}): Promise<IShoppingMallAiCartItem> {
  const { customer, cartId, cartItemId, body } = props;

  // 1. Lookup cart item with relations
  const cartItem = await MyGlobal.prisma.shopping_mall_ai_cart_items.findUnique(
    {
      where: { id: cartItemId },
      include: {
        cart: true,
        product: true,
      },
    },
  );
  if (!cartItem || cartItem.shopping_mall_ai_cart_id !== cartId) {
    throw new Error("Cart item not found in specified cart.");
  }
  if (
    !cartItem.cart ||
    cartItem.cart.shopping_mall_ai_customer_id !== customer.id
  ) {
    throw new Error("You are not authorized to update this cart item.");
  }
  if (body.quantity <= 0) {
    throw new Error("Quantity must be greater than zero");
  }

  // Validate product option if present
  let optionId: (string & tags.Format<"uuid">) | null =
    body.shopping_mall_ai_product_option_id !== undefined
      ? body.shopping_mall_ai_product_option_id
      : (cartItem.shopping_mall_ai_product_option_id ?? null);
  if (optionId !== null) {
    const option =
      await MyGlobal.prisma.shopping_mall_ai_product_options.findUnique({
        where: { id: optionId },
      });
    if (
      !option ||
      option.shopping_mall_ai_product_id !==
        cartItem.shopping_mall_ai_product_id
    ) {
      throw new Error("Invalid product option for this cart item");
    }
  }

  // Inventory check
  const inventory =
    await MyGlobal.prisma.shopping_mall_ai_inventories.findFirst({
      where: {
        shopping_mall_ai_product_id: cartItem.shopping_mall_ai_product_id,
        shopping_mall_ai_product_option_id: optionId,
      },
    });
  if (!inventory) throw new Error("No inventory record found");
  const available = inventory.quantity - inventory.reserved_quantity;
  if (body.quantity > available)
    throw new Error("Requested quantity exceeds inventory");

  // Update cart item
  const updated = await MyGlobal.prisma.shopping_mall_ai_cart_items.update({
    where: { id: cartItemId },
    data: {
      quantity: body.quantity,
      shopping_mall_ai_product_option_id: optionId,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  return {
    id: updated.id,
    shopping_mall_ai_cart_id: updated.shopping_mall_ai_cart_id,
    shopping_mall_ai_product_id: updated.shopping_mall_ai_product_id,
    shopping_mall_ai_product_option_id:
      updated.shopping_mall_ai_product_option_id ?? undefined,
    quantity: updated.quantity,
    added_at: toISOStringSafe(updated.added_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

