/**
 * Updates file metadata for a shopping mall file asset by fileId.
 *
 * Only admin users can use this operation. Permits partial update of only the
 * following fields: original_name, actor_type, actor_id, and deleted_at (for
 * soft delete). Attempting to update immutable fields will result in an error.
 * All changes are logged in the audit trail (before/after diff including
 * timestamp normalization; never Date instances).
 *
 * @param props - Request arguments
 * @param props.admin - The authenticated admin user
 * @param props.fileId - The file metadata record UUID to update
 * @param props.body - The update payload (editable fields only)
 * @returns The updated file metadata record with all fields normalized
 * @throws {Error} If forbidden fields are present or file does not exist
 */
export async function put__shopping_mall_ai_admin_files_$fileId(props: {
  admin: AdminPayload;
  fileId: string & tags.Format<"uuid">;
  body: IShoppingMallAiFile.IUpdate;
}): Promise<IShoppingMallAiFile> {
  const { admin, fileId, body } = props;
  // Only allow updating original_name, actor_type, actor_id, deleted_at
  const allowed = ["original_name", "actor_type", "actor_id", "deleted_at"];
  for (const key of Object.keys(body)) {
    if (!allowed.includes(key)) {
      throw new Error(`Forbidden to update immutable field: ${key}`);
    }
  }
  // Fetch previously existing record for diff
  const prev = await MyGlobal.prisma.shopping_mall_ai_files.findUnique({
    where: { id: fileId },
  });
  if (!prev) throw new Error("File not found");
  // Only include provided fields (never mutate others)
  const updates = {
    ...(body.original_name !== undefined
      ? { original_name: body.original_name }
      : {}),
    ...(body.actor_type !== undefined ? { actor_type: body.actor_type } : {}),
    ...(body.actor_id !== undefined ? { actor_id: body.actor_id } : {}),
    ...(body.deleted_at !== undefined ? { deleted_at: body.deleted_at } : {}),
  };
  const updated = await MyGlobal.prisma.shopping_mall_ai_files.update({
    where: { id: fileId },
    data: updates,
  });
  // Write audit log (before/after with date normalization, no Date type anywhere)
