    data: rows.map((prod) => ({
      id: prod.id,
      title: prod.title,
      price: prod.price,
      status: prod.status,
      sku: prod.sku,
      shopping_mall_ai_product_category_id:
        prod.shopping_mall_ai_product_category_id,
    })),
  });
