  body: IShoppingMallAiProductOption.IRequest;
}): Promise<IPageIShoppingMallAiProductOption> {
  const { seller, body } = props;

  // Pagination controls
  let page = body.page ?? 1;
  let limit = body.limit ?? 20;
  if (!Number.isFinite(page) || page < 1) page = 1;
  if (!Number.isFinite(limit) || limit < 1) limit = 20;
  if (limit > 100) limit = 100;
  const skip = (page - 1) * limit;

  // Get all product IDs owned by seller (enforce visibility)
