  const sellerProductIds = ownedProducts.map((row) => row.id);

  if (!sellerProductIds.length) {
    return {
      pagination: {
        current: page,
        limit,
        records: 0,
        pages: 0,
      },
      data: [],
    };
  }

  // Build complex where condition
  const where = {
    shopping_mall_ai_product_id: { in: sellerProductIds },
    ...(body.shopping_mall_ai_product_id !== undefined &&
      body.shopping_mall_ai_product_id !== null && {
        shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
      }),
    ...(body.name !== undefined &&
      body.name !== null &&
      body.name.length > 0 && {
        name: { contains: body.name, mode: "insensitive" as const },
      }),
    ...(body.value !== undefined &&
      body.value !== null &&
      body.value.length > 0 && {
        value: { contains: body.value, mode: "insensitive" as const },
      }),
    ...(body.option_sku !== undefined &&
      body.option_sku !== null &&
      body.option_sku.length > 0 && {
        option_sku: { contains: body.option_sku, mode: "insensitive" as const },
