              body.created_at_from !== null && { gte: body.created_at_from }),
            ...(body.created_at_to !== undefined &&
              body.created_at_to !== null && { lte: body.created_at_to }),
          },
        }
      : {}),
  };

  // Fetch paginated result and total
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_product_options.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
      select: {
        id: true,
        shopping_mall_ai_product_id: true,
        name: true,
        value: true,
        option_sku: true,
        created_at: true,
        updated_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_product_options.count({ where }),
  ]);

  // Map result converting Date to string & tags.Format<'date-time'>
  const data: IShoppingMallAiProductOption[] = rows.map((opt) => ({
    id: opt.id,
    shopping_mall_ai_product_id: opt.shopping_mall_ai_product_id,
    name: opt.name,
    value: opt.value,
    option_sku: opt.option_sku,
    created_at: toISOStringSafe(opt.created_at),
    updated_at: toISOStringSafe(opt.updated_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
