/**
 * 리스트 및 모든 쇼핑카트의 페이지네이션 조회 (관리자/분석용).
 *
 * 이 엔드포인트는 시스템에 등록된 모든 쇼핑카트를 관리자 권한으로 페이징하여 반환합니다. 고객/판매자 게스트 구분 없이 전체 데이터를
 * 조회하며, 민감 데이터 보호를 위해 반드시 어드민 인증이 필요합니다.
 *
 * Page, limit 매개변수가 따로 없으므로 기본 1페이지, 100개 단위로 페이징 처리됩니다. 관련 cart_items 및
 * cart_sessions 정보는 포함되지 않으며, 추가 엔드포인트로 별도 조회 가능합니다.
 *
 * @param props - 요청 속성
 * @param props.admin - 인증된 관리자 페이로드
 * @returns 페이징된 카트 요약 목록
 * @throws {Error} 인증되지 않은 경우 또는 권한 없는 접근 시
 */
export async function get__shopping_mall_ai_admin_carts(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiCart> {
  const DEFAULT_PAGE = 1;
  const DEFAULT_LIMIT = 100;
  const current = DEFAULT_PAGE;
  const limit = DEFAULT_LIMIT;
  const skip = (current - 1) * limit;

  const [total, rows] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_carts.count(),
    MyGlobal.prisma.shopping_mall_ai_carts.findMany({
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
  ]);

  const data = rows.map((row) => ({
    id: row.id,
    shopping_mall_ai_customer_id: row.shopping_mall_ai_customer_id ?? undefined,
    shopping_mall_ai_seller_id: row.shopping_mall_ai_seller_id ?? undefined,
    shopping_mall_ai_channel_id: row.shopping_mall_ai_channel_id,
    shopping_mall_ai_section_id: row.shopping_mall_ai_section_id,
    updated_at: toISOStringSafe(row.updated_at),
    created_at: toISOStringSafe(row.created_at),
  }));
  const pages = Math.ceil(total / limit);
  return {
    pagination: {
      current,
      limit,
      records: total,
      pages,
    },
    data,
  };
}

