import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Search and filter all shopping carts in the system with advanced filtering
 * (admin/analytics).
 *
 * This endpoint allows administrators to search across all shopping carts in
 * the platform's database, supporting advanced filtering by customer, channel,
 * creation/update time windows, seller, or cart section. It supports
 * pagination, sorts results by recent activity (updated_at desc), and enables
 * business analytics on cart abandonment or multi-merchant activity.
 *
 * Note: Only admins are authorized to access this function. If the admin is not
 * active, a forbidden error is thrown.
 *
 * @param props - Request parameters
 * @param props.admin - Authenticated admin user payload
 * @param props.body - Search criteria and pagination control
 * @returns Paginated, filtered list of shopping carts with pagination meta-data
 * @throws {Error} If the admin is not active or not found
 */
export async function patch__shopping_mall_ai_admin_carts(props: {
  admin: AdminPayload;
  body: IShoppingMallAiCart.IRequest;
}): Promise<IPageIShoppingMallAiCart> {
  const { admin, body } = props;

  // Authorization check for admin (throws if invalid)
  const adminRecord = await MyGlobal.prisma.shopping_mall_ai_admins.findFirst({
    where: { id: admin.id, is_active: true },
  });
  if (!adminRecord) throw new Error("Forbidden: admin inactive or not found");

  // Pagination parameters with reasonable defaults
  const page = body.page && body.page >= 1 ? body.page : 1;
  const limit = body.limit && body.limit >= 1 ? body.limit : 20;
  const skip = (page - 1) * limit;

  const where = {
    ...(body.shopping_mall_ai_customer_id !== undefined &&
      body.shopping_mall_ai_customer_id !== null && {
        shopping_mall_ai_customer_id: body.shopping_mall_ai_customer_id,
      }),
    ...(body.shopping_mall_ai_seller_id !== undefined &&
      body.shopping_mall_ai_seller_id !== null && {
        shopping_mall_ai_seller_id: body.shopping_mall_ai_seller_id,
      }),
    ...(body.shopping_mall_ai_channel_id !== undefined &&
      body.shopping_mall_ai_channel_id !== null && {
        shopping_mall_ai_channel_id: body.shopping_mall_ai_channel_id,
      }),
    ...(body.shopping_mall_ai_section_id !== undefined &&
      body.shopping_mall_ai_section_id !== null && {
        shopping_mall_ai_section_id: body.shopping_mall_ai_section_id,
      }),
    ...((body.created_at_from !== undefined ||
      body.created_at_to !== undefined) && {
      created_at: {
        ...(body.created_at_from !== undefined && {
          gte: body.created_at_from,
        }),
        ...(body.created_at_to !== undefined && { lte: body.created_at_to }),
      },
    }),
    ...((body.updated_at_from !== undefined ||
      body.updated_at_to !== undefined) && {
      updated_at: {
        ...(body.updated_at_from !== undefined && {
          gte: body.updated_at_from,
        }),
        ...(body.updated_at_to !== undefined && { lte: body.updated_at_to }),
      },
    }),
  };

  // Fetch matching carts and total count concurrently
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_carts.findMany({
      where,
      orderBy: { updated_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_carts.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((cart) => ({
      id: cart.id,
      shopping_mall_ai_customer_id:
        cart.shopping_mall_ai_customer_id ?? undefined,
      shopping_mall_ai_seller_id: cart.shopping_mall_ai_seller_id ?? undefined,
      shopping_mall_ai_channel_id: cart.shopping_mall_ai_channel_id,
      shopping_mall_ai_section_id: cart.shopping_mall_ai_section_id,
      updated_at: toISOStringSafe(cart.updated_at),
      created_at: toISOStringSafe(cart.created_at),
    })),
  };
}

