 * Completely removes a shopping cart by its cartId. All dependent records
 * (items, sessions) are cascade deleted per Prisma schema. Only the owner
 * (customer) may delete a cart. Attempts to delete a cart that does not exist
 * or is not owned by the user will return an error. This action is
 * irreversible.
 *
 * @param props - The request properties.
 * @param props.customer - Authenticated customer performing the deletion.
 * @param props.cartId - Unique identifier of the cart to delete (UUID).
 * @returns Void
 * @throws {Error} If the cart does not exist or is not owned by the customer
 */
export async function delete__shopping_mall_ai_customer_carts_$cartId(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, cartId } = props;
  // Step 1: Look up the cart (must exist)
  const cart = await MyGlobal.prisma.shopping_mall_ai_carts.findUnique({
    where: { id: cartId },
