  if (!cart) throw new Error("Cart not found");
  // Step 2: Auth check (only owner/customer can delete)
  if (cart.shopping_mall_ai_customer_id !== customer.id)
    throw new Error("Forbidden: not the owner of this cart");
  // Step 3: Delete the cart (cascade by schema setup)
  await MyGlobal.prisma.shopping_mall_ai_carts.delete({
    where: { id: cartId },
