export async function post__shopping_mall_ai_admin_orders(props: {
  admin: AdminPayload;
  body: IShoppingMallAiOrder.ICreate;
}): Promise<IShoppingMallAiOrder> {
  const { admin, body } = props;

  if (!admin || admin.type !== "admin")
