/**
 * Provides advanced search and pagination over the list of shipments assigned
 * to the given order.
 *
 * Using the orderId path parameter to restrict the search scope, this endpoint
 * calls the shopping_mall_ai_shipments table matching shipment status,
 * provider, creation time, or other allowed filters as set in the IRequest DTO.
 * Sorting and limit/offset or cursor-based pagination are supported. Only the
 * order owner may invoke this API (ownership is enforced).
 *
 * @param props -
 * @param props.customer Authenticated customer (must own the order to access)
 * @param props.orderId Unique identifier of the order whose shipments are being
 *   searched.
 * @param props.body Criteria for filtering/order/paging of order's shipments.
 * @returns Paginated and filtered list of shipments for the given order, with
 *   proper type branding on data and pagination.
 * @throws {Error} If the order does not exist or is not owned by the customer.
 */
export async function patch__shopping_mall_ai_customer_orders_$orderId_shipments(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingMallAiShipment.IRequest;
}): Promise<IPageIShoppingMallAiShipment> {
  const { customer, orderId, body } = props;

  // Authorization: Confirm order belongs to this customer
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUniqueOrThrow(
    {
      where: { id: orderId },
      select: { shopping_mall_ai_customer_id: true },
    },
  );
  if (order.shopping_mall_ai_customer_id !== customer.id) {
    throw new Error("Forbidden: Only the order owner may view shipments.");
  }

  // Extract query/pagination/sorting parameters
  const {
    page = 1,
    limit = 20,
    status,
    provider,
    created_from,
    created_to,
    sort_by = "created_at",
    sort_order = "desc",
  } = body;

  // Build where condition
  const where = {
    shopping_mall_ai_order_id: orderId,
    ...(status !== undefined && status !== null ? { status } : {}),
    ...(provider !== undefined && provider !== null ? { provider } : {}),
    ...((created_from !== undefined && created_from !== null) ||
    (created_to !== undefined && created_to !== null)
      ? {
          created_at: {
            ...(created_from !== undefined && created_from !== null
              ? { gte: created_from }
              : {}),
            ...(created_to !== undefined && created_to !== null
              ? { lt: created_to }
              : {}),
          },
        }
      : {}),
  };
  const safePage = Number.isFinite(page) && page > 0 ? page : 1;
  const safeLimit =
    Number.isFinite(limit) && limit > 0 && limit <= 100 ? limit : 20;
  const skip = (safePage - 1) * safeLimit;

  // Fetch data and count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_shipments.findMany({
      where,
      orderBy: { [sort_by]: sort_order },
      skip,
      take: safeLimit,
    }),
    MyGlobal.prisma.shopping_mall_ai_shipments.count({ where }),
  ]);

  // Map/format rows for DTO contract, including strict date branding
  const data = rows.map(
    (row): IShoppingMallAiShipment => ({
      id: row.id,
      shopping_mall_ai_order_id: row.shopping_mall_ai_order_id,
      status: row.status,
      tracking_number: row.tracking_number ?? null,
      provider: row.provider ?? null,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    }),
  );

  // Pagination: brand numbers using typia.assert
  const pagination: IPage.IPagination = {
    current: typia.assert<
      number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "uint32" }>
    >(safePage),
    limit: typia.assert<
      number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "uint32" }>
    >(safeLimit),
    records: typia.assert<
      number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "uint32" }>
    >(total),
    pages: typia.assert<
      number & tags.Type<"int32"> & tags.JsonSchemaPlugin<{ format: "uint32" }>
    >(Math.max(1, Math.ceil(total / safeLimit))),
  };

  return {
    pagination,
    data,
  };
}

