      "Forbidden: seller cannot register shipment for this order",
    );

  // 3. Create shipment (fully typed, all dates ISO string, no Date, no 'as')
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_shipments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_ai_order_id: orderId,
      status: body.status,
      tracking_number: body.tracking_number ?? null,
      provider: body.provider ?? null,
      created_at: now,
      updated_at: now,
    },
    select: {
      id: true,
      shopping_mall_ai_order_id: true,
      status: true,
      tracking_number: true,
      provider: true,
      created_at: true,
      updated_at: true,
    },
  });

