 *
 * Erase (hard delete) a shipment tied to a specific order by exact record
 * identity (orderId + shipmentId). No soft deletion is present, so the database
 * row is removed. Used in admin or high-trust seller support tools to resolve
 * invalid shipments or operational errors.
 *
 * Security & Authorization: Only permitted for trusted actors as enforced by
 * RBAC, with full audit logging. Customers cannot call this endpoint. Related
 * shipment GET endpoints should be used for validation before deletion.
 * Operation is irreversible.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the deletion
 * @param props.orderId - The ID of the parent order containing the shipment
 * @param props.shipmentId - The shipment record ID to remove
 * @returns Void
 * @throws {Error} If shipment or order is not found; or seller does not own the
 *   shipment's order
 */
export async function delete__shopping_mall_ai_seller_orders_$orderId_shipments_$shipmentId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  shipmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, orderId, shipmentId } = props;

  // 1. Fetch the shipment to verify existence and order relationship
  const shipment = await MyGlobal.prisma.shopping_mall_ai_shipments.findUnique({
    where: { id: shipmentId },
    select: {
      id: true,
      shopping_mall_ai_order_id: true,
    },
  });
  if (!shipment) throw new Error("Shipment not found");
  if (shipment.shopping_mall_ai_order_id !== orderId)
    throw new Error("Shipment does not belong to the specified order");

  // 2. Fetch the order and confirm it exists
  const order = await MyGlobal.prisma.shopping_mall_ai_orders.findUnique({
    where: { id: orderId },
    select: { id: true },
  });
  if (!order) throw new Error("Order not found");

  // 3. Confirm the order contains order items that belong to the current seller
  // This protects against a seller deleting a shipment for an order with no items of theirs
  const items = await MyGlobal.prisma.shopping_mall_ai_order_items.findMany({
    where: { shopping_mall_ai_order_id: orderId },
    select: { shopping_mall_ai_product_id: true },
  });
  if (items.length === 0) throw new Error("Order has no items");

  // Check if any product in the order belongs to this seller
  const productIds = items.map((i) => i.shopping_mall_ai_product_id);
  const sellerProducts =
    await MyGlobal.prisma.shopping_mall_ai_products.findMany({
      where: {
        id: { in: productIds },
        shopping_mall_ai_seller_id: seller.id,
      },
      select: { id: true },
    });
  if (sellerProducts.length === 0) {
    throw new Error(
      "Forbidden: Seller does not have permission to delete this shipment.",
    );
  }

  // 4. Perform hard delete
  await MyGlobal.prisma.shopping_mall_ai_shipments.delete({
    where: { id: shipmentId },
  });
}

