 * Permanently delete a deposit (store credit) record from
 * shopping_mall_ai_deposits (admin-only).
 *
 * This deletes a deposit by its id (hard delete), as there is no soft delete
 * column. Only admins are authorized to perform this action. After successful
 * deletion, this function writes an audit/compliance log using the
 * shopping_mall_ai_audit_logs table.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user performing the operation
 * @param props.depositId - The UUID of the deposit entry to delete
 * @returns Void
 * @throws {Error} When the deposit does not exist
 */
export async function delete__shopping_mall_ai_admin_deposits_$depositId(props: {
  admin: AdminPayload;
  depositId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, depositId } = props;

  // 1. Ensure deposit exists
  const deposit = await MyGlobal.prisma.shopping_mall_ai_deposits.findUnique({
    where: { id: depositId },
  });
  if (!deposit) throw new Error("Deposit not found");

  // 2. Hard delete deposit
  await MyGlobal.prisma.shopping_mall_ai_deposits.delete({
    where: { id: depositId },
  });

  // 3. Capture deletion in audit/compliance logs
  await MyGlobal.prisma.shopping_mall_ai_audit_logs.create({
    data: {
      id: v4(),
      entity_type: "deposit",
      entity_id: depositId,
      actor_id: admin.id,
      actor_role: "admin",
      operation: "delete",
      detail: JSON.stringify(deposit),
      occurred_at: toISOStringSafe(new Date()),
      context: null,
      deleted_at: null,
    },
  });
}

