export async function get__shopping_mall_ai_admin_mileagePoints(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiMileagePoint> {
  const { admin } = props;
  // Ensure admin exists and is active
  const dbAdmin = await MyGlobal.prisma.shopping_mall_ai_admins.findFirst({
    where: { id: admin.id, is_active: true },
