 * compliant changes occur in the points ledger.
 *
 * Usage scenarios include correcting misapplied accruals, resolving disputes,
 * or applying business logic corrections after the fact. Audit logging
 * guarantees traceability for all changes. Any attempt to update a missing
 * event returns a clear error, and all successful/failed update attempts are
 * tracked for compliance. Aligns with Promotions/Loyalty database structure.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user (must have valid session)
 * @param props.mileagePointId - Unique identifier of the mileage point event to
 *   update
 * @param props.body - Fields permitted for update (point_type, amount, details,
 *   occurred_at)
 * @returns The updated mileage point event after admin correction
 * @throws {Error} When mileage point event is not found
 */
export async function put__shopping_mall_ai_admin_mileagePoints_$mileagePointId(props: {
  admin: AdminPayload;
  mileagePointId: string & tags.Format<"uuid">;
  body: IShoppingMallAiMileagePoint.IUpdate;
