 * customer.
 *
 * Returns only posts that have not been soft-deleted (deleted_at IS NULL) and
 * belong to the same channel as the customer. Each post includes metadata such
 * as title, timestamps, section, channel, and author nickname (from the
 * customers table). Pagination is fixed at page=1, limit=20 for simplicity in
 * this provider layer; advanced parameters can be added later if needed.
 *
 * @param props - Function parameters
 * @param props.customer - The authenticated customer payload (enforced by
 *   CustomerAuth decorator)
 * @returns Paginated summary information for BBS posts per
 *   IPageIShoppingMallAiBbsPost.ISummary
 * @throws {Error} If database or infrastructure issues prevent operation
 */
export async function get__shopping_mall_ai_customer_bbsPosts(props: {
  customer: CustomerPayload;
}): Promise<IPageIShoppingMallAiBbsPost.ISummary> {
  const { customer } = props;
  const page = 1 as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;
  const limit = 20 as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;
  const offset = (page - 1) * limit;

  // Fetch visible posts for customer's channel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_bbs_posts.findMany({
      where: {
        deleted_at: null,
        shopping_mall_ai_channel_id: customer.shopping_mall_ai_channel_id,
      },
      orderBy: { created_at: "desc" },
      skip: offset,
      take: limit,
      select: {
        id: true,
        title: true,
        created_at: true,
        updated_at: true,
        shopping_mall_ai_section_id: true,
        shopping_mall_ai_channel_id: true,
        shopping_mall_ai_customer_id: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_bbs_posts.count({
      where: {
        deleted_at: null,
        shopping_mall_ai_channel_id: customer.shopping_mall_ai_channel_id,
      },
    }),
  ]);

  // Batch load author nicknames
  const authorIds: (string & tags.Format<"uuid">)[] = Array.from(
    new Set(rows.map((row) => row.shopping_mall_ai_customer_id)),
  );
