 *   happen)
 */
export async function get__shopping_mall_ai_admin_bbsPosts(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingMallAiBbsPost.ISummary> {
  const posts = await MyGlobal.prisma.shopping_mall_ai_bbs_posts.findMany({
    where: { deleted_at: null },
    orderBy: { created_at: "desc" },
    take: 100,
    select: {
      id: true,
      title: true,
      created_at: true,
      updated_at: true,
