 * to support up to 3 levels of nested replies, as described in the
 * shopping_mall_ai_bbs_comments model. Only comments with deleted_at null are
 * included in standard queries, ensuring proper content moderation and audit.
 * Allows for paginated results if there are numerous comments.
 *
 * Applicable to customers, sellers, admins for post engagement, moderation, or
 * analytics. Returns threaded comment structures for use in client thread UIs.
 * Honors permissions for content visibility and section/channel context.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user (authorization checked by
 *   decorator)
 * @param props.bbsPostId - The UUID of the BBS post whose comments are
 *   requested
 * @returns Paginated list of comments for the post, as
 *   IPageIShoppingMallAiBbsComment
 * @throws {Error} If the BBS post does not exist
 */
export async function get__shopping_mall_ai_admin_bbsPosts_$bbsPostId_bbsComments(props: {
  admin: AdminPayload;
  bbsPostId: string & tags.Format<"uuid">;
}): Promise<IPageIShoppingMallAiBbsComment> {
  const { admin, bbsPostId } = props;

  // Validate post existence
  const post = await MyGlobal.prisma.shopping_mall_ai_bbs_posts.findUnique({
    where: { id: bbsPostId },
  });
  if (!post) throw new Error("BBS post not found");

  // Pagination settings
  const current = 1;
  const limit = 100;

  // Total record count
  const totalRecords =
    await MyGlobal.prisma.shopping_mall_ai_bbs_comments.count({
      where: {
        shopping_mall_ai_bbs_post_id: bbsPostId,
        deleted_at: null,
      },
    });

  // Fetch comments for the post
  const comments = await MyGlobal.prisma.shopping_mall_ai_bbs_comments.findMany(
    {
      where: {
        shopping_mall_ai_bbs_post_id: bbsPostId,
        deleted_at: null,
      },
      orderBy: { created_at: "asc" },
      skip: 0,
      take: limit,
    },
  );

  // Map all date fields with toISOStringSafe, never use Date type
  const data = comments.map((comment) => ({
    id: comment.id,
    shopping_mall_ai_bbs_post_id: comment.shopping_mall_ai_bbs_post_id,
    shopping_mall_ai_customer_id: comment.shopping_mall_ai_customer_id,
    parent_id: comment.parent_id ?? null,
    body: comment.body,
    ip: comment.ip,
    created_at: toISOStringSafe(comment.created_at),
    updated_at: toISOStringSafe(comment.updated_at),
    deleted_at: comment.deleted_at ? toISOStringSafe(comment.deleted_at) : null,
  }));

  const pages = Math.max(1, Math.ceil(totalRecords / limit));

  return {
    pagination: {
      current,
      limit,
      records: totalRecords,
      pages,
    },
    data,
  };
}

