/**
 * Create a new comment (or reply, up to 3 levels nested) for a BBS forum post.
 *
 * Ensures the target post exists and is not deleted, validates parent reply
 * (must exist, same post, not deleted, and depth max 3). Writes all timestamps
 * as string & tags.Format<'date-time'>. No native Date used. UUIDs generated
 * using v4().
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer (author)
 * @param props.bbsPostId - The UUID of the target BBS post
 * @param props.body - Comment creation content (body & parent_id)
 * @returns Created comment object (all fields populated)
 * @throws {Error} If post/parent do not exist, are (soft) deleted, or nesting >
 *   3
 */
export async function post__shopping_mall_ai_customer_bbsPosts_$bbsPostId_bbsComments(props: {
  customer: CustomerPayload;
  bbsPostId: string & tags.Format<"uuid">;
  body: IShoppingMallAiBbsComment.ICreate;
}): Promise<IShoppingMallAiBbsComment> {
  const { customer, bbsPostId, body } = props;
  const post = await MyGlobal.prisma.shopping_mall_ai_bbs_posts.findFirst({
    where: { id: bbsPostId, deleted_at: null },
  });
  if (!post) throw new Error("BBS post not found or deleted");
  let nestingLevel = 1;
  if (body.parent_id !== undefined && body.parent_id !== null) {
    let parent = await MyGlobal.prisma.shopping_mall_ai_bbs_comments.findFirst({
      where: {
        id: body.parent_id,
        shopping_mall_ai_bbs_post_id: bbsPostId,
        deleted_at: null,
      },
    });
    if (!parent)
      throw new Error("Parent comment not found, deleted, or not in this post");
    while (parent.parent_id !== undefined && parent.parent_id !== null) {
      nestingLevel++;
      if (nestingLevel > 3) break;
      parent = await MyGlobal.prisma.shopping_mall_ai_bbs_comments.findFirst({
        where: {
          id: parent.parent_id,
          shopping_mall_ai_bbs_post_id: bbsPostId,
          deleted_at: null,
        },
      });
      if (!parent) break;
    }
    if (nestingLevel > 3) throw new Error("Maximum reply nesting (3) exceeded");
  }
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_bbs_comments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_ai_bbs_post_id: bbsPostId,
      shopping_mall_ai_customer_id: customer.id,
      parent_id: body.parent_id ?? null,
      body: body.body,
      ip: "0.0.0.0",
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });
  return {
    id: created.id,
    shopping_mall_ai_bbs_post_id: created.shopping_mall_ai_bbs_post_id,
    shopping_mall_ai_customer_id: created.shopping_mall_ai_customer_id,
    parent_id: created.parent_id ?? null,
    body: created.body,
    ip: created.ip,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

