    throw new Error("Comment does not belong to the referenced post");
  // 4. Check author is customer
  if (comment.shopping_mall_ai_customer_id !== customer.id)
    throw new Error("Only the comment author can delete this comment");

  // 5. Soft delete: set deleted_at = now (ISO 8601 string)
  await MyGlobal.prisma.shopping_mall_ai_bbs_comments.update({
    where: { id: bbsCommentId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
}

