/**
 * Create a new product inquiry (Q&A).
 *
 * Allows a customer to create a new product inquiry question in the mall,
 * recording it in the shopping_mall_ai_inquiries table. Requires an
 * authenticated customer; caller may only create on their own behalf. Validates
 * that product exists and seller is valid. Timestamps are auto-generated, and
 * answer fields are set to null. Upon completion, seller notifications and
 * audit logging may be triggered elsewhere.
 *
 * @param props - The request context and body.
 * @param props.customer - Authenticated customer payload (authorization must
 *   pass CustomerAuth).
 * @param props.body - Fields required to create a new inquiry
 *   (IShoppingMallAiInquiry.ICreate).
 * @returns The newly created inquiry object including auto-generated fields and
 *   default nulls where appropriate.
 * @throws {Error} If the product does not exist, if seller does not exist, or
 *   if the question text is empty.
 */
export async function post__shopping_mall_ai_customer_inquiries(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiInquiry.ICreate;
}): Promise<IShoppingMallAiInquiry> {
  const { customer, body } = props;

  // Validate: Question must not be empty.
  if (!body.question || body.question.trim().length === 0) {
    throw new Error("Question must not be empty");
  }

  // Validate: Product must exist.
  const product = await MyGlobal.prisma.shopping_mall_ai_products.findUnique({
    where: { id: body.shopping_mall_ai_product_id },
    select: { shopping_mall_ai_seller_id: true },
  });
  if (!product) throw new Error("Invalid product id");

  // Validate: Seller must exist.
  const seller = await MyGlobal.prisma.shopping_mall_ai_sellers.findUnique({
    where: { id: product.shopping_mall_ai_seller_id },
    select: { id: true },
  });
  if (!seller) throw new Error("Seller not found for this product");

  // Generate UUID for id (with correct branding) and ISO date for timestamp.
  const inquiryId = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());

  // Create inquiry.
  const created = await MyGlobal.prisma.shopping_mall_ai_inquiries.create({
    data: {
      id: inquiryId,
      shopping_mall_ai_product_id: body.shopping_mall_ai_product_id,
      shopping_mall_ai_customer_id: customer.id,
      shopping_mall_ai_seller_id: product.shopping_mall_ai_seller_id,
      question: body.question,
      is_private: body.is_private,
      answer: null,
      answer_marked_helpful: null,
      created_at: now,
      answered_at: null,
      deleted_at: null,
    },
  });

  // Map to DTO and ensure ALL date/datetime fields are strings with branding.
  return {
    id: created.id,
    shopping_mall_ai_product_id: created.shopping_mall_ai_product_id,
    shopping_mall_ai_customer_id: created.shopping_mall_ai_customer_id,
    shopping_mall_ai_seller_id: created.shopping_mall_ai_seller_id,
    question: created.question,
    is_private: created.is_private,
    answer: created.answer ?? null,
    answer_marked_helpful: created.answer_marked_helpful ?? null,
    created_at: toISOStringSafe(created.created_at),
    answered_at: created.answered_at
      ? toISOStringSafe(created.answered_at)
      : null,
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

