/**
 * Retrieves a paginated list of admin content moderation events.
 *
 * This endpoint provides audit trail visibility into all admin moderation
 * actions, including admin name, content type, action, and exact moderation
 * timestamp. Only accessible by authenticated admins. Used by compliance/audit
 * dashboards.
 *
 * @param props - Request properties
 * @param props.admin - Payload of the authenticated admin (authorization
 *   enforced before logic)
 * @returns Paginated result containing moderation event summaries and page
 *   metadata
 * @throws {Error} If database access fails
 */
export async function get__shopping_mall_ai_admin_contentModerations(props: {
  admin: AdminPayload;
}): Promise<IPageIShoppingContentModeration.ISummary> {
  const page = 1 as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;
  const limit = 50 as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;

  // Auth check is enforced by the decorator: props.admin must be valid

  const [total, moderationRows] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_content_moderations.count(),
    MyGlobal.prisma.shopping_mall_ai_content_moderations.findMany({
      orderBy: { acted_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
      include: {
        moderator: true, // joins to shopping_mall_ai_admins
      },
    }),
  ]);

  const data = moderationRows.map((row) => ({
    id: row.id,
    admin_name: row.moderator.name,
    content_type: row.content_type,
    action: row.action,
    acted_at: toISOStringSafe(row.acted_at),
