/**
 * Advanced search for content moderation logs with pagination and filters.
 *
 * Search and retrieve filtered moderation action logs with advanced pagination,
 * sorting, and complex search criteria, all executing against the
 * shopping_mall_ai_content_moderations table. The request body accepts various
 * search parameters including admin ID, content type, action, time ranges, and
 * free-text queries for detailed audit and compliance requirements.
 *
 * Typically used by super-admins and compliance teams, this endpoint supports
 * rigorous filtering to meet regulatory inquiries, internal reviews, and
 * periodic reporting. Only authorized admins can use this API due to
 * information sensitivity and regulatory requirements.
 *
 * If used as part of bulk investigations, results should reference actions
 * precisely and support drill-down into specific moderation types or time
 * intervals for legal hold, compliance, or investigation.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the search
 * @param props.body - The search and filter criteria for moderation logs
 * @returns Paginated, filtered moderation events as
 *   IPageIShoppingContentModeration
 * @throws {Error} When the requester is not an active admin
 */
export async function patch__shopping_mall_ai_admin_contentModerations(props: {
  admin: AdminPayload;
  body: IShoppingContentModeration.IRequest;
}): Promise<IPageIShoppingContentModeration> {
  const { admin, body } = props;

  // Authorization: ensure admin is active and exists
  const adminRec = await MyGlobal.prisma.shopping_mall_ai_admins.findFirst({
    where: { id: admin.id, is_active: true },
  });
  if (!adminRec)
    throw new Error("Unauthorized: Admin account not found or inactive");

  // Pagination (defaults & strict type conversion)
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;

  // Build dynamic where clause
  const where = {
    ...(body.admin_id !== undefined &&
      body.admin_id !== null && { shopping_mall_ai_admin_id: body.admin_id }),
    ...(body.content_type !== undefined &&
      body.content_type !== null && { content_type: body.content_type }),
    ...(body.action !== undefined &&
      body.action !== null && { action: body.action }),
    ...((body.acted_at_from !== undefined && body.acted_at_from !== null) ||
    (body.acted_at_to !== undefined && body.acted_at_to !== null)
      ? {
          acted_at: {
            ...(body.acted_at_from !== undefined &&
              body.acted_at_from !== null && { gte: body.acted_at_from }),
            ...(body.acted_at_to !== undefined &&
              body.acted_at_to !== null && { lte: body.acted_at_to }),
          },
        }
      : {}),
  };

  // Query DB for data and count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_content_moderations.findMany({
      where,
      orderBy: { acted_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_content_moderations.count({ where }),
  ]);

  // Convert result rows into strict DTOs, converting date fields
  const data: IShoppingContentModeration[] = rows.map((row) => ({
    id: row.id,
    shopping_mall_ai_admin_id: row.shopping_mall_ai_admin_id,
    content_type: row.content_type,
    content_id: row.content_id,
    action: row.action,
    message: row.message ?? null,
    acted_at: toISOStringSafe(row.acted_at),
    restored_at: row.restored_at ? toISOStringSafe(row.restored_at) : null,
  }));

  // Compose pagination (return type requires typia branded ints)
  const pagination = typia.assert<
    { current: number; limit: number; records: number; pages: number } & {
      current: number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>;
      limit: number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>;
      records: number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>;
      pages: number &
        tags.Type<"int32"> &
        tags.JsonSchemaPlugin<{ format: "uint32" }>;
    }
  >({
    current: page,
    limit: limit,
    records: total,
    pages: Math.max(Math.ceil(total / limit), 1),
  });

  return {
    pagination,
    data,
  };
}

