/**
 * Update a content moderation event by its ID as an admin.
 *
 * This function allows an authenticated admin to update an existing moderation
 * event's action, rationale/message, or restoration timestamp. Only the fields
 * specified in IShoppingContentModeration.IUpdate may be modified. The update
 * is persisted in the database and the fully updated moderation record is
 * returned, with ISO 8601-formatted datetime fields.
 *
 * @param props - The request properties for the update operation
 * @param props.admin - The authenticated admin payload (validated via
 *   AdminAuth)
 * @param props.contentModerationId - UUID of the moderation event to update
 * @param props.body - The update fields (action, message, and/or restored_at)
 * @returns The updated moderation event with date fields as ISO8601 strings
 * @throws {Error} If the specified moderation event does not exist
 */
export async function put__shopping_mall_ai_admin_contentModerations_$contentModerationId(props: {
  admin: AdminPayload;
  contentModerationId: string & tags.Format<"uuid">;
  body: IShoppingContentModeration.IUpdate;
}): Promise<IShoppingContentModeration> {
  const { admin, contentModerationId, body } = props;

  // Fetch target moderation event to ensure existence
  const moderation =
    await MyGlobal.prisma.shopping_mall_ai_content_moderations.findUnique({
      where: { id: contentModerationId },
    });
  if (!moderation) throw new Error("Moderation event not found");

  // Update fields: only what was provided in body
  const updated =
    await MyGlobal.prisma.shopping_mall_ai_content_moderations.update({
      where: { id: contentModerationId },
      data: {
        ...(body.action !== undefined ? { action: body.action } : {}),
        ...(body.message !== undefined ? { message: body.message } : {}),
        ...(body.restored_at !== undefined
          ? {
              restored_at:
                body.restored_at === null
                  ? null
                  : toISOStringSafe(body.restored_at),
            }
          : {}),
      },
    });

  return {
    id: updated.id,
    shopping_mall_ai_admin_id: updated.shopping_mall_ai_admin_id,
    content_type: updated.content_type,
    content_id: updated.content_id,
    action: updated.action,
    message: updated.message ?? null,
    acted_at: toISOStringSafe(updated.acted_at),
    restored_at: updated.restored_at
      ? toISOStringSafe(updated.restored_at)
      : null,
  };
}

