import { IShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiFile";
import { IPageIShoppingMallAiFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiFile";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

/**
 * Advanced file search and paginated metadata listing for admin/compliance.
 *
 * Queries file metadata records in shopping_mall_ai_files according to provided
 * filter criteria, supporting advanced search, strict pagination, and
 * compliance requirements.
 *
 * - Supports searching by file name, extension, MIME type, actor type, actor ID,
 *   upload timestamp range, and soft deletion status.
 * - Results are paginated as per page/limit input for operational scalability.
 * - Only accessible by validated admin users for security/compliance.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin performing the operation (must have
 *   permission)
 * @param props.body - Search & filter criteria, including pagination and search
 *   fields
 * @returns Paginated file summary structure with meta for UI/report generation
 * @throws {Error} When admin is not authorized or DB errors occur
 */
export async function patch__shopping_mall_ai_admin_files(props: {
  admin: AdminPayload;
  body: IShoppingMallAiFile.IRequest;
}): Promise<IPageIShoppingMallAiFile.ISummary> {
  const { admin, body } = props;
  // Authorization: admin prop is pre-validated

  // Pagination defaults
  const page: number =
    body.page !== undefined && body.page !== null ? body.page : 1;
  const limit: number =
    body.limit !== undefined && body.limit !== null ? body.limit : 20;

  // Build Prisma where clause based on provided filters
  const where = {
    ...(body.original_name !== undefined &&
      body.original_name !== null && {
        original_name: {
          contains: body.original_name,
          mode: "insensitive" as const,
        },
      }),
    ...(body.extension !== undefined &&
      body.extension !== null && {
        extension: { equals: body.extension },
      }),
    ...(body.mime_type !== undefined &&
      body.mime_type !== null && {
        mime_type: { equals: body.mime_type },
      }),
    ...(body.actor_type !== undefined &&
      body.actor_type !== null && {
        actor_type: { equals: body.actor_type },
      }),
    ...(body.actor_id !== undefined &&
      body.actor_id !== null && {
        actor_id: body.actor_id,
      }),
    ...((body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && {
                gte: body.created_from,
              }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && {
                lte: body.created_to,
              }),
          },
        }
      : {}),
    ...(body.deleted === true
      ? { deleted_at: { not: null } }
      : body.deleted === false
        ? { deleted_at: null }
        : {}),
  };

  // Run queries in parallel for performance
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_files.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_files.count({ where }),
  ]);

  // Transform DB results to ISummary array with ISO date strings
  const data: IShoppingMallAiFile.ISummary[] = rows.map((row) => ({
    id: row.id,
    original_name: row.original_name,
    uri: row.uri,
    extension: row.extension,
    mime_type: row.mime_type,
    size: row.size,
    hash: row.hash,
    created_at: toISOStringSafe(row.created_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  // Compute pagination info
  const pages = Math.max(1, Math.ceil(total / limit));
  const pagination = {
    current: page,
    limit,
    records: total,
    pages,
  };

  return {
    pagination,
    data,
  };
}

