/**
 * Update file metadata by fileId (shopping_mall_ai_files).
 *
 * Update file metadata for a file asset given its unique fileId. This operation
 * updates atomically allowed fields such as actor_type/id, original_name, or
 * soft deletion (deleted_at).
 *
 * Only the following fields can be updated: original_name, actor_type,
 * actor_id, deleted_at. Attempting to update other fields (uri, hash,
 * mime_type, extension, size, id, created_at) is forbidden and will throw an
 * error.
 *
 * All changes are logged in the audit trail for full traceability, with
 * date-type fields normalized to string & tags.Format<'date-time'>.
 *
 * @param props - Request arguments
 * @param props.admin - The authenticated admin user
 * @param props.fileId - Unique ID of file metadata record to update
 * @param props.body - Partial update data for the file metadata record (allowed
 *   fields only)
 * @returns Updated file metadata after modifications are applied.
 * @throws {Error} If forbidden fields are present or file does not exist
 */
export async function put__shopping_mall_ai_admin_files_$fileId(props: {
  admin: AdminPayload;
  fileId: string & tags.Format<"uuid">;
  body: IShoppingMallAiFile.IUpdate;
}): Promise<IShoppingMallAiFile> {
  const { admin, fileId, body } = props;
  // Only allow updating: original_name, actor_type, actor_id, deleted_at
  const allowed = ["original_name", "actor_type", "actor_id", "deleted_at"];
  for (const key of Object.keys(body)) {
    if (!allowed.includes(key)) {
      throw new Error(`Field '${key}' is immutable and cannot be updated.`);
    }
  }

  // Fetch previous record for before/after diff
  const prev = await MyGlobal.prisma.shopping_mall_ai_files.findUnique({
    where: { id: fileId },
  });
  if (!prev) throw new Error("File not found");

  // Prepare update fields strictly to allowed DTO
  const updated = await MyGlobal.prisma.shopping_mall_ai_files.update({
    where: { id: fileId },
    data: {
      original_name:
        body.original_name !== undefined ? body.original_name : undefined,
      actor_type: body.actor_type !== undefined ? body.actor_type : undefined,
      actor_id: body.actor_id !== undefined ? body.actor_id : undefined,
      deleted_at:
        body.deleted_at !== undefined
          ? body.deleted_at !== null
            ? toISOStringSafe(body.deleted_at)
            : null
          : undefined,
    },
  });

  // Write audit log: before/after fields fully normalized (no Date type remains)
  await MyGlobal.prisma.shopping_mall_ai_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      entity_type: "file",
      entity_id: updated.id,
      actor_id: admin.id,
      actor_role: "admin",
      operation: "update",
      detail: JSON.stringify({
        before: {
          ...prev,
          created_at: toISOStringSafe(prev.created_at),
          deleted_at: prev.deleted_at ? toISOStringSafe(prev.deleted_at) : null,
        },
        after: {
          ...updated,
          created_at: toISOStringSafe(updated.created_at),
          deleted_at: updated.deleted_at
            ? toISOStringSafe(updated.deleted_at)
            : null,
        },
      }),
      occurred_at: toISOStringSafe(new Date()),
      context: null,
      deleted_at: null,
    },
  });

  // Return IShoppingMallAiFile strictly with normalized dates & branding
  return {
    id: updated.id,
    original_name: updated.original_name,
    uri: updated.uri,
    extension: updated.extension,
    mime_type: updated.mime_type,
    size: updated.size,
    hash: updated.hash,
    actor_type: updated.actor_type ?? null,
    actor_id: updated.actor_id ?? null,
    created_at: toISOStringSafe(updated.created_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

