 */
export async function delete__shopping_mall_ai_admin_files_$fileId(props: {
  admin: AdminPayload;
  fileId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, fileId } = props;
  // Retrieve the file record by id; if none, throw error
  const file = await MyGlobal.prisma.shopping_mall_ai_files.findUnique({
    where: { id: fileId },
  });
  if (!file) {
    throw new Error("File not found");
  }

  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  // If already deleted
  if (file.deleted_at) {
