  await MyGlobal.prisma.shopping_mall_ai_files.update({
    where: { id: fileId },
    data: { deleted_at: now },
  });

  // Write audit log
  await MyGlobal.prisma.shopping_mall_ai_audit_logs.create({
    data: {
